"use client";
import LegacyPage from "../components/LegacyPage";

const TITLE = "Averages — Assignment";
const STYLE_CSS = "\n  /* ---------- Shared design system — copied verbatim from the other\n     pages so this reads as the same app. See architecture-decisions.md\n     re: promoting this to an actual shared stylesheet once there's a\n     build step. ---------- */\n  :root {\n    --accent: #d94a2b;\n    --accent-dark: #a8331a;\n    --accent-ring: rgb(from var(--accent) r g b / 0.35);\n    --page-bg-start: #f17b53;\n    --page-bg-end: #930500;\n    --panel-bg: #eaeaec;\n    --panel-inner: #dcdce0;\n    --text-dark: #14151f;\n    --text-muted: #4b4d63;\n    --text-faint: #83849a;\n    --border: #cfcfd6;\n    --window-radius-lg: 22px;\n    --window-radius-md: 14px;\n    --window-radius-sm: 10px;\n    --grade-good: #2f7d54;\n    --grade-mid: #a67a22;\n    --grade-bad: #b6432f;\n    /* A fifth lifecycle color for the \"Returned\" status — a teacher\n       sends the submission back with a comment, usually asking for a\n       revision, without necessarily finalizing a grade. Distinct from\n       every existing use (red/amber/green already carry Missing/\n       Submitted/Graded meanings, and violet isn't used anywhere else\n       in this app), so a returned item can't be visually confused with\n       an ordinary graded one. */\n    --returned: #6a4fae;\n  }\n\n  * { box-sizing: border-box; }\n\n  /* Scrollbars app-wide: a slim, permanently-visible, rounded gray bar\n     sitting slightly inset from the true edge of its scrollable area --\n     like a normal OS/Gmail-style scrollbar, not hidden and not\n     hover-gated. (An earlier hover-only version turned out unreliable:\n     the outer page counts as \"hovered\" almost the entire time you're\n     using it, so it either showed constantly or never, depending on the\n     browser -- not the meaningful hover signal it needed to be.)\n     Scrolling itself always works via wheel/trackpad/touch/keys either\n     way. One universal rule (the `*` selector) so it covers every\n     scrollable element automatically — the outer page scroll, every\n     popup/modal, every internal list — without repeating it per\n     element. (The bottom nav's own horizontal scroll strip is a\n     deliberate exception — see .app-nav-inner further down — that one\n     stays permanently hidden as a mobile overflow safety net.) */\n  * {\n    scrollbar-width: thin;\n    scrollbar-color: rgba(20, 21, 31, 0.28) transparent;\n  }\n  *::-webkit-scrollbar { width: 10px; height: 10px; }\n  *::-webkit-scrollbar-track { background: transparent; }\n  *::-webkit-scrollbar-thumb {\n    background-color: rgba(20, 21, 31, 0.28);\n    border-radius: 999px;\n    border: 2px solid transparent;\n    background-clip: padding-box; /* the transparent border creates the\n      inset gap around the thumb, so it reads as sitting inside the\n      window rather than flush against the very edge */\n  }\n  *::-webkit-scrollbar-thumb:hover { background-color: rgba(20, 21, 31, 0.45); }\n  *::-webkit-scrollbar-corner { background: transparent; }\n\n  /* Declared so the browser themes ITS OWN chrome — scrollbars, the\n\n     overscroll gutter, form controls — against this page rather than\n\n     guessing. Without it Firefox drew a light-theme scrollbar over the\n\n     dark canvas and tinted it (Martin saw it as pink on a blue\n\n     background). LegacyPage's applyStoredTheme() updates both of these\n\n     to match whatever background the user actually saved. */\n\n  html {\n\n    color-scheme: dark;\n\n    background-color: #0c0c0e;\n\n  }\n\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    min-height: 100%;\n    font-family: \"puffin\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  }\n\n  body {\n    height: 100vh; /* fixed, not min -- body itself no longer scrolls */\n    overflow: hidden; /* scrolling now happens inside .page (see below), so\n      the scrollbar sits at the edge of the app's own window/card instead of\n      out at the browser's outer edge, over the wallpaper margin */\n    /* Neutral black instead of a baked-in accent gradient here —\n       2026-09-11, per Martin. This is only ever visible for a split\n       second on reload/navigation, before applyStoredTheme() (or this\n       page's own appearance-reading script) sets the user's actual\n       saved background over it. The old default was the sample\n       red-orange gradient baked into this file, which read as a real\n       glitch flashing in between pages; a neutral black reads as\n       \"still loading\" instead, and matches the app's own Black\n       preset (#0c0c0e) so it's not a color that appears nowhere else\n       in the app. */\n    background-color: #0c0c0e;\n    background-image: none;\n    background-size: cover;\n    background-position: center;\n    background-repeat: no-repeat;\n    padding: 40px 24px 100px;\n    display: flex;\n    justify-content: center;\n  }\n\n  .page {\n    width: 100%;\n    max-width: 980px;\n    align-self: stretch; /* fill body's available height regardless of\n      whatever align-items body declares, so there's a bounded box to\n      scroll within */\n    min-height: 0; /* flexbox gotcha: without this, a flex item won't\n      shrink below its content size, which breaks overflow scrolling */\n    overflow-y: auto; /* the actual scroll happens here -- both cards grow\n      to their natural content height and .page scrolls as a whole */\n    overflow-x: hidden;\n  }\n\n  /* ---------- Top bar — same .back-link convention as /course-home/\n     /course-materials's \"‹ Back\" breadcrumb. ---------- */\n  .back-link {\n    display: inline-flex;\n    align-items: center;\n    gap: 5px;\n    background: none;\n    border: none;\n    color: rgba(255,255,255,0.82);\n    font-weight: 800;\n    font-size: 0.76rem;\n    padding: 0;\n    margin: 0 0 14px 4px;\n    cursor: pointer;\n    font-family: inherit;\n  }\n  .back-link svg { width: 12px; height: 12px; stroke: currentColor; fill: none; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }\n  .back-link:hover { color: #fff; }\n  .back-link:focus-visible { outline: none; text-decoration: underline; }\n\n  .topbar {\n    display: flex;\n    align-items: flex-end;\n    justify-content: space-between;\n    margin: 0 4px 8px;\n    gap: 12px;\n  }\n\n  h1.title {\n    color: #ffffff;\n    font-size: clamp(1.5rem, 3.2vw, 2rem);\n    font-weight: 900;\n    font-style: italic;\n    letter-spacing: -0.01em;\n    margin: 0;\n    transform: skewX(-2deg);\n    display: inline-block;\n  }\n\n  /* ---------- Sub-line — \"Class Name (Linked)\" + \"Gradebook (linked)\"\n     from the draft, laid out as a subtitle row. Both are now real links\n     (Gradebook became one 2026-08-31 once /gradebook existed to\n     point at — previously styled visibly muted/inert, same convention\n     as every other unbuilt nav destination in this app; that treatment\n     is gone now that there's a real destination). ---------- */\n  .assign-sub { display: flex; align-items: center; gap: 8px; margin: 4px 0 18px 2px; flex-wrap: wrap; }\n  .assign-sub-link {\n    background: none;\n    border: none;\n    font-family: inherit;\n    font-weight: 700;\n    font-style: italic;\n    font-size: 0.9rem;\n    color: rgba(255,255,255,0.92);\n    text-decoration: underline;\n    text-underline-offset: 2px;\n    cursor: pointer;\n    padding: 0;\n  }\n  .assign-sub-link:hover { color: #fff; }\n  .assign-sub-link:focus-visible { outline: none; text-decoration-thickness: 2px; }\n  .assign-sub-dot { color: rgba(255,255,255,0.5); font-size: 0.8rem; }\n\n  .profile-menu-wrap { position: relative; flex-shrink: 0; }\n  .profile-btn {\n    width: 42px;\n    height: 42px;\n    border-radius: 50%;\n    background: rgba(255,255,255,0.2);\n    border: 2px solid rgba(255,255,255,0.5);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-weight: 800;\n    font-size: 0.95rem;\n    cursor: pointer;\n    flex-shrink: 0;\n  }\n  .profile-menu {\n    position: absolute;\n    top: calc(100% + 10px);\n    right: 0;\n    min-width: 160px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 25;\n  }\n  .profile-menu-item {\n    display: block;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.86rem;\n    color: var(--text-dark);\n    padding: 9px 12px;\n    cursor: pointer;\n  }\n  .profile-menu-item:hover { background: var(--panel-inner); }\n  .profile-menu-item.signout { color: var(--grade-bad); }\n\n  /* ---------- Two-panel layout — Description+Materials / Submissions,\n     matching the draft's two equal-width white boxes side by side.\n     This grid is capped to the space .page has left (flex: 1;\n     min-height: 0) instead of .page growing to fit both cards' full\n     height, which is what used to let their rounded corners scroll off\n     screen. Fixed again 2026-09-04 (per Martin, \"round corners on\n     scroll on all pages\"): the grid itself no longer scrolls — that\n     just moved the same bug down one level, scrolling both cards as a\n     single unit and cutting off THEIR rounded corners instead (found by\n     scrolling .assign-detail-grid directly and screenshotting — the top\n     of both cards went flat/square mid-scroll). align-items: stretch\n     (not start) so each card fills the grid row's full height, and each\n     .card is its own independently-windowed frame — fixed size, only\n     .card-inner scrolls inside it — same pattern as every single-card\n     page (/calendar, /home, etc.), just one level deeper. ---------- */\n  .assign-detail-grid {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);   /* minmax(0,…): a long file name can't push a card past the page edge (2026-10-04) */\n    gap: 18px;\n    align-items: start;\n  }\n  @media (max-width: 720px) {\n    .assign-detail-grid { grid-template-columns: minmax(0, 1fr); }\n  }\n\n  .card {\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    padding: 6px;\n  }\n  .card-inner {\n    padding: 22px 24px 24px;\n  }\n  .card-inner h2 {\n    font-size: 0.92rem;\n    font-weight: 800;\n    font-style: italic;\n    color: var(--text-dark);\n    margin: 0 0 8px;\n  }\n  .card-inner h2.second { margin-top: 20px; }\n\n  .assign-desc-text { font-size: 0.86rem; line-height: 1.55; color: var(--text-muted); margin: 0; white-space: pre-line; overflow-wrap: anywhere; }\n\n  /* ---------- Attached / submitted file rows — same red/blue/orange\n     PDF/DOCX/PPTX badge colors /course-materials already uses, so\n     a file reads consistently wherever it shows up in the app. ---------- */\n  .material-row { display: flex; align-items: center; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--border); }\n  .material-row:last-child { border-bottom: none; }\n  .material-badge {\n    flex-shrink: 0;\n    width: 30px;\n    height: 30px;\n    border-radius: 7px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-size: 0.58rem;\n    font-weight: 800;\n    letter-spacing: 0.02em;\n  }\n  .material-name { flex: 1; min-width: 0; font-size: 0.82rem; font-weight: 600; color: var(--text-dark); }\n  .assign-empty { font-size: 0.8rem; color: var(--text-faint); font-style: italic; padding: 4px 0; }\n\n  /* ---------- View/Download buttons on an Attached Materials row\n     (2026-08-29, per Martin's request) — no real file content exists in\n     this mock (same as /course-materials), so both open a small\n     info modal rather than actually opening or downloading anything. ---------- */\n  .material-actions { display: flex; gap: 2px; flex-shrink: 0; }\n  .material-icon-btn {\n    width: 28px;\n    height: 28px;\n    border: none;\n    background: none;\n    color: var(--text-faint);\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n  }\n  .material-icon-btn svg { width: 15px; height: 15px; stroke: currentColor; fill: none; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }\n  .material-icon-btn:hover { background: var(--border); color: var(--text-dark); }\n\n  /* ---------- Attached Materials file bars (2026-10-04, per Martin) — the\n     landing page's Connections card: Edit in Canva, Save to cloud, Download.\n     Canva's rules for the button: their icon inside it, always with text. ---------- */\n  .material-row.file-bar { background: var(--panel-inner); border-radius: var(--window-radius-sm); padding: 8px 8px 8px 12px; margin-top: 8px; border-bottom: none; flex-wrap: wrap; row-gap: 8px; }\n  .file-bar .material-name { flex: 1 1 0; min-width: 110px; font-weight: 700; overflow-wrap: anywhere; }   /* buttons drop to their own line only when the name would get squeezed */\n  .file-bar .material-actions { margin-left: auto; align-items: center; gap: 4px; }\n  .canva-mark { width: 20px; height: 20px; flex: none; display: block; border-radius: 50%; background: center / contain no-repeat url(\"data:image/svg+xml;base64,\"); }\n  /* Canva's guidelines: 8px around their icon inside a button. 40px tall, same as every other file-bar button. */\n  .canva-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 40px; box-sizing: border-box; padding: 8px 16px 8px 8px; border: 2px solid var(--border); border-radius: 999px; background: var(--panel-bg); color: var(--text-dark); font-family: inherit; font-size: 0.74rem; font-weight: 800; white-space: nowrap; cursor: pointer; transition: border-color 0.14s ease, transform 0.14s ease; }\n  .canva-btn:hover { border-color: var(--text-dark); transform: translateY(-1px); }\n  .canva-btn.drive-btn { padding: 8px 16px; }   /* text only, same 40px height */\n  .draft-badge.drive { color: #fff; font-size: 0.5rem; font-weight: 900; letter-spacing: 0.02em; }\n  .canva-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .file-bar .material-icon-btn { width: 40px; height: 40px; background: var(--panel-bg); color: var(--text-muted); }\n  .file-bar .material-icon-btn:hover { background: var(--border); color: var(--text-dark); }\n  .file-bar .material-icon-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .tipwrap { position: relative; display: inline-flex; }\n  .tip { position: absolute; bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%); z-index: 5; background: var(--text-dark); color: var(--panel-bg); border-radius: 7px; padding: 4px 8px; font-size: 0.68rem; font-weight: 800; white-space: nowrap; pointer-events: none; opacity: 0; visibility: hidden; transition: opacity 0.14s ease, visibility 0.14s; }\n  .tip::after { content: \"\"; position: absolute; top: 100%; left: 50%; transform: translateX(-50%); border: 5px solid transparent; border-top-color: var(--text-dark); }\n  .tipwrap:hover .tip, .tipwrap:focus-within .tip { opacity: 1; visibility: visible; }\n  .file-menu { position: fixed; z-index: 300; min-width: 224px; max-width: calc(100vw - 16px); background: var(--panel-bg); border: 1px solid var(--border); border-radius: 10px; box-shadow: 0 20px 50px -12px rgba(0,0,0,0.55); padding: 6px; }\n  .file-menu[hidden] { display: none; }\n  .file-menu-label { padding: 4px 10px 8px; font-size: 0.72rem; font-weight: 700; color: var(--text-muted); overflow-wrap: anywhere; }\n  .file-menu-item { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; padding: 8px 10px; border: none; background: none; border-radius: 6px; font-family: inherit; font-size: 0.8rem; font-weight: 700; color: var(--text-dark); text-align: left; }\n  .file-menu-item:disabled { color: var(--text-faint); cursor: default; }\n  .file-menu-item:not(:disabled) { cursor: pointer; }\n  .file-menu-item:not(:disabled):hover, .file-menu-item:not(:disabled):focus-visible { background: var(--panel-inner); outline: none; }\n  .file-menu-item small { display: block; margin-top: 2px; font-size: 0.68rem; font-weight: 700; color: var(--text-faint); }\n  .soon { font-size: 0.66rem; font-weight: 800; color: var(--text-faint); white-space: nowrap; }\n  /* Add Submission: other places to add a file from */\n  .upload-sources { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; margin-top: 12px; }\n  .upload-sources-label { font-size: 0.74rem; font-weight: 700; color: var(--text-muted); margin-right: 2px; }\n  .upload-source { display: inline-flex; align-items: center; gap: 8px; padding: 8px 12px 8px 8px; border: 1px solid var(--border); border-radius: 999px; background: var(--panel-inner); font-family: inherit; font-size: 0.74rem; font-weight: 800; color: var(--text-faint); cursor: default; }\n  .upload-source .canva-mark { width: 16px; height: 16px; opacity: 0.6; }\n  /* Turning in, signed in with Schoology (2026-10-06): the \"Or add from\"\n     buttons work, a picked file says where it came from, and each file shows\n     its own progress while it's turned in. */\n  .upload-source:not(:disabled) { color: var(--text-dark); cursor: pointer; }\n  .upload-source:not(:disabled):hover { background: var(--border); }\n  .upload-source:not(:disabled) .canva-mark { opacity: 1; }\n  .upload-source:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .upload-source[aria-busy=\"true\"] { cursor: progress; opacity: 0.7; }\n  .modal-box .upload-source-note { margin: 8px 0 0; font-size: 0.74rem; font-weight: 700; color: var(--text-muted); line-height: 1.45; }\n  .upload-source-note[hidden], .submit-error[hidden], .upload-picked-progress[hidden], .upload-bar[hidden], .canva-pick[hidden] { display: none; }\n  .upload-source-note a, .submit-error a, .canva-pick-empty a { color: var(--accent-dark); font-weight: 800; text-underline-offset: 2px; }\n  .upload-note-btn { border: none; background: none; padding: 0; font: inherit; font-weight: 800; color: var(--accent-dark); text-decoration: underline; text-underline-offset: 2px; cursor: pointer; }\n  .upload-picked-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }\n  .upload-picked-text .upload-picked-name { flex: none; }\n  .upload-picked-src { font-size: 0.66rem; font-weight: 700; color: var(--text-faint); }\n  .upload-picked-progress { display: flex; align-items: center; gap: 8px; min-width: 0; font-size: 0.68rem; font-weight: 700; color: var(--text-muted); }\n  .upload-progress-text { min-width: 0; overflow-wrap: anywhere; }\n  .upload-bar { flex: 1 1 60px; max-width: 140px; height: 4px; border-radius: 999px; background: var(--border); overflow: hidden; }\n  .upload-bar i { display: block; height: 100%; width: 0; background: var(--accent); transition: width 0.2s ease; }\n  .upload-picked-row.done .upload-picked-progress { color: var(--grade-good); }\n  .upload-picked-row.done .upload-bar i { background: var(--grade-good); }\n  .upload-picked-row.failed .upload-picked-progress { color: var(--grade-bad); }\n  .upload-picked-row.failed .upload-bar { display: none; }\n  .material-icon-btn:disabled, .upload-picker-btn:disabled, .upload-tab:disabled, .modal-btn:disabled { opacity: 0.55; cursor: default; }\n  .modal-box .submit-error { margin: 12px 0 0; font-size: 0.76rem; font-weight: 700; color: var(--grade-bad); line-height: 1.45; }\n  #draftSubProgress { margin-top: 12px; }\n  .canva-pick { margin-top: 10px; padding: 8px; border-radius: var(--window-radius-sm); background: var(--panel-inner); }\n  .canva-pick-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 0 4px 4px; font-size: 0.74rem; font-weight: 800; color: var(--text-dark); }\n  .canva-pick-list { max-height: 216px; overflow-y: auto; }\n  .canva-pick-label { padding: 8px 4px 4px; font-size: 0.64rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.03em; color: var(--text-faint); }\n  .canva-pick-item { display: flex; align-items: center; gap: 10px; width: 100%; padding: 6px; border: none; border-radius: 8px; background: none; font-family: inherit; text-align: left; cursor: pointer; color: var(--text-dark); }\n  .canva-pick-item:hover, .canva-pick-item:focus-visible { background: var(--panel-bg); outline: none; }\n  .canva-pick-thumb { width: 40px; height: 30px; flex: none; border-radius: 5px; background: var(--panel-bg); display: grid; place-items: center; overflow: hidden; }\n  .canva-pick-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }\n  .canva-pick-name { flex: 1; min-width: 0; font-size: 0.78rem; font-weight: 700; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .canva-pick-meta { flex-shrink: 0; font-size: 0.66rem; font-weight: 700; color: var(--text-faint); white-space: nowrap; }\n  .canva-pick-empty { margin: 0; padding: 6px 4px; font-size: 0.76rem; color: var(--text-muted); }\n  .canva-pick .assign-retry { margin: 6px 4px 2px; }\n  .submit-done-head { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }\n  .submit-done-head h3 { margin: 0; }\n  .submit-done-check { width: 28px; height: 28px; flex: none; border-radius: 50%; background: var(--grade-good); display: grid; place-items: center; }\n  .submit-done-check svg { width: 16px; height: 16px; stroke: #fff; fill: none; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }\n  .submit-dropzone.live-drop.dragging { background: var(--panel-inner); color: var(--text-dark); }\n  .rev-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }\n  .rev-main .material-name { flex: none; overflow-wrap: anywhere; }\n  .rev-when { color: var(--text-faint); font-weight: 600; }\n  .rev-snippet { font-size: 0.72rem; color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .submission-latest-tag.late { color: var(--grade-bad); }\n  .submission-latest-tag.draft { color: var(--text-faint); }\n  .rev-size { flex-shrink: 0; font-size: 0.7rem; font-weight: 700; color: var(--text-faint); }\n  .rev-text { margin-top: 12px; padding: 10px 12px; max-height: 240px; overflow-y: auto; border-radius: var(--window-radius-sm); background: var(--panel-inner); font-size: 0.8rem; line-height: 1.5; color: var(--text-dark); white-space: pre-line; overflow-wrap: anywhere; }\n  @media (prefers-reduced-motion: reduce) { .canva-btn, .tip { transition: none; } .canva-btn:hover { transform: none; } }\n\n  /* ---------- Drafts (2026-10-04): Canva edits waiting to be turned in ---------- */\n  .drafts { margin-bottom: 22px; }\n  /* Signed in (2026-10-05) */\n  .drafts-note { margin: 0 0 10px; padding: 10px 12px; border-radius: 10px; background: var(--panel-inner); font-size: 0.8rem; font-weight: 700; color: var(--text-dark); }\n  .drafts-note[hidden] { display: none; }\n  .material-link { color: var(--text-dark); text-decoration: underline; text-underline-offset: 2px; }\n  .material-link:hover { color: var(--accent-dark); }\n  .canva-btn[aria-busy=\"true\"] { opacity: 0.7; cursor: progress; }\n  .assign-retry { margin-left: 6px; border: none; background: none; padding: 0; font: inherit; font-style: normal; font-weight: 800; color: var(--accent-dark); text-decoration: underline; cursor: pointer; }\n  .drafts[hidden] { display: none; }\n  .drafts .material-row.file-bar:first-child { margin-top: 0; }\n  .draft-badge { width: 36px; height: 36px; flex-shrink: 0; border-radius: 7px; background: var(--panel-bg); display: grid; place-items: center; }\n  .draft-text { flex: 1 1 0; min-width: 110px; display: flex; flex-direction: column; gap: 1px; }\n  .draft-text .material-name { flex: none; min-width: 0; }\n  .draft-meta { font-size: 0.68rem; font-weight: 700; color: var(--text-faint); }\n  .draft-submit { border: none; border-radius: 999px; background: var(--accent); color: #fff; font-family: inherit; font-size: 0.74rem; font-weight: 800; min-height: 40px; padding: 8px 18px; cursor: pointer; white-space: nowrap; }\n  .draft-submit:hover { filter: brightness(1.08); }\n  .draft-submit:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .draft-submit:disabled { background: var(--border); color: var(--text-faint); cursor: default; filter: none; }\n  .draft-ghost { position: fixed; z-index: 400; margin: 0; pointer-events: none; box-shadow: 0 18px 40px -14px rgba(0,0,0,0.5); overflow: hidden; background: var(--panel-inner); border-radius: var(--window-radius-sm); }\n  .draft-ghost .material-actions { transform-origin: right center; }\n  .draft-row.leaving { overflow: hidden; }\n  /* ---------- Turning in a draft (2026-10-10): × [Send a Copy ⇅ | Submit], then a step bar ---------- */\n  .draft-row { position: relative; }\n  /* \"Why Canva?\" under a file that opens in Canva although Google Drive is picked (2026-10-10) */\n  .why-btn { margin-top: 2px; padding: 0; border: none; background: none; font: inherit; font-size: 0.68rem; font-weight: 800; color: var(--text-faint); text-decoration: underline; text-underline-offset: 2px; cursor: pointer; }\n  .why-btn:hover, .why-btn[aria-expanded=\"true\"] { color: var(--text-dark); }\n  .why-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); border-radius: 4px; }\n  .why-note { flex: 0 0 100%; margin: 0; padding: 8px 10px; border-radius: 10px; background: var(--panel-bg); font-size: 0.74rem; font-weight: 600; color: var(--text-muted); line-height: 1.45; }\n  .why-note[hidden] { display: none; }\n  .why-note a { color: var(--accent-dark); font-weight: 800; }\n  .ti-acts { gap: 14px; }\n  .ti-x { flex: none; width: 40px; height: 40px; border-radius: 50%; border: none; background: var(--panel-bg); color: var(--text-muted); display: grid; place-items: center; cursor: pointer; }\n  .ti-x svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 2.4; stroke-linecap: round; }\n  .ti-x:hover { color: var(--text-dark); background: var(--border); }\n  .ti-x:disabled { opacity: .5; cursor: default; }\n  .ti-grp { display: inline-flex; align-items: center; gap: 4px; padding: 3px; border-radius: 999px; background: var(--panel-bg); }\n  .ti-pick { height: 36px; display: inline-flex; align-items: center; gap: 8px; padding: 0 10px 0 12px; border: none; border-radius: 999px; background: none; color: var(--text-dark); font: inherit; font-size: 0.76rem; font-weight: 800; cursor: pointer; white-space: nowrap; overflow: hidden; }\n  .ti-pick:hover:not(:disabled) { background: var(--panel-inner); }\n  .ti-pick:disabled { cursor: default; }\n  .ti-t { display: inline-flex; align-items: center; gap: 7px; }\n  .ti-pick svg, .ti-hint svg, .ti-opt svg { stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; flex: none; }\n  .ti-pick .ti-t svg { width: 16px; height: 16px; }\n  .ti-pick .ti-ud { width: 12px; height: 12px; color: var(--text-faint); }\n  .ti-grp .draft-submit { min-height: 36px; padding: 6px 18px; }\n  .draft-submit.ti-main { overflow: hidden; }\n  .ti-x:focus-visible, .ti-pick:focus-visible, .ti-opt:focus-visible, .ti-hint:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .ti-below { flex: 0 0 100%; min-width: 0; display: grid; gap: 8px; padding: 2px 0 2px; }\n  .ti-hint { display: flex; align-items: center; gap: 9px; margin: 0; padding: 8px 10px; border: none; border-radius: 10px; background: transparent; font: inherit; font-size: 0.78rem; font-weight: 700; color: var(--text-dark); text-align: left; line-height: 1.4; }\n  .ti-hint svg { width: 18px; height: 18px; color: var(--text-muted); }\n  button.ti-hint { width: 100%; cursor: pointer; }\n  button.ti-hint:hover:not(:disabled) { background: var(--panel-bg); }\n  .ti-hint .ti-chev { margin-left: auto; width: 14px; height: 14px; color: var(--text-faint); transition: transform .15s ease; }\n  button.ti-hint[aria-expanded=\"true\"] .ti-chev { transform: rotate(90deg); }\n  .ti-access { background: var(--panel-bg); border-radius: 12px; padding: 4px; }\n  .ti-opt { display: grid; grid-template-columns: 16px 22px minmax(0, 1fr); gap: 10px; align-items: start; width: 100%; text-align: left; border: none; background: none; border-radius: 10px; padding: 10px 10px; font: inherit; color: var(--text-dark); cursor: pointer; }\n  .ti-opt:hover:not(:disabled) { background: var(--panel-inner); }\n  .ti-opt:disabled { opacity: .45; cursor: not-allowed; }\n  .ti-opt .ti-ck { width: 15px; height: 15px; margin-top: 2px; visibility: hidden; stroke-width: 2.6; }\n  .ti-opt[aria-checked=\"true\"] .ti-ck { visibility: visible; }\n  .ti-opt > svg:not(.ti-ck) { width: 20px; height: 20px; }\n  .ti-opt b { display: block; font-size: 0.82rem; font-weight: 800; }\n  .ti-opt b + span { display: block; font-size: 0.72rem; font-weight: 600; color: var(--text-muted); margin-top: 2px; line-height: 1.35; }\n  .ti-menu { position: absolute; z-index: 30; width: min(320px, calc(100% - 16px)); background: var(--panel-bg); border-radius: 16px; box-shadow: 0 18px 44px rgba(0, 0, 0, 0.28); padding: 6px; }\n  .ti-paste input { width: 100%; box-sizing: border-box; padding: 9px 12px; border-radius: 10px; border: 1px solid var(--border); background: var(--panel-bg); font: inherit; font-size: 0.8rem; font-weight: 600; color: var(--text-dark); }\n  .ti-paste input:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring); }\n  .ti-prog { padding: 12px 12px 10px; border-radius: 12px; background: var(--panel-bg); display: grid; gap: 10px; }\n  .ti-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; font-size: 0.78rem; font-weight: 800; color: var(--text-dark); }\n  .ti-head small { font-size: 0.7rem; font-weight: 700; color: var(--text-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }\n  .ti-segs { display: flex; gap: 4px; }\n  .ti-seg { min-width: 84px; display: grid; gap: 7px; }\n  .ti-track { position: relative; height: 10px; border-radius: 999px; background: var(--panel-inner); overflow: hidden; }\n  .ti-fill { position: absolute; inset: 0 auto 0 0; width: 0; border-radius: inherit; background: var(--accent); transition: width .3s ease; }\n  .ti-seg.now .ti-fill.ind { width: 100%; background: linear-gradient(90deg, rgb(from var(--accent) r g b / 0.25) 0%, var(--accent) 50%, rgb(from var(--accent) r g b / 0.25) 100%); background-size: 200% 100%; animation: ti-sweep 1.1s linear infinite; }\n  .ti-seg.done .ti-fill { width: 100%; }\n  .ti-seg.fail .ti-fill { width: 100%; background: #c0392b; }\n  .ti-seg.ok .ti-fill { background: #2f9e64; }\n  @keyframes ti-sweep { from { background-position: 200% 0; } to { background-position: 0 0; } }\n  .ti-lab { display: flex; align-items: center; gap: 6px; font-size: 0.68rem; font-weight: 800; color: var(--text-faint); min-width: 0; }\n  .ti-lab span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .ti-lab svg { width: 14px; height: 14px; flex: none; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n  .ti-seg.now .ti-lab, .ti-seg.done .ti-lab { color: var(--text-dark); }\n  .ti-seg.fail .ti-lab { color: #c0392b; }\n  .ti-spin { animation: ti-spin .8s linear infinite; }\n  @keyframes ti-spin { to { transform: rotate(360deg); } }\n  .ti-err { display: flex; align-items: center; gap: 10px; margin: 0; font-size: 0.74rem; font-weight: 700; color: #c0392b; }\n  .ti-err a { color: inherit; }\n  .ti-err button { margin-left: auto; flex: none; border: none; border-radius: 999px; background: var(--accent); color: #fff; font: inherit; font-weight: 800; font-size: 0.72rem; padding: 7px 14px; cursor: pointer; }\n  @media (max-width: 560px) {\n    .ti-acts { width: 100%; gap: 8px; flex-wrap: nowrap; }\n    .ti-acts .ti-x { margin-right: auto; }\n    .ti-grp { min-width: 0; }\n    .ti-pick { min-width: 0; padding: 0 8px 0 10px; }\n    .ti-pick .ti-t { min-width: 0; overflow: hidden; text-overflow: ellipsis; }\n    .ti-grp .draft-submit { padding: 6px 14px; }\n    .ti-seg { min-width: 0; }\n    .ti-seg:not(.now):not(.fail) .ti-lab span { display: none; }\n  }\n  @media (prefers-reduced-motion: reduce) { .ti-seg.now .ti-fill.ind, .ti-spin { animation: none; } }\n  body.potato-mode .ti-seg.now .ti-fill.ind, body.potato-mode .ti-spin { animation: none; }\n  .material-icon-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n\n  /* ---------- Shared small modal — Add Submission and the file-action\n     (View/Download) info both use this one component. ---------- */\n  .modal-overlay {\n    position: fixed;\n    inset: 0;\n    background: rgba(0,0,0,0.55);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    padding: 20px;\n    z-index: 60;\n  }\n  /* Same [hidden]-vs-display:flex specificity tie already caught\n     elsewhere in this app (.edit-fab[hidden] on /home,\n     .view-toggle[hidden] on /course-materials) — without this,\n     the later `display: flex` rule above wins and the overlay stays\n     visible (and intercepts clicks) even with `hidden` set. */\n  .modal-overlay[hidden] { display: none; }\n  .modal-box {\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    box-shadow: 0 30px 70px -20px rgba(0,0,0,0.6);\n    padding: 22px;\n    width: 100%;\n    max-width: 380px;\n  }\n  /* Wider variant for the Add Submission modal only (2026-09-04, per\n     Martin: \"make the assignment submission popup bigger\") -- it now\n     carries tabs, a multi-file list, and the Create tab's rich-text\n     toolbar, so the default 380px (sized for the smaller file-info/\n     submission-preview popups) felt cramped. Added/removed by\n     openAddSubmissionModal()/closeModal() rather than changing\n     .modal-box itself, so every other popup in this app stays the same\n     size it's always been. Still just width:100% under 560px, so it\n     shrinks to fit a narrow viewport the same as .modal-box normally does. */\n  .modal-box.modal-box-lg { max-width: 560px; }\n  /* Wraps the per-file rows in the Submission Preview popup (2026-09-04)\n     -- just spacing, .material-row/.material-badge do the rest. */\n  .modal-file-list { margin-top: 8px; }\n  .modal-box h3 { margin: 0 0 8px; font-size: 1rem; font-weight: 800; font-style: italic; color: var(--text-dark); }\n  .modal-box p { margin: 0; font-size: 0.82rem; color: var(--text-muted); line-height: 1.5; }\n  .modal-file-input {\n    width: 100%;\n    margin-top: 14px;\n    font-size: 0.78rem;\n    color: var(--text-muted);\n  }\n  /* Add Submission — Upload/Create tabs, mirroring the real Schoology\n     upload dialog Martin shared a screenshot of (2026-08-29). */\n  .upload-tabs {\n    display: flex;\n    gap: 4px;\n    margin-top: 14px;\n    border-bottom: 1px solid var(--border);\n  }\n  .upload-tab {\n    background: none;\n    border: none;\n    border-bottom: 2px solid transparent;\n    margin-bottom: -1px;\n    font-family: inherit;\n    font-weight: 800;\n    font-size: 0.76rem;\n    color: var(--text-muted);\n    padding: 6px 10px 9px;\n    cursor: pointer;\n  }\n  .upload-tab:hover { color: var(--text-dark); }\n  .upload-tab.active { color: var(--accent); border-bottom-color: var(--accent); }\n  .upload-tab:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); border-radius: 4px; }\n  .upload-tab-panel { padding-top: 12px; }\n  .upload-tab-desc { font-size: 0.76rem; color: var(--text-muted); margin: 0 0 8px; line-height: 1.45; }\n  .modal-field-label {\n    display: block;\n    margin-top: 16px;\n    font-size: 0.68rem;\n    font-weight: 800;\n    text-transform: uppercase;\n    letter-spacing: 0.03em;\n    color: var(--text-faint);\n  }\n  .modal-textarea {\n    width: 100%;\n    margin-top: 6px;\n    padding: 8px 10px;\n    border-radius: var(--window-radius-sm);\n    border: 1px solid var(--border);\n    background: var(--panel-inner);\n    color: var(--text-dark);\n    font-family: inherit;\n    font-size: 0.78rem;\n    line-height: 1.4;\n    resize: vertical;\n    min-height: 52px;\n    box-sizing: border-box;\n  }\n  .modal-textarea:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .modal-textarea.answer-textarea { min-height: 78px; }\n  /* Upload tab's file picker — the bare native <input type=\"file\"> read\n     ugly (browser-default button + \"no file chosen\" text with no styling\n     control), so it's now a hidden input triggered by a real styled button,\n     matching every other pill/rounded control in this modal (2026-08-29,\n     per Martin's request). */\n  .upload-picker { display: flex; align-items: center; gap: 10px; margin-top: 4px; min-width: 0; }\n  .upload-picker-btn {\n    background: var(--panel-inner);\n    border: 1px solid var(--border);\n    border-radius: 999px;\n    padding: 7px 14px;\n    font-family: inherit;\n    font-weight: 800;\n    font-size: 0.76rem;\n    color: var(--text-dark);\n    cursor: pointer;\n    flex-shrink: 0;\n  }\n  .upload-picker-btn:hover { background: var(--border); }\n  .upload-picker-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .upload-picker-filename {\n    flex: 1;\n    min-width: 0;\n    font-size: 0.78rem;\n    color: var(--text-dark);\n    font-weight: 600;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n  .upload-picker-filename.empty { color: var(--text-faint); font-weight: 600; font-style: italic; }\n  /* Required-file validation (2026-09-04, per Martin: \"make sure that the\n     user uploads at min 1 file in the upload tab\") -- Submit is blocked\n     on the Upload tab until a file is chosen; this note + the picker's\n     red border only appear after that first failed attempt, not before\n     the user has had a chance to pick a file. Same red as\n     .profile-menu-item.signout elsewhere in the app. */\n  .upload-picker.error .upload-picker-btn { border-color: #b6432f; }\n  .upload-required-note { font-size: 0.74rem; font-weight: 700; color: #b6432f; margin: 6px 0 0; }\n  .upload-required-note[hidden] { display: none; }\n  /* List of files picked so far on the Upload tab (2026-09-04, per\n     Martin: \"let people upload multiple files\") -- the native file input\n     is `multiple` and re-opening the OS picker only ADDS to this list\n     rather than replacing it (each dialog's selection is appended to\n     `pickedFiles` in bindUploadTab, since the browser itself resets\n     input.files to just the newest selection every time). Reuses\n     .material-row's badge look (same file-type colors as everywhere else\n     in this app) plus a remove button per row. */\n  .upload-picked-list { margin-top: 4px; max-height: 168px; overflow-y: auto; }\n  .upload-picked-list:empty { margin-top: 0; }\n  .upload-picked-row { display: flex; align-items: center; gap: 10px; padding: 7px 0; border-bottom: 1px solid var(--border); }\n  .upload-picked-row:last-child { border-bottom: none; }\n  .upload-picked-name { flex: 1; min-width: 0; font-size: 0.8rem; font-weight: 600; color: var(--text-dark); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  /* Create tab's rich-text toolbar (2026-08-30, per Martin's request — \"the\n     create section is just one textbox that has formatting options like\n     google docs\"). A lightweight execCommand-based editor: a block-style\n     picker (Normal text / Heading 1-3) plus Bold/Italic/Underline/list/link\n     buttons sit above a contenteditable answer area, replacing the old\n     plain <textarea>. Front-end only, same as everywhere else in this\n     mockup — nothing is actually saved as rich text on submit. */\n  .rte-toolbar {\n    display: flex;\n    align-items: center;\n    gap: 4px;\n    flex-wrap: wrap;\n    margin-top: 4px;\n    padding: 5px 6px;\n    border: 1px solid var(--border);\n    border-bottom: none;\n    border-radius: var(--window-radius-sm) var(--window-radius-sm) 0 0;\n    background: var(--panel-inner);\n  }\n  .rte-select {\n    font-family: inherit;\n    font-size: 0.72rem;\n    font-weight: 700;\n    color: var(--text-dark);\n    background: var(--panel-bg);\n    border: 1px solid var(--border);\n    border-radius: 6px;\n    padding: 4px 6px;\n    cursor: pointer;\n  }\n  .rte-select:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .rte-divider { width: 1px; height: 18px; background: var(--border); margin: 0 2px; flex-shrink: 0; }\n  .rte-btn {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    width: 26px;\n    height: 26px;\n    border: none;\n    border-radius: 6px;\n    background: transparent;\n    color: var(--text-dark);\n    font-family: inherit;\n    font-size: 0.78rem;\n    cursor: pointer;\n    flex-shrink: 0;\n    padding: 0;\n  }\n  .rte-btn b, .rte-btn i, .rte-btn u { pointer-events: none; }\n  .rte-btn:hover { background: var(--border); }\n  .rte-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .rte-btn.active { background: var(--accent); color: #fff; }\n  .rte-btn svg { width: 15px; height: 15px; stroke: currentColor; fill: none; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; pointer-events: none; }\n  .rte-btn svg text { fill: currentColor; stroke: none; font-weight: 700; pointer-events: none; }\n  .rte-editor {\n    border-top-left-radius: 0;\n    border-top-right-radius: 0;\n    min-height: 110px;\n    overflow-y: auto;\n  }\n  .rte-editor:empty::before { content: attr(data-placeholder); color: var(--text-faint); }\n  .rte-editor h1 { font-size: 1.15rem; margin: 4px 0; }\n  .rte-editor h2 { font-size: 1.02rem; margin: 4px 0; }\n  .rte-editor h3 { font-size: 0.92rem; margin: 4px 0; }\n  .rte-editor ul, .rte-editor ol { margin: 4px 0 4px 18px; padding: 0; }\n  .rte-editor a { color: var(--accent); }\n  .submission-comment {\n    font-size: 0.76rem;\n    color: var(--text-muted);\n    font-style: italic;\n    margin: 2px 0 0 34px;\n  }\n  /* Submission-history rows are clickable (2026-08-31, per Martin's\n     request) — a row is a specific turn-in, so clicking it opens a\n     small preview + that turn-in's own teacher comments, rather than\n     showing feedback as one static block for the whole assignment. */\n  .submission-row { cursor: pointer; border-radius: var(--window-radius-sm); border-bottom: none; padding: 10px 8px; }\n  .submission-row:hover { background: var(--panel-inner); }\n  .submission-row:focus-visible {\n    outline: none;\n    box-shadow: 0 0 0 2px var(--accent-ring);\n  }\n  .submission-comment-icon {\n    flex-shrink: 0;\n    width: 15px;\n    height: 15px;\n    color: var(--text-faint);\n    stroke: currentColor;\n    fill: none;\n    stroke-width: 2;\n    stroke-linecap: round;\n    stroke-linejoin: round;\n  }\n  /* The student's own comment on a submission, shown inside the preview\n     popup — same italic quote treatment as .submission-comment used to\n     have inline, just without the row-indent margin since it now sits\n     inside a modal instead of under a list row. */\n  .own-comment-box {\n    font-size: 0.82rem;\n    color: var(--text-muted);\n    font-style: italic;\n    line-height: 1.5;\n    margin: 12px 0 0;\n  }\n  .own-comment-box .label {\n    display: block;\n    font-size: 0.66rem;\n    font-weight: 800;\n    font-style: normal;\n    text-transform: uppercase;\n    letter-spacing: 0.03em;\n    color: var(--text-faint);\n    margin-bottom: 4px;\n  }\n  .modal-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 18px; }\n  .modal-btn {\n    border: none;\n    border-radius: 999px;\n    padding: 8px 16px;\n    font-family: inherit;\n    font-weight: 800;\n    font-size: 0.78rem;\n    cursor: pointer;\n  }\n  a.modal-btn { display: inline-flex; align-items: center; text-decoration: none; }\n  .modal-btn.secondary { background: var(--panel-inner); color: var(--text-dark); }\n  .modal-btn.secondary:hover { background: var(--border); }\n  .modal-btn.primary { background: var(--accent); color: #fff; }\n  .modal-btn.primary:hover { background: var(--accent-dark); }\n  .modal-btn.danger { background: #b6432f; color: #fff; }   /* same red as Sign out */\n  .modal-btn.danger:hover { filter: brightness(1.08); }\n  .modal-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n\n  /* ---------- Add Submission button + submission history — an\n     assignment can be submitted more than once (2026-08-29, per\n     Martin's request), so Submissions now shows a small history list\n     (newest first) instead of a single fixed file, with this button\n     always available to add another attempt regardless of status. ---------- */\n  .add-submission-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    background: var(--accent);\n    color: #fff;\n    border: none;\n    border-radius: 999px;\n    padding: 8px 14px 8px 12px;\n    font-weight: 800;\n    font-size: 0.76rem;\n    font-family: inherit;\n    cursor: pointer;\n    margin-top: 4px;\n  }\n  .add-submission-btn:hover { background: var(--accent-dark); }\n  .add-submission-btn svg { width: 14px; height: 14px; stroke: #fff; fill: none; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }\n  .submission-latest-tag {\n    font-size: 0.6rem;\n    font-weight: 800;\n    text-transform: uppercase;\n    letter-spacing: 0.03em;\n    color: var(--accent);\n    margin-left: 8px;\n  }\n\n  /* ---------- Submissions panel ---------- */\n  .submission-banner {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    padding: 12px 14px;\n    border-radius: var(--window-radius-md);\n    margin-bottom: 16px;\n  }\n  .submission-banner .dot { width: 9px; height: 9px; border-radius: 50%; flex-shrink: 0; }\n  .submission-banner-text { min-width: 0; }\n  .submission-banner-label { font-weight: 800; font-size: 0.86rem; margin: 0; }\n  .submission-banner-meta { font-weight: 600; font-size: 0.74rem; margin: 2px 0 0; opacity: 0.85; }\n  .submission-banner.overdue { background: rgba(182, 67, 47, 0.14); }\n  .submission-banner.overdue .dot { background: var(--grade-bad); }\n  .submission-banner.overdue .submission-banner-label { color: var(--grade-bad); }\n  .submission-banner.upcoming { background: var(--panel-inner); }\n  .submission-banner.upcoming .dot { background: var(--text-faint); }\n  .submission-banner.upcoming .submission-banner-label { color: var(--text-muted); }\n  .submission-banner.submitted { background: rgba(166, 122, 34, 0.14); }\n  .submission-banner.submitted .dot {\n    background: var(--grade-mid);\n    /* Submitted = grade pending. Fade in/out to read as \"waiting\", distinct from the\n       static dots on every other status. */\n    animation: pending-fade 1.8s ease-in-out infinite;\n  }\n  .submission-banner.submitted .submission-banner-label { color: var(--grade-mid); }\n\n  @keyframes pending-fade {\n    0%, 100% { opacity: 1; }\n    50%      { opacity: 0.25; }\n  }\n  @media (prefers-reduced-motion: reduce) {\n    .submission-banner.submitted .dot { animation: none; }\n  }\n  .submission-banner.graded { background: rgba(47, 125, 84, 0.14); }\n  .submission-banner.graded .dot { background: var(--grade-good); }\n  .submission-banner.graded .submission-banner-label { color: var(--grade-good); }\n  .submission-banner.returned { background: rgba(106, 79, 174, 0.14); }\n  .submission-banner.returned .dot { background: var(--returned); }\n  .submission-banner.returned .submission-banner-label { color: var(--returned); }\n\n  .submit-dropzone {\n    border: 2px dashed var(--border);\n    border-radius: var(--window-radius-md);\n    padding: 26px 18px;\n    text-align: center;\n    color: var(--text-faint);\n    font-size: 0.78rem;\n    font-weight: 600;\n    line-height: 1.5;\n  }\n  .submit-dropzone svg { width: 24px; height: 24px; stroke: var(--text-faint); fill: none; stroke-width: 1.8; margin-bottom: 6px; }\n  /* Solid panel background instead of the dashed upload border — this\n     notice isn't a drop target, it's a redirect, so it shouldn't read as\n     one (2026-09-03, quiz redirect notice). Accent-colored icon for the\n     same reason: it's pointing somewhere, not waiting for a file.\n     `> svg` (direct child only) so this doesn't also recolor/resize the\n     smaller icon inside the Open in Schoology button below. */\n  .quiz-redirect-notice { border: none; background: var(--panel-inner); }\n  .quiz-redirect-notice > svg { stroke: var(--accent); }\n  /* Real clickable redirect (2026-09-03, per Martin: \"keep them in but\n     ... can you put a redirect to schoology\") — a working external link,\n     not another disabled/\"not available in this preview\" placeholder,\n     since Schoology itself is a real site this can actually open.\n     Same pill shape/weight as .add-submission-btn so it reads as the\n     one other real action-button on this panel. */\n  .quiz-redirect-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    background: var(--accent);\n    color: #fff;\n    border: none;\n    border-radius: 999px;\n    padding: 8px 14px;\n    font-weight: 800;\n    font-size: 0.76rem;\n    font-family: inherit;\n    text-decoration: none;\n    cursor: pointer;\n    margin-top: 12px;\n  }\n  .quiz-redirect-btn:hover { background: var(--accent-dark); }\n  .quiz-redirect-btn svg { width: 13px; height: 13px; stroke: #fff; fill: none; stroke-width: 2.4; margin-bottom: 0; }\n\n  .feedback-box {\n    background: var(--panel-inner);\n    border-radius: var(--window-radius-md);\n    padding: 12px 14px;\n    margin-top: 16px;\n  }\n  .feedback-box p { margin: 0; font-size: 0.84rem; font-style: italic; color: var(--text-dark); line-height: 1.5; }\n  .feedback-box .attrib { display: block; margin-top: 8px; font-size: 0.72rem; font-weight: 800; font-style: normal; color: var(--text-faint); }\n  /* A comment on a Returned assignment reuses the same quote-box shape\n     as graded Teacher Feedback, but with a violet accent border and a\n     small label so it never reads as an actual final-grade comment. */\n  .feedback-box.returned { border-left: 4px solid var(--returned); }\n  .feedback-box-label {\n    display: block;\n    font-size: 0.66rem;\n    font-weight: 800;\n    text-transform: uppercase;\n    letter-spacing: 0.03em;\n    color: var(--returned);\n    margin-bottom: 6px;\n  }\n\n  /* ---------- Bottom nav — verbatim from every other page ---------- */\n  .app-nav {\n    position: fixed;\n    left: 0;\n    right: 0;\n    bottom: 20px;\n    display: flex;\n    justify-content: center;\n    padding: 0 20px;\n    z-index: 10;\n    pointer-events: none;\n  }\n  .app-nav-inner {\n    display: flex;\n    gap: 4px;\n    width: 100%;\n    max-width: 940px;\n    overflow-x: auto;\n    scrollbar-width: none;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    padding: 0 8px;\n    pointer-events: auto;\n  }\n  .app-nav-inner::-webkit-scrollbar { display: none; }\n  .nav-link {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 1;\n    min-width: 0;\n    padding: 12px 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-link .label { display: block; max-width: 100%; font-size: 0.72rem; font-weight: 800; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; }\n  .nav-link:hover .label { color: var(--text-muted); }\n  .nav-link .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-link.active .label { color: var(--text-dark); }\n  .nav-link.active .dot { background: var(--accent); }\n  /* ---------- \"More\" overflow (2026-10-01, per Martin: \"if the text has\n     to get ... we should add a more button on the far right side with a\n     list of the other options\"). Labels never truncate: when they would,\n     the rightmost pages move into the More menu instead. ---------- */\n  .nav-link[hidden], .nav-more[hidden], .nav-more-menu[hidden] { display: none; }\n  /* While the More menu is open the whole bar sits above everything else on\n     the page (sticky headers, pop-ups, the edit button go up to z-index 90),\n     so the menu is never drawn underneath them. */\n  .app-nav.more-open { z-index: 1000; }\n  .nav-more {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 0 0 auto;\n    position: relative;\n    margin-left: 4px;\n    padding: 12px 16px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-more .label { display: flex; align-items: center; height: 1.2em; font-size: 0.72rem; color: var(--text-faint); }\n  .nav-more .label svg { display: block; fill: currentColor; }\n  /* thin divider between the pages and the dots */\n  .nav-more::before { content: \"\"; position: absolute; left: 0; top: 12px; bottom: 12px; width: 1px; background: var(--border, #cfcfd6); }\n  .nav-more:hover .label, .nav-more[aria-expanded=\"true\"] .label { color: var(--text-dark); }\n  .nav-more .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-more.has-active .label { color: var(--text-dark); }\n  .nav-more.has-active .dot { background: var(--accent); }\n  .nav-more:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-menu {\n    position: absolute;\n    bottom: calc(100% + 8px);\n    right: 20px;\n    min-width: 168px;\n    padding: 8px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);\n    pointer-events: auto;\n  }\n  .nav-more-item {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    font-size: 0.8rem;\n    font-weight: 800;\n    color: var(--text-faint);\n    text-align: left;\n    padding: 12px 12px;\n    border-radius: 8px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n  }\n  .nav-more-item:hover, .nav-more-item:focus-visible { outline: none; color: var(--text-dark); box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-item.active { color: var(--text-dark); }\n  .nav-more-item.active span { position: relative; display: inline-block; padding-bottom: 6px; margin-bottom: -6px; }\n  .nav-more-item.active span::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  /* Labels sit centered in the bar; the active page is underlined in the\n     accent color instead of marked with a dot (2026-10-01, per Martin). */\n  .app-nav-inner .nav-link, .app-nav-inner .nav-more { justify-content: center; gap: 0; padding-top: 10px; padding-bottom: 10px; }\n  .app-nav-inner .nav-link .dot, .app-nav-inner .nav-more .dot { display: none; }\n  .app-nav-inner .nav-link .label, .app-nav-inner .nav-more .label { position: relative; padding: 6px 0; }\n  .app-nav-inner .nav-link.active .label::after, .app-nav-inner .nav-more.has-active .label::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  @media (max-width: 520px) {\n    .nav-more { padding: 10px 12px 8px; }\n    .nav-more::before { top: 10px; bottom: 10px; }\n    .app-nav-inner .nav-link, .app-nav-inner .nav-more { padding-top: 8px; padding-bottom: 8px; }\n    .nav-more .label { font-size: 0.58rem; }\n  }\n  .nav-link:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  @media (max-width: 520px) {\n    .nav-link { min-width: 0; padding: 10px 3px 8px; }\n    .nav-link .label { font-size: 0.58rem; }\n  }\n  /* Emoji icons (2026-10-01, per Martin): icons that show a thing are emoji;\n     buttons and action icons stay line icons. */\n  /* Each emoji is an inline SVG sized by font-size (1em box), so it is\n     exactly as big as its box and sits dead center. The svg rule undoes\n     the line-icon styles (stroke, fill:none, opacity) that the parent\n     rows still set for their other icons. */\n  .emo { display: inline-block; width: 1em; height: 1em; line-height: 0; flex-shrink: 0; vertical-align: middle; }\n  .emo svg { display: block; width: 100%; height: 100%; fill: initial; stroke: none; opacity: 1; }\n  .emo.submission-comment-icon { width: 15px; height: 15px; }\n";
const BODY_HTML = "\n  <div class=\"page\">\n    <button class=\"back-link\" type=\"button\" id=\"backBtn\">\n      <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M15 18l-6-6 6-6\"/></svg>\n      <span id=\"backLabel\">Back to Assignments</span>\n    </button>\n\n    <div class=\"topbar\">\n      <div>\n        <h1 class=\"title\" id=\"assignTitle\">Assignment Name</h1>\n        <div class=\"assign-sub\">\n          <button class=\"assign-sub-link\" type=\"button\" id=\"classLink\">Class Name</button>\n          <span class=\"assign-sub-dot\">·</span>\n          <button class=\"assign-sub-link\" type=\"button\" id=\"gradebookLink\" title=\"Grading Period\">Gradebook</button>\n        </div>\n      </div>\n      <div class=\"profile-menu-wrap\">\n        <button class=\"profile-btn\" id=\"profileBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Profile and settings\">M</button>\n        <div class=\"profile-menu\" id=\"profileMenu\" role=\"menu\" hidden>\n          <button class=\"profile-menu-item\" type=\"button\" role=\"menuitem\" data-action=\"settings\">Settings</button>\n          <button class=\"profile-menu-item signout\" type=\"button\" role=\"menuitem\" data-action=\"signout\">Sign out</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"assign-detail-grid\">\n      <div class=\"card\">\n        <div class=\"card-inner\">\n          <h2>Description</h2>\n          <p class=\"assign-desc-text\" id=\"descText\"></p>\n          <h2 class=\"second\">Attached Materials</h2>\n          <div id=\"materialsList\"></div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-inner\">\n          <section class=\"drafts\" id=\"draftsSec\" aria-labelledby=\"draftsTitle\" hidden>\n            <h2 id=\"draftsTitle\">Drafts</h2>\n            <div id=\"draftsList\"></div>\n          </section>\n          <h2>Submissions</h2>\n          <div id=\"submissionBanner\"></div>\n          <div id=\"submissionBody\"></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <nav class=\"app-nav\" aria-label=\"Main navigation\">\n    <div class=\"app-nav-inner\" id=\"dock\">\n      <button class=\"nav-link\" type=\"button\" data-page=\"home\" data-href=\"/home\">\n        <span class=\"label\">Home</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"courses\" data-href=\"/courses\">\n        <span class=\"label\">Courses</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"grades\" data-href=\"/grades\">\n        <span class=\"label\">Grades</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link active\" type=\"button\" data-page=\"assignments\" data-href=\"/assignments\">\n        <span class=\"label\">Assignments</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"files\" data-href=\"/files\">\n        <span class=\"label\">Files</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"calendar\" data-href=\"/calendar\">\n        <span class=\"label\">Calendar</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"messages\" data-href=\"/messages\">\n        <span class=\"label\">Messages</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"contacts\" data-href=\"/contacts\">\n        <span class=\"label\">Contacts</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"settings\" data-href=\"/settings\">\n        <span class=\"label\">Settings</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-more\" type=\"button\" id=\"navMore\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\" aria-label=\"More pages\" hidden>\n        <span class=\"label\"><svg viewBox=\"0 0 16 4\" width=\"16\" height=\"4\" aria-hidden=\"true\"><circle cx=\"2\" cy=\"2\" r=\"1.75\"/><circle cx=\"8\" cy=\"2\" r=\"1.75\"/><circle cx=\"14\" cy=\"2\" r=\"1.75\"/></svg></span>\n        <span class=\"dot\"></span>\n      </button>\n    </div>\n    <div class=\"nav-more-menu\" id=\"navMoreMenu\" role=\"menu\" aria-label=\"More pages\" hidden></div>\n  </nav>\n\n  \n\n\n  <div class=\"modal-overlay\" id=\"modalOverlay\" hidden>\n    <div class=\"modal-box\" id=\"modalBox\"></div>\n  </div>\n\n  \n  \n";
const SCRIPT_JS = "\n    // ---- Links by id (2026-10-07, Martin) ----\n    // A real class (Schoology/Classroom ids are digits) links as\n    // assignment?id=<id> and course-home?id=<section id>; the sample classes\n    // (word ids like \"apchem\") keep ?course=&title=. Pages read both.\n    function avgIsId(v) { return /^\\d{1,24}$/.test(String(v == null ? '' : v)); }\n    function avgCourseQ(course) { return (avgIsId(course) ? 'id=' : 'course=') + encodeURIComponent(course == null ? '' : course); }\n    function avgAssignHref(course, title, id, extra) {\n      extra = extra || '';\n      if (avgIsId(id) && avgIsId(course)) return `/assignment?id=${id}${extra}`;\n      return `/assignment?course=${encodeURIComponent(course == null ? '' : course)}&title=${encodeURIComponent(title || '')}${avgIsId(id) ? `&id=${id}` : ''}${extra}`;\n    }\n\n    // Potato PC Mode on every page (2026-10-04, per Martin). The saved\n    // setting turns off all CSS animations and transitions, makes animate()\n    // calls and smooth scrolling instant, and drops the slanted page title.\n    // Same code as app/lib/theme-boot.ts, which runs it before first paint in\n    // the app; this copy covers the preview and pages theme-boot skips.\n    (function () {\n    var POTATO_CSS = \"body.potato-mode,body.potato-mode *,body.potato-mode *::before,body.potato-mode *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;filter:none!important;text-shadow:none!important}html:has(body.potato-mode){scroll-behavior:auto!important}body.potato-mode,body.potato-mode *{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif!important}body.potato-mode h1.title{font-style:normal!important;transform:none!important}body.potato-mode .trend.has-popup:focus-visible{outline:2px solid currentColor;outline-offset:2px}\";\n    function potatoOn() { return !!(document.body && document.body.classList.contains(\"potato-mode\")); }\n    function applyPotato() {\n      var on = false;\n      try { on = (JSON.parse(localStorage.getItem(\"schoolagy_settings_options\") || \"{}\") || {}).potatoMode === true; } catch (e) {}\n      if (document.body) document.body.classList.toggle(\"potato-mode\", on);\n      if (!document.getElementById(\"potatoStyle\")) {\n        var st = document.createElement(\"style\");\n        st.id = \"potatoStyle\";\n        st.textContent = POTATO_CSS;\n        (document.head || document.documentElement).appendChild(st);\n      }\n      var EP = window.Element && Element.prototype;\n      if (EP && !EP.__potatoPatched) {\n        EP.__potatoPatched = true;\n        var anim = EP.animate;\n        if (anim) EP.animate = function (frames, opts) {\n          if (potatoOn()) opts = (typeof opts === \"number\" || opts == null) ? { duration: 0 } : Object.assign({}, opts, { duration: 0, delay: 0, endDelay: 0, iterations: 1 });\n          return anim.call(this, frames, opts);\n        };\n        var siv = EP.scrollIntoView;\n        if (siv) EP.scrollIntoView = function (arg) {\n          if (potatoOn() && arg && typeof arg === \"object\") arg = Object.assign({}, arg, { behavior: \"auto\" });\n          return siv.call(this, arg);\n        };\n        [\"scrollTo\", \"scrollBy\"].forEach(function (name) {\n          [EP, window].forEach(function (target) {\n            var fn = target[name];\n            if (!fn) return;\n            target[name] = function (a, b) {\n              if (potatoOn() && a && typeof a === \"object\") a = Object.assign({}, a, { behavior: \"auto\" });\n              return b === undefined ? fn.call(this, a) : fn.call(this, a, b);\n            };\n          });\n        });\n      }\n    }\n      applyPotato();\n      window.addEventListener('storage', function (e) { if (e.key === 'schoolagy_settings_options') applyPotato(); });\n    })();\n\n    // Bottom nav \"More\" overflow. Shows as many pages as fit without\n    // cutting a label off (\"Cour...\"); the rest go in the More menu.\n    // The current page always stays in the bar.\n    (function () {\n      const nav = document.querySelector('.app-nav');\n      const inner = nav && nav.querySelector('.app-nav-inner');\n      const more = document.getElementById('navMore');\n      const menu = document.getElementById('navMoreMenu');\n      if (!inner || !more || !menu) return;\n      const links = Array.from(inner.querySelectorAll('.nav-link'));\n\n      const cut = () =>\n        inner.scrollWidth > inner.clientWidth + 1 ||\n        links.some(l => !l.hidden && l.querySelector('.label').scrollWidth > l.querySelector('.label').clientWidth + 1);\n\n      function fit() {\n        closeMenu();\n        links.forEach(l => { l.hidden = false; });\n        more.hidden = true;\n        if (!cut()) return;\n        more.hidden = false;\n        // Hide from the right, but never the current page.\n        for (let i = links.length - 1; i >= 1 && cut(); i--) {\n          if (!links[i].classList.contains('active')) links[i].hidden = true;\n        }\n        const hidden = links.filter(l => l.hidden);\n        more.classList.toggle('has-active', hidden.some(l => l.classList.contains('active')));\n        menu.textContent = '';\n        hidden.forEach(l => {\n          const item = document.createElement('button');\n          item.type = 'button';\n          item.className = 'nav-more-item' + (l.classList.contains('active') ? ' active' : '');\n          item.setAttribute('role', 'menuitem');\n          const text = document.createElement('span'); text.textContent = l.querySelector('.label').textContent; item.appendChild(text);\n          item.addEventListener('click', () => { closeMenu(); l.click(); });\n          menu.appendChild(item);\n        });\n      }\n\n      function openMenu() {\n        const navBox = nav.getBoundingClientRect();\n        const innerBox = inner.getBoundingClientRect();\n        menu.style.right = Math.max(0, navBox.right - innerBox.right) + 'px';\n        menu.hidden = false;\n        nav.classList.add('more-open');\n        more.setAttribute('aria-expanded', 'true');\n        const first = menu.querySelector('.nav-more-item');\n        if (first) first.focus();\n      }\n      function closeMenu() {\n        if (menu.hidden) return;\n        menu.hidden = true;\n        nav.classList.remove('more-open');\n        more.setAttribute('aria-expanded', 'false');\n      }\n\n      more.addEventListener('click', e => {\n        e.stopPropagation();\n        menu.hidden ? openMenu() : closeMenu();\n      });\n      document.addEventListener('click', e => { if (!menu.contains(e.target)) closeMenu(); });\n      document.addEventListener('keydown', e => {\n        if (e.key === 'Escape' && !menu.hidden) { closeMenu(); more.focus(); }\n        if (!menu.hidden && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {\n          const items = Array.from(menu.querySelectorAll('.nav-more-item'));\n          const i = items.indexOf(document.activeElement);\n          const next = items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length];\n          if (next) { e.preventDefault(); next.focus(); }\n        }\n      });\n\n      fit();\n      if (window.ResizeObserver) new ResizeObserver(fit).observe(nav);\n      else window.addEventListener('resize', fit);\n      if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);\n    })();\n  \n\n\n    // ------------------------------------------------------------------\n    // Shared appearance (accent + background) — 2026-09-08, per Martin:\n    // \"wallpapers + accent colors don't save across pages.\" Settings'\n    // Appearance section (and onboarding's Theme step) are the only\n    // writers of schoolagy_appearance; every other real app page,\n    // including this one, applies whatever's saved there, read-only, on\n    // its own load — same shared-localStorage-record pattern already\n    // used for schoolagy_dark_mode/schoolagy_profile.\n    // ------------------------------------------------------------------\n    (function () {\n      function darken(hex, amount) {\n        const n = parseInt(hex.slice(1), 16);\n        const r = Math.max(0, ((n >> 16) & 255) * (1 - amount));\n        const g = Math.max(0, ((n >> 8) & 255) * (1 - amount));\n        const b = Math.max(0, (n & 255) * (1 - amount));\n        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');\n      }\n      function applyAppearance() {\n        let saved = null;\n        try {\n          const raw = localStorage.getItem('schoolagy_appearance');\n          if (raw) saved = JSON.parse(raw);\n        } catch {}\n        if (!saved) return;\n        const root = document.documentElement.style;\n        if (saved.accent) {\n          root.setProperty('--accent', saved.accent);\n          root.setProperty('--accent-dark', saved.accentDark || darken(saved.accent, 0.22));\n        }\n        if (saved.background === 'white') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#f4f4f6';\n        } else if (saved.background === 'black') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#0c0c0e';\n        } else if (saved.background) {\n          document.body.style.backgroundImage = `url(\"${saved.background}\")`;\n          document.body.style.backgroundColor = '';\n        }\n      }\n      applyAppearance();\n      window.addEventListener('storage', e => {\n        if (e.key === 'schoolagy_appearance') applyAppearance();\n      });\n    })();\n\n    // ------------------------------------------------------------------\n    // Sample data — same six courses/colors/teachers as /courses,\n    // and the same OVERDUE/UPCOMING/HISTORY/SUBMITTED values\n    // /assignments uses, so a given assignment's title/type/date/\n    // score/status match no matter which page it's viewed from.\n    // ------------------------------------------------------------------\n\n    // ------------------------------------------------------------------\n    // Course customization persistence — added 2026-09-08. Renaming,\n    // recoloring, or reordering a course (in /home's Customize editor\n    // or /courses's Reorder tool — the only places that WRITE these)\n    // used to be invisible everywhere else, since every page just\n    // re-generated its own hardcoded COURSES array from scratch on load.\n    // schoolagy_course_custom holds per-course name/color overrides\n    // (object keyed by course id, only actually-customized courses\n    // present); schoolagy_course_order holds a full custom ordering of\n    // course ids (array), written only once the user has actually\n    // reordered. This page only READS both — applyCourseCustomizationsInPlace()\n    // is called right after the raw array literal below, mutating COURSES\n    // in place, so it's already the customized/reordered version before\n    // anything on this page ever renders it. Same defensive\n    // try/catch-per-key style as AVERAGES_DARK_MODE_KEY in /settings.\n    // ------------------------------------------------------------------\n    const AVERAGES_COURSE_CUSTOM_KEY = 'schoolagy_course_custom';\n    const AVERAGES_COURSE_ORDER_KEY = 'schoolagy_course_order';\n    function loadCourseCustom() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_CUSTOM_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return {};\n    }\n    function loadCourseOrder() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_ORDER_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return null;\n    }\n    // Subject table (2026-10-01, per Martin): each course gets a color that\n    // fits its subject, picked from its name. First match wins, so specific\n    // subjects come before broad ones (\"Computer Science\" before \"Science\",\n    // \"Physical Education\" before \"Physics\"). A color the student picked in\n    // the course's info pop-up still wins over this. No match keeps the\n    // course's own color. All colors pass 4.5:1 with white text.\n    const COURSE_SUBJECTS = [\n      [/\\bchem/, '🧪', '#1b7f67'],\n      [/\\bbio|anatom|physiolog/, '🧬', '#387f33'],\n      [/\\bphysical ed|(^|[^a-z])p\\.?e\\.?($|[^a-z])|fitness|\\bweight/, '🏃', '#c2562b'],\n      [/\\bhealth/, '🩺', '#c0404a'],\n      [/\\bphysics/, '⚛️', '#4a56b8'],\n      [/astronom/, '🔭', '#3b3f8f'],\n      [/environment|\\bearth|geolog/, '🌍', '#2f7f63'],\n      [/robotic/, '🤖', '#55697d'],\n      [/computer|programming|coding|\\bcs[ap]?\\b|software/, '💻', '#2d6f8f'],\n      [/engineer/, '⚙️', '#6a6478'],\n      [/government|civics|politic/, '🏛️', '#2f4f8a'],\n      [/econ/, '📈', '#2e7d4f'],\n      [/psych/, '🧠', '#9a4583'],\n      [/geograph/, '🗺️', '#4c7a5a'],\n      [/histor/, '📜', '#9a5a2a'],\n      [/statistic|\\bstats?\\b/, '📊', '#2f72a8'],\n      [/geometr|\\btrig/, '📐', '#3e64b0'],\n      [/calc|algebra|\\bmath/, '🧮', '#2f5fb3'],\n      [/english|literature|\\blit\\b|writing|composition|language arts|reading/, '📖', '#a63a4f'],\n      [/spanish|french|german|chinese|mandarin|japanese|korean|latin|italian|\\basl\\b|sign language|language/, '🗣️', '#7a4fae'],\n      [/theat|drama/, '🎭', '#a3364b'],\n      [/music|band|choir|orchestra|chorus/, '🎵', '#6b48a8'],\n      [/photo/, '📷', '#4f5d6e'],\n      [/culinary|cooking|\\bfoods?\\b|nutrition/, '🍳', '#b05a26'],\n      [/\\barts?\\b|drawing|painting|ceramic|sculpt|design/, '🎨', '#b03f7a'],\n      [/business|marketing|accounting|financ/, '💼', '#3d5f6e'],\n      [/journalism|yearbook|newspaper/, '📰', '#5c5c6e'],\n      [/science/, '🔬', '#2b7b8c'],\n    ];\n    function courseSubject(name) {\n      const n = String(name || '').toLowerCase();\n      return COURSE_SUBJECTS.find(([re]) => re.test(n)) || null;\n    }\n\n    function applyCourseCustomizationsInPlace(courses) {\n      const custom = loadCourseCustom();\n      // Mutates each course object's own fields in place (never clones,\n      // never reassigns `courses` itself) so the `const COURSES = [...]`\n      // literal a few lines below stays exactly that — a literal array —\n      // for scripts/port-pages.mjs's data-overrides transform to match\n      // and rewrite for live Schoology data. This function only edits\n      // the array's contents/order after that binding already exists.\n      courses.forEach(c => {\n        const subject = courseSubject(c.name);\n        if (subject) c.color = subject[2];\n        Object.assign(c, custom[c.id] || {});\n      });\n      const order = loadCourseOrder();\n      if (order && order.length) {\n        const byId = new Map(courses.map(c => [c.id, c]));\n        const ordered = order.filter(id => byId.has(id)).map(id => byId.get(id));\n        // A course not present in the saved order (e.g. added to the demo\n        // data after the order was saved) still shows up, just appended.\n        courses.forEach(c => { if (!order.includes(c.id)) ordered.push(c); });\n        courses.splice(0, courses.length, ...ordered);\n      }\n    }\n    const COURSES = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.COURSES) || [\n      { id: 'apchem', name: 'AP Chemistry', color: '#a67a22', teacher: 'Mr. Alvarez' },\n      { id: 'algebra2', name: 'Algebra II', color: '#5b6ea3', teacher: 'Ms. Whitfield' },\n      { id: 'english10', name: 'English 10', color: '#6b8f5e', teacher: 'Mr. Cho' },\n      { id: 'ushistory', name: 'U.S. History', color: '#a15c4f', teacher: 'Mr. Bennett' },\n      { id: 'spanish3', name: 'Spanish III', color: '#8a6ba1', teacher: 'Ms. Ortiz' },\n      { id: 'pe', name: 'PE', color: '#4f8c8a', teacher: 'Coach Reyes' },\n    ];\n    applyCourseCustomizationsInPlace(COURSES);\n    function findCourse(id) { return COURSES.find(c => c.id === id); }\n\n    /* Assignment titles, teacher feedback/comments and attached or submitted\n       FILE NAMES all arrive from Schoology (and the title can also come\n       straight off this page's own ?title= query param), so interpolating any\n       of them raw into innerHTML lets `<img src=x onerror=...>` run in this\n       app's own origin — everything data-derived below goes through here\n       first. String() rather than assuming a string, since scores arrive as\n       numbers. Do NOT wrap values that are themselves markup: the *_ICON\n       constants, materialRowHTML()/submissionHistoryHTML() output, and the\n       feedbackHtml/ownCommentHtml fragments. Verified by verify/xss-test.mjs. */\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, ch => (\n        { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch]\n      ));\n    }\n\n    const TYPE_LABEL = { assignment: 'Assignment', discussion: 'Discussion', assessment: 'Quiz' };\n\n    const HISTORY = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.HISTORY) || {\n      apchem: { points: [72, 79, 84, 88, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'], titles: [['Intro Lab Safety Quiz', 'assessment'], ['Stoichiometry Problem Set', 'assignment'], ['Molarity Discussion', 'discussion'], ['Gas Laws Test', 'assessment'], ['Lab Report #3', 'assignment']] },\n      algebra2: { points: [94, 96, 93, 97, 95], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'], titles: [['Warm-Up Quiz 1', 'assessment'], ['Systems of Equations HW', 'assignment'], ['Factoring Discussion', 'discussion'], ['Unit 1 Test', 'assessment'], ['Practice Set 6', 'assignment']] },\n      english10: { points: [88, 82, 79, 76, 73], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'], titles: [['Reading Journal 1', 'assignment'], ['Vocabulary Quiz', 'assessment'], ['Chapter 3 Discussion', 'discussion'], ['Essay Draft', 'assignment'], ['Grammar Check', 'assessment']] },\n      ushistory: { points: [89, 93, 88, 92, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'], titles: [['Colonial Era Notes', 'assignment'], ['Primary Source Quiz', 'assessment'], ['Revolution Discussion', 'discussion'], ['Timeline Project', 'assignment'], ['Unit 1 Exam', 'assessment']] },\n      spanish3: { points: [76, 80, 83, 85, 87], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'], titles: [['Vocabulario Quiz', 'assessment'], ['Conjugación Practice', 'assignment'], ['Conversación Discussion', 'discussion'], ['Listening Check', 'assessment'], ['Composición 1', 'assignment']] },\n      pe: { points: [96, 98, 95, 97, 96], dates: ['Aug 2', 'Aug 6', 'Aug 10', 'Aug 16', 'Aug 22'], titles: [['Fitness Log 1', 'assignment'], ['Rules Quiz', 'assessment'], ['Team Strategy Discussion', 'discussion'], ['Skills Check', 'assessment'], ['Fitness Log 2', 'assignment']] },\n    };\n\n    const OVERDUE = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.OVERDUE) || [\n      { type: 'assignment', title: 'Lab Report #4', courseId: 'apchem', due: 'Fri Aug 21' },\n      { type: 'discussion', title: 'Chapter 6 Discussion', courseId: 'english10', due: 'Thu Aug 20' },\n      { type: 'discussion', title: 'Reading Response', courseId: 'ushistory', due: 'Wed Aug 19' },\n    ];\n    const UPCOMING = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.UPCOMING) || [\n      { type: 'assessment', title: 'Unit 2 Quiz', courseId: 'algebra2', due: 'Mon Aug 24' },\n      { type: 'assignment', title: 'Vocab Worksheet', courseId: 'spanish3', due: 'Tue Aug 25' },\n      { type: 'assignment', title: 'Problem Set 7', courseId: 'algebra2', due: 'Wed Aug 26' },\n      { type: 'assignment', title: 'Titration Lab Prep', courseId: 'apchem', due: 'Mon Aug 24' },\n    ];\n    // Recently Submitted — work that's been turned in but hasn't been\n    // graded yet, sitting between Upcoming and Graded in the overall\n    // assignment lifecycle. New as of 2026-08-29, per Martin's request.\n    const SUBMITTED = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.SUBMITTED) || [\n      { type: 'assignment', title: 'Molarity Practice Set', courseId: 'apchem', submittedOn: 'Sat Aug 22' },\n      { type: 'assessment', title: 'Quiz Corrections', courseId: 'algebra2', submittedOn: 'Sun Aug 23' },\n      { type: 'assignment', title: 'Composición 2', courseId: 'spanish3', submittedOn: 'Fri Aug 21' },\n    ];\n    // Returned — the teacher has looked at the submission and sent it\n    // back with a comment, usually asking for a revision, without\n    // necessarily attaching a final score. A separate lifecycle stage\n    // from Graded (which already has its own Teacher Feedback + score),\n    // added per Martin's request to see what a \"comment or return\" on\n    // an assignment looks like.\n    const RETURNED = [\n      { type: 'assignment', title: 'Periodic Trends Worksheet', courseId: 'apchem', returnedOn: 'Sun Aug 23' },\n    ];\n\n    // ------------------------------------------------------------------\n    // Hand-authored detail content — description, attached materials,\n    // submitted file(s), and teacher feedback — for one representative\n    // assignment per status (Missing/Upcoming/Submitted/Graded), keyed\n    // by \"{courseId}|{title}\". There are ~40 assignments across the\n    // app's sample data and hand-writing rich detail for all of them\n    // isn't realistic for a mock — anything not listed here falls back\n    // to generic placeholder content in buildDetail() below, same as a\n    // real assignment a teacher hasn't filled in yet would show.\n    // ------------------------------------------------------------------\n    // Real Schoology grading periods are named things like \"HS-Fall:\n    // 2026-08-17 - 2026-12-18\", not the bare word \"Gradebook\" (2026-08-29,\n    // per Martin's correction) — this is what the breadcrumb next to\n    // Class Name shows. Now a real link (2026-08-31, once /gradebook\n    // existed to link to) — see the click wiring below, which points at\n    // this assignment's own course, resolving the note that used to sit\n    // here about the breadcrumb needing a real, course + grading-period-\n    // scoped destination rather than a generic one.\n    const GRADING_PERIOD = 'HS-Fall: 2026-08-17 - 2026-12-18';\n\n    // Submissions are now a history, not a single fixed file — a real\n    // assignment can be turned in more than once, and the teacher sees\n    // the most recent attempt (2026-08-29, per Martin's request). Each\n    // DETAILS entry's `submissions` array is oldest-first; the Submitted\n    // example below has two entries specifically to demonstrate a\n    // resubmission.\n    const DETAILS = {\n      'apchem|Lab Report #4': {\n        description: \"Write up your findings from this week's titration lab. Include your data table, calculated molarity for each trial, and a short error-analysis paragraph.\",\n        materials: [{ name: 'Lab Report Template.docx', ext: 'docx' }, { name: 'Titration Data Sheet.pdf', ext: 'pdf' }],\n      },\n      'algebra2|Unit 2 Quiz': {\n        description: 'Covers solving and graphing systems of equations (Sections 4.1–4.4). Calculator allowed; show your work for full credit.',\n        materials: [{ name: 'Unit 2 Study Guide.pdf', ext: 'pdf' }],\n      },\n      'apchem|Molarity Practice Set': {\n        description: \"Ten practice problems on molarity and dilution calculations — extra practice before Friday's quiz. Show all work for each problem.\",\n        materials: [{ name: 'Molarity Practice Set.pdf', ext: 'pdf' }],\n        submissions: [\n          { name: 'Molarity_Practice_Martin_v1.pdf', ext: 'pdf', timestamp: 'Fri, Aug 21 at 6:10 PM' },\n          { name: 'Molarity_Practice_Martin.pdf', ext: 'pdf', timestamp: 'Sat, Aug 22 at 11:42 PM' },\n        ],\n      },\n      'apchem|Gas Laws Test': {\n        description: \"Unit test covering Boyle's Law, Charles's Law, and the Ideal Gas Law. 25 multiple choice questions plus 2 free-response problems.\",\n        materials: [{ name: 'Gas Laws Formula Sheet.pdf', ext: 'pdf' }],\n        submissions: [{ name: 'GasLawsTest_Martin.pdf', ext: 'pdf', timestamp: 'Mon, Aug 18 at 9:58 AM' }],\n        feedback: \"Solid work overall — your free-response reasoning on Boyle's Law was especially clear. Watch your significant figures on Q14 and Q19 next time.\",\n      },\n      // Uses a new `comment` field (distinct from `feedback`, which is\n      // only ever shown once an assignment is actually Graded) so a\n      // Returned item's note reads as \"not your final grade yet\".\n      'apchem|Periodic Trends Worksheet': {\n        description: 'Label and explain the periodic trends (atomic radius, ionization energy, electronegativity) across a period and down a group, using the blank periodic table provided.',\n        materials: [{ name: 'Periodic Trends Packet.pdf', ext: 'pdf' }],\n        submissions: [{ name: 'PeriodicTrends_Martin.pdf', ext: 'pdf', timestamp: 'Fri, Aug 21 at 4:32 PM' }],\n        comment: \"You're on the right track, but your explanation of the ionization-energy trend needs another pass — re-read the section on shielding effect and resubmit by Wednesday.\",\n      },\n    };\n    function buildDetail(item) {\n      const key = `${item.courseId}|${item.title}`;\n      const found = DETAILS[key];\n      if (found && !LIVE) return found;   // sample detail is preview-only\n      const generic = { description: 'No description provided by your teacher yet.', materials: [] };\n      // Preview/demo (2026-10-05): opened from a Materials file, that file is\n      // what's attached (Materials only lists assignments that have one).\n      const fromFile = !LIVE && params.get('file');\n      if (fromFile && /\\.[a-z0-9]{1,8}$/i.test(fromFile)) {\n        generic.materials = [{ name: fromFile.slice(0, 200), ext: fromFile.split('.').pop().toLowerCase() }];\n      }\n      if (item.status === 'submitted' || item.status === 'graded' || item.status === 'returned') {\n        const ts = item.status === 'graded' ? item.due : (item.submittedOn || item.returnedOn);\n        if (ts) generic.submissions = [{ name: `${item.title}.pdf`, ext: 'pdf', timestamp: ts }];\n        if (item.status === 'graded') generic.feedback = 'No additional feedback yet.';\n        if (item.status === 'returned') generic.comment = 'No comment yet.';\n      }\n      return generic;\n    }\n\n    const EXT_COLOR = { pdf: '#c1443a', docx: '#3b6fd1', pptx: '#d1852f' };\n    // New file icons (2026-10-09, public/js/averages-file-icons.js): fileIcon(ext, oldBadge) is the\n    // icon when that script is loaded, else the old colored badge as before.\n    const fileIcon = (ext, fallback, size) => (window.AveragesFileIcons ? window.AveragesFileIcons.html(ext || 'file', { size: size || 34 }) : fallback);\n\n    const DOWNLOAD_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 15V3M12 15l-4-4M12 15l4-4\"/><path d=\"M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2\"/></svg>';\n    const PLUS_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\"/></svg>';\n    // Remove button on a picked-file row in the Add Submission modal's\n    // Upload tab (2026-09-04, per Martin's multi-file request).\n    const REMOVE_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>';\n    // Small speech-bubble flag shown on a submission-history row when it\n    // has a student-entered comment attached (2026-08-31) — a hint that\n    // there's more to see before the row is actually clicked open.\n    const COMMENT_ICON = '<span class=\"submission-comment-icon emo\" aria-hidden=\"true\"><svg aria-hidden=\"true\" focusable=\"false\" viewBox=\"0 0 36 36\"><path fill=\"#BDDDF4\" d=\"M18 1C8.059 1 0 7.268 0 15c0 4.368 2.574 8.268 6.604 10.835C6.08 28.144 4.859 31.569 2 35c5.758-.96 9.439-3.761 11.716-6.416 1.376.262 2.805.416 4.284.416 9.941 0 18-6.268 18-14S27.941 1 18 1z\"/><circle cx=\"18\" cy=\"15\" r=\"2\" fill=\"#2A6797\"/><circle cx=\"26\" cy=\"15\" r=\"2\" fill=\"#2A6797\"/><circle cx=\"10\" cy=\"15\" r=\"2\" fill=\"#2A6797\"/></svg></span>';\n    // Used on the quiz redirect notice (2026-09-03) — an \"external link\"\n    // glyph, distinct from the upload-arrow icon the dropzone normally\n    // shows, so it reads as \"this happens somewhere else\" rather than\n    // \"drag a file here.\"\n    const EXTERNAL_LINK_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6\"/><path d=\"M15 3h6v6\"/><path d=\"M10 14L21 3\"/></svg>';\n\n    const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];\n    function fmtAug(day) { return `${DOW[new Date(2026, 7, day).getDay()]} Aug ${day}`; }\n    function dayNum(dateStr) { const parts = dateStr.trim().split(/\\s+/); return parseInt(parts[parts.length - 1], 10); }\n\n    // Build one normalized master list across every status, exactly as\n    // /assignments does, so this page can look any assignment up by\n    // course + title regardless of which list it came from.\n    // Signed in (2026-10-05): the API's items carry their Schoology `id`\n    // (kept below, it's what loads the real attachments). Lists the API\n    // doesn't send yet (Recently Submitted, Returned) are empty rather than\n    // the sample ones, and HISTORY's sample `titles` only exist in the preview.\n    const LIVE = window.__AVERAGES_MODE__ === 'live';\n    const LIVE_DATA = (window.__AVERAGES__ && window.__AVERAGES__.data) || {};\n    // Google Classroom sign-in (2026-10-05): work is turned in on Classroom\n    // itself (its API only lets an app turn in work that app created), so this\n    // page shows the status and sends the student there. No Drafts.\n    const CLASSROOM = LIVE && LIVE_DATA.platform === 'classroom';\n    const ALL_ITEMS = [];\n    OVERDUE.forEach(o => ALL_ITEMS.push({ status: 'overdue', type: o.type, title: o.title, courseId: o.courseId, due: o.due, id: o.id }));\n    UPCOMING.forEach(u => ALL_ITEMS.push({ status: 'upcoming', type: u.type, title: u.title, courseId: u.courseId, due: u.due, id: u.id }));\n    (LIVE && !LIVE_DATA.SUBMITTED ? [] : SUBMITTED).forEach(s => ALL_ITEMS.push({ status: 'submitted', type: s.type, title: s.title, courseId: s.courseId, submittedOn: s.submittedOn, id: s.id }));\n    (LIVE ? [] : RETURNED).forEach(r => ALL_ITEMS.push({ status: 'returned', type: r.type, title: r.title, courseId: r.courseId, returnedOn: r.returnedOn }));\n    COURSES.forEach(course => {\n      const hist = HISTORY[course.id];\n      if (!hist || !Array.isArray(hist.titles) || !Array.isArray(hist.dates)) return;\n      hist.dates.forEach((d, i) => {\n        ALL_ITEMS.push({ status: 'graded', type: hist.titles[i][1], title: hist.titles[i][0], courseId: course.id, due: fmtAug(dayNum(d)), score: hist.points[i] });\n      });\n    });\n\n    function findAssignment(courseId, title) {\n      return ALL_ITEMS.find(i => i.courseId === courseId && i.title === title);\n    }\n\n    // Default landing item (no query string) — the new Submitted status\n    // is the freshest feature on this page, so it doubles as a natural\n    // example to land on.\n    const params = new URLSearchParams(location.search);\n    const qCourse = params.get('course');\n    const qTitle = params.get('title');\n    const qFrom = params.get('from');\n    let item = null;\n    const qId = params.get('id');\n    const qIdOk = !!qId && /^\\d{1,24}$/.test(qId);\n    // ?id= alone (2026-10-07): the class comes from the lists, else from the\n    // API's answer to \"which class is this in?\" (LegacyPage loads it with\n    // the page: LOCATED), else from a course's Grades tab.\n    let qCourseFromId = '';\n    let qTitleFromId = '';\n    if (qIdOk && !qCourse) {\n      const inLists = ALL_ITEMS.find(i => String(i.id || '') === qId);\n      const located = LIVE_DATA && LIVE_DATA.LOCATED;\n      let gbHint = null;\n      try { gbHint = JSON.parse(sessionStorage.getItem('schoolagy_gb_open') || 'null'); } catch {}\n      if (inLists) { qCourseFromId = inLists.courseId; qTitleFromId = inLists.title; }\n      else if (located && String(located.id) === qId && avgIsId(located.section)) { qCourseFromId = String(located.section); qTitleFromId = located.title || 'Assignment'; }\n      else if (gbHint && gbHint.id === qId) { qCourseFromId = gbHint.courseId; qTitleFromId = gbHint.title; }\n      else {\n        let hint = null;\n        try { hint = JSON.parse(sessionStorage.getItem('schoolagy_locate') || 'null'); } catch {}\n        if (hint && hint.id === qId && avgIsId(hint.section)) { qCourseFromId = hint.section; qTitleFromId = hint.title || 'Assignment'; }\n        else if (window.__AVERAGES_MODE__ === 'live') {\n          // Not loaded with the page (slow, or an old link): ask once, then reopen.\n          const api = window.location.hostname.endsWith('averages.io') ? 'https://api.averages.io' : 'http://localhost:8787';\n          fetch(`${api}/data/assignment/locate?id=${qId}`, { credentials: 'include' })\n            .then(r => (r.ok ? r.json() : null))\n            .then(j => {\n              if (j && avgIsId(j.section)) {\n                try { sessionStorage.setItem('schoolagy_locate', JSON.stringify({ id: qId, section: String(j.section), title: String(j.title || '') })); } catch {}\n                window.location.reload();\n              } else {\n                window.location.replace('/assignments');\n              }\n            })\n            .catch(() => {});\n        }\n      }\n    }\n    const qCourseUse = qCourse || qCourseFromId;\n    const qTitleUse = qTitle || qTitleFromId;\n    if (qCourseUse && qTitleUse) {\n      const qCourse = qCourseUse;\n      const qTitle = qTitleUse;\n      // The Schoology id, when given, picks the exact item (two can share a title).\n      item = (qIdOk && ALL_ITEMS.find(i => i.courseId === qCourse && String(i.id || '') === qId)) || findAssignment(qCourse, qTitle);\n      if (!item) {\n        // A real title/course was passed (e.g. an assignment-flagged file\n        // opened from /course-materials — see openAssignmentDetail()\n        // there) but it has no matching entry in this page's own shared\n        // OVERDUE/UPCOMING/SUBMITTED/HISTORY lists. Show its real title\n        // with generic fallback content rather than silently swapping in\n        // an unrelated default assignment.\n        item = { status: 'upcoming', type: 'assignment', title: qTitle, courseId: qCourse, due: null };\n        // Opened from a course's Grades tab (2026-10-04): use that row's own\n        // graded state and score instead of calling it upcoming.\n        if (qFrom === 'gradebook') {\n          let gb = null;\n          try { gb = JSON.parse(sessionStorage.getItem('schoolagy_gb_open') || 'null'); } catch {}\n          if (gb && gb.courseId === qCourse && (gb.title === item.title || (qIdOk && gb.id === qId))) {\n            const cat = String(gb.category || '');\n            item.type = /test|quiz|exam|assessment/i.test(cat) ? 'assessment' : /discussion/i.test(cat) ? 'discussion' : 'assignment';\n            if (gb.graded && typeof gb.score === 'number' && gb.points > 0) { item.status = 'graded'; item.score = Math.round(gb.score / gb.points * 100); }\n          }\n        }\n      }\n    } else if (qIdOk && window.__AVERAGES_MODE__ === 'live') {\n      // ?id= we couldn't place yet: a blank page while it's looked up (never another assignment).\n      item = { status: 'upcoming', type: 'assignment', title: 'Assignment', courseId: '', due: null };\n    } else {\n      item = findAssignment('apchem', 'Molarity Practice Set');\n    }\n    if (!item) item = ALL_ITEMS[0] || { status: 'upcoming', type: 'assignment', title: 'Assignment', courseId: (COURSES[0] || {}).id, due: null };\n    // An explicit ?id= (Schoology assignment id) wins when the lists didn't have one.\n    if (qIdOk && !item.id && item.courseId) item.id = qId;\n    const course = findCourse(item.courseId) || COURSES[0];\n    const detail = buildDetail(item);\n\n    document.title = `Averages — ${item.title}`;\n    document.getElementById('assignTitle').textContent = item.title;\n    document.getElementById('classLink').textContent = course.name;\n    document.getElementById('classLink').addEventListener('click', () => {\n      window.location.href = `/course-home?${avgCourseQ(course.id)}`;\n    });\n    // Links to /gradebook scoped to this assignment's own course —\n    // resolves the note that used to sit here about the breadcrumb\n    // needing to point at the specific course + grading-period gradebook\n    // it's actually referring to, rather than a shared/ambiguous one\n    // (2026-08-31, once /gradebook existed to link to).\n    document.getElementById('gradebookLink').textContent = GRADING_PERIOD;\n    document.getElementById('gradebookLink').addEventListener('click', () => {\n      window.location.href = `/gradebook?${avgCourseQ(course.id)}`;\n    });\n\n    // Back breadcrumb — \"Back to Assignments\" by default, but swapped for\n    // \"Back to Course Materials\" when this page was reached from the\n    // Materials Finder (2026-08-29, per Martin's request), since that's\n    // genuinely where the user came from and /assignments would be a\n    // dead end back to a page they didn't start on.\n    const cameFromMaterials = qFrom === 'materials';\n    const cameFromGradebook = qFrom === 'gradebook';   // 2026-10-04\n    document.getElementById('backLabel').textContent = cameFromMaterials ? 'Back to Course Materials' : cameFromGradebook ? 'Back to Grades' : 'Back to Assignments';\n    document.getElementById('backBtn').addEventListener('click', () => {\n      window.location.href = cameFromMaterials ? `/course-materials?${avgCourseQ(course.id)}` : cameFromGradebook ? `/gradebook?${avgCourseQ(course.id)}` : '/assignments';\n    });\n\n    document.getElementById('descText').textContent = detail.description;\n\n    // `actions` adds the Download icon button — used for Attached\n    // Materials rows only, not the Submissions history list, per how\n    // Martin originally scoped this (2026-08-29). **View button removed\n    // (2026-09-03)**: per Martin's material-types scoping decision — real\n    // file preview/editing is coming with the Canva/Drive integrations\n    // already on the roadmap for Release 1.0.0 (\"Preview in Drive\"/\"Edit\n    // in Canva\" — see `claude/updates-roadmap.md`), so a \"View\" action\n    // that only ever opened a \"no live preview\" placeholder modal doesn't\n    // belong in the app before that's real. Download is the one file\n    // action Averages.io offers for now — see the click handler below,\n    // which now triggers a real file download instead of another\n    // placeholder modal.\n    // Attached Materials rows (2026-10-04, per Martin): `actions === 'full'`\n    // draws the landing page's file bar, with Edit in Canva (file types Canva\n    // can open), Save to cloud and Download. `true` is the plain Download-only\n    // row the Submission Preview popup uses.\n    const CANVA_EXTS = ['pdf', 'doc', 'docx', 'ppt', 'pptx', 'xls', 'xlsx', 'key', 'numbers', 'pages', 'odt', 'odp', 'ods', 'png', 'jpg', 'jpeg', 'gif', 'heic', 'ai', 'psd'];\n    // In the preview, Edit in Canva runs the Drafts flow below in memory.\n    // Signed in (2026-10-05) it's real: see liveEditInCanva. Since 10-5 an\n    // Edit button only shows for a connected app (EDIT_READY below), so demo\n    // sessions, where nothing is connected, have none.\n    const CANVA_PREVIEW = !(window.__AVERAGES__ && window.__AVERAGES__.data);\n    // Edit in Google Drive (2026-10-04): Word/PowerPoint/Excel use Google Drive\n    // when Settings > Integrations > Open files in says so.\n    const DRIVE_EXTS = ['doc', 'docx', 'ppt', 'pptx', 'xls', 'xlsx'];\n    const DRIVE_KIND = { doc: ['DOC', '#3b6fd1'], docx: ['DOC', '#3b6fd1'], ppt: ['SLIDES', '#d1852f'], pptx: ['SLIDES', '#d1852f'], xls: ['SHEET', '#2f7d54'], xlsx: ['SHEET', '#2f7d54'] };\n    let EDITOR_PREF = 'canva';\n    try { if (localStorage.getItem('schoolagy_default_editor') === 'gdrive') EDITOR_PREF = 'gdrive'; } catch {}\n    // Which \"Edit in\" app a file gets (2026-10-05, per Martin): only one\n    // that's connected. The preview shows both, as before.\n    const EDIT_READY = { canva: CANVA_PREVIEW, gdrive: CANVA_PREVIEW };\n    // Incognito (2026-10-05, set by LegacyPage.tsx): connected apps are off, so\n    // no Edit buttons and no Save to cloud, and Canva / Google aren't asked anything.\n    const INCOGNITO = !!(window.__AVERAGES_INCOGNITO__ && window.__AVERAGES_INCOGNITO__.on);\n    function editAppFor(ext) {\n      const can = { canva: CANVA_EXTS.includes(ext), gdrive: DRIVE_EXTS.includes(ext) };\n      const order = EDITOR_PREF === 'gdrive' ? ['gdrive', 'canva'] : ['canva', 'gdrive'];\n      return order.find(app => can[app] && EDIT_READY[app]) || null;\n    }\n    const CLOUD_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 18H6.5a4.5 4.5 0 0 1-.6-8.96A6 6 0 0 1 17.6 8.1 4.5 4.5 0 0 1 17.5 18H17\"/><path d=\"M12 20v-8M9 15l3-3 3 3\"/></svg>';\n    function materialRowHTML(m, actions) {\n      const color = EXT_COLOR[m.ext] || '#83849a';\n      const nm = escapeHtml(m.name), ex = escapeHtml(m.ext);\n      const fid = m.fileId ? ` data-file-id=\"${escapeHtml(m.fileId)}\"` : '';   // live attachments (2026-10-05)\n      const tip = (label, inner) => `<span class=\"tipwrap\">${inner}<span class=\"tip\" role=\"tooltip\">${label}</span></span>`;\n      const download = `<button class=\"material-icon-btn\" type=\"button\" data-file-action=\"download\" data-file-name=\"${nm}\" data-file-ext=\"${ex}\"${fid} aria-label=\"Download ${nm}\">${DOWNLOAD_ICON}</button>`;\n      let btns = '', whyBtn = '', whyNote = '';\n      if (actions === 'full') {\n        const ext = String(m.ext || '').toLowerCase();\n        const editApp = editAppFor(ext);\n        // \"Why Canva?\" (2026-10-10, Martin): Google Drive is picked in Settings, but this file gets Canva.\n        if (EDITOR_PREF === 'gdrive' && editApp === 'canva') {\n          const driveCan = DRIVE_EXTS.includes(ext);\n          const label = escapeHtml(String(ext || 'file').toUpperCase());\n          whyBtn = '<br><button class=\"why-btn\" type=\"button\" data-why aria-expanded=\"false\">Why Canva?</button>';\n          whyNote = `<p class=\"why-note\" hidden>${driveCan\n              ? 'You picked Google Drive in Settings, but Google Drive isn’t connected right now, so this opens in Canva. <a href=\"/settings?section=integrations\">Connect Google Drive</a> to edit it there.'\n              : `${label} files always open in Canva. Google Drive can only edit one by turning it into a Google Doc, which usually scrambles the layout. Word, PowerPoint and Excel files open in Google Drive, as you picked in <a href=\"/settings?section=integrations\">Settings</a>.`}</p>`;\n        }\n        const canva = editApp === 'gdrive'\n          ? `<button class=\"canva-btn drive-btn\" type=\"button\" data-file-action=\"gdrive\" data-file-name=\"${nm}\" data-file-ext=\"${ex}\"${fid}${CANVA_PREVIEW || (LIVE && m.fileId) ? '' : ' aria-haspopup=\"menu\"'}><span>Edit in Google Drive</span></button>`\n          : editApp === 'canva'\n          ? `<button class=\"canva-btn\" type=\"button\" data-file-action=\"canva\" data-file-name=\"${nm}\"${fid}${CANVA_PREVIEW || (LIVE && m.fileId) ? '' : ' aria-haspopup=\"menu\"'}><span class=\"canva-mark\" aria-hidden=\"true\"></span><span>Edit in Canva</span></button>` : '';\n        btns = `\n          <div class=\"material-actions\">\n            ${canva}\n            ${tip('Save to cloud', `<button class=\"material-icon-btn\" type=\"button\" data-file-action=\"cloud\" data-file-name=\"${nm}\"${fid} aria-label=\"Save ${nm} to cloud\" aria-haspopup=\"menu\">${CLOUD_ICON}</button>`)}\n            ${tip('Download', download)}\n          </div>`;\n      } else if (actions) {\n        btns = `\n          <div class=\"material-actions\">\n            ${download}\n          </div>`;\n      }\n      return `\n        <div class=\"material-row${actions === 'full' ? ' file-bar' : ''}\">\n          ${fileIcon(m.ext, `<span class=\"material-badge\" style=\"background:${escapeHtml(color)}\">${escapeHtml(String(m.ext || '').toUpperCase())}</span>`)}\n          <span class=\"material-name\">${nm}${whyBtn}</span>\n          ${btns}\n          ${whyNote}\n        </div>`;\n    }\n    // A submission-history entry carries its file(s) as either the older\n    // singular `name`/`ext` fields (every hand-authored DETAILS/generic\n    // entry) or, since 2026-09-04 (per Martin: \"let people upload\n    // multiple files\"), a plural `files` array (every submission made\n    // through the Add Submission modal — see modalSubmitBtn's click\n    // handler further down). Normalizes either shape to an array so\n    // submissionHistoryHTML/openSubmissionPreview only have to handle one\n    // case, the same pattern /messages's attachmentsOf() uses.\n    function filesOf(s) {\n      return Array.isArray(s.files) ? s.files : (s.name ? [{ name: s.name, ext: s.ext }] : []);\n    }\n    // Real client-side download (2026-09-03, per Martin: \"for now we\n    // should just have a download option\") — there's no real backend\n    // holding actual file bytes in this mock, so this generates a small\n    // placeholder text blob and downloads it under the material's real\n    // name/extension via a throwaway <a download> link, rather than\n    // showing another \"isn't available in this preview yet\" dead end.\n    // The download itself is genuinely real (a real browser Save/\n    // Downloads-folder event fires); only the file's *content* is a\n    // stand-in, same honesty convention as Quick Look's own \"no preview\n    // available in this mock\" note elsewhere in the app.\n    function downloadPlaceholderFile(name, ext) {\n      const content = `${name}\\n\\nThis is a placeholder file from the Averages mockup — no real file content is stored yet.\\nReal file delivery is coming with the Drive/Canva integrations (Release 1.0.0).`;\n      const blob = new Blob([content], { type: 'text/plain' });\n      const url = URL.createObjectURL(blob);\n      const a = document.createElement('a');\n      a.href = url;\n      a.download = name;\n      document.body.appendChild(a);\n      a.click();\n      document.body.removeChild(a);\n      setTimeout(() => URL.revokeObjectURL(url), 1000);\n    }\n    const materialsEl = document.getElementById('materialsList');\n    materialsEl.innerHTML = (detail.materials && detail.materials.length)\n      ? detail.materials.map(m => materialRowHTML(m, 'full')).join('')\n      : '<p class=\"assign-empty\">No materials attached to this assignment.</p>';\n\n    // ------------------------------------------------------------------\n    // Signed in (2026-10-05): the real description and Attached Materials\n    // come from the API (GET /data/assignment). Files arrive as ids + names;\n    // the Worker looks up and fetches the real file whenever one is\n    // downloaded or opened in Canva, so no Schoology URL reaches the page.\n    // ------------------------------------------------------------------\n    function averagesApiBase() {\n      // Same rule as app/lib/averages.ts's API_BASE (pages can't import it).\n      return window.location.hostname.endsWith('averages.io') ? 'https://api.averages.io' : 'http://localhost:8787';\n    }\n    const ID_OK = v => /^\\d{1,24}$/.test(String(v || ''));\n    const LIVE_DETAIL = LIVE && ID_OK(item.id) && ID_OK(item.courseId);\n    // Turning in work, signed in with Schoology (2026-10-06): real uploads\n    // through our API with public/js/averages-submit.js. Classroom work is\n    // still turned in on Classroom; the preview and the demo keep the mock.\n    const SUBMIT_LIVE = LIVE_DETAIL && !CLASSROOM;\n    const SUBMIT_MAX_BYTES = 95 * 1024 * 1024;   // the API's limit per file\n    let submitScript = null;\n    function loadSubmitScript() {\n      if (!submitScript) {\n        submitScript = new Promise((resolve, reject) => {\n          if (window.AveragesSubmit) { resolve(window.AveragesSubmit); return; }\n          const sc = document.createElement('script');\n          sc.src = '/js/averages-submit.js';\n          sc.onload = () => (window.AveragesSubmit ? resolve(window.AveragesSubmit) : reject(new Error('submit')));\n          sc.onerror = () => reject(new Error('submit'));\n          document.head.appendChild(sc);\n        }).catch(e => { submitScript = null; throw e; });\n      }\n      return submitScript;\n    }\n    /** This page's own path for Return / Connect, minus our one-off ?canva= message flag. */\n    function currentAppPath() {\n      const u = new URL(window.location.href);\n      u.searchParams.delete('canva');\n      return u.pathname + u.search;\n    }\n    function linkRowHTML(l) {\n      return `\n        <div class=\"material-row file-bar\">\n          ${fileIcon('link', '<span class=\"material-badge\" style=\"background:#4f6b8c\">LINK</span>')}\n          <a class=\"material-name material-link\" href=\"${escapeHtml(l.url)}\" target=\"_blank\" rel=\"noopener noreferrer\">${escapeHtml(l.title)}</a>\n        </div>`;\n    }\n    // Classroom materials are links: Drive files open in Google Drive, plus\n    // web links, YouTube videos and Google Forms.\n    const CLASSROOM_BADGE = { drive: ['DRIVE', '#3b6fd1'], youtube: ['VIDEO', '#c1443a'], form: ['FORM', '#7a4fae'], link: ['LINK', '#4f6b8c'] };\n    function classroomMaterialRowHTML(m) {\n      const ext = (String(m.title || '').match(/\\.([a-z0-9]{1,5})$/i) || [])[1];\n      const u = String(m.url || '');\n      const badge = m.kind !== 'drive' ? (CLASSROOM_BADGE[m.kind] || CLASSROOM_BADGE.link)\n        : ext ? [ext.toUpperCase(), EXT_COLOR[ext.toLowerCase()] || '#3b6fd1']\n        : /^https:\\/\\/docs\\.google\\.com\\/document\\//.test(u) ? ['DOC', '#3b6fd1']\n        : /^https:\\/\\/docs\\.google\\.com\\/spreadsheets\\//.test(u) ? ['SHEET', '#2f7d54']\n        : /^https:\\/\\/docs\\.google\\.com\\/presentation\\//.test(u) ? ['SLIDES', '#d1852f']\n        : CLASSROOM_BADGE.drive;\n      const small = badge[0].length > 4 ? ';font-size:0.44rem;letter-spacing:0' : '';\n      return `\n        <div class=\"material-row file-bar\">\n          ${fileIcon(m.kind === 'youtube' ? 'video' : m.kind === 'form' ? 'gform' : m.kind === 'link' ? 'link' : ext ? ext : ({ DOC: 'gdoc', SHEET: 'gsheet', SLIDES: 'gslide' })[badge[0]] || 'file', `<span class=\"material-badge\" style=\"background:${badge[1]}${small}\">${escapeHtml(badge[0])}</span>`)}\n          <a class=\"material-name material-link\" href=\"${escapeHtml(m.url)}\" target=\"_blank\" rel=\"noopener noreferrer\">${escapeHtml(m.title)}</a>\n        </div>`;\n    }\n    let liveMaterials = null;   // { files, links, materials } once loaded\n    function renderLiveMaterials() {\n      if (!liveMaterials) return;\n      if (liveMaterials.materials) {\n        materialsEl.innerHTML = liveMaterials.materials.map(classroomMaterialRowHTML).join('') || '<p class=\"assign-empty\">No materials attached to this assignment.</p>';\n        return;\n      }\n      const rows = liveMaterials.files.map(f => materialRowHTML({ name: f.name, ext: String(f.ext || '').toLowerCase(), fileId: String(f.id) }, 'full')).join('')\n        + liveMaterials.links.map(linkRowHTML).join('');\n      materialsEl.innerHTML = rows || '<p class=\"assign-empty\">No materials attached to this assignment.</p>';\n    }\n    // Signed in: is Canva connected? (Google Drive is checked in this browser, see loadCloud.)\n    let canvaInfo = null;   // { configured, connected } once known (Add from Canva, 2026-10-06)\n    async function loadCanvaReady() {\n      try {\n        const res = await fetch(averagesApiBase() + '/canva/status', { credentials: 'include' });\n        if (!res.ok) return;\n        const j = await res.json();\n        canvaInfo = { configured: j.configured !== false, connected: !!j.connected };\n        refreshUploadSources();\n        if (!!j.connected !== EDIT_READY.canva) { EDIT_READY.canva = !!j.connected; renderLiveMaterials(); }\n      } catch {\n        /* no Edit in Canva button then */\n      }\n    }\n    function syncDriveReady() {\n      const C = window.AveragesCloud;\n      const ready = !!(C && cloudCfg && cloudCfg.google && C.accounts().gdrive);\n      if (ready !== EDIT_READY.gdrive) { EDIT_READY.gdrive = ready; renderLiveMaterials(); }\n    }\n    async function loadLiveDetail() {\n      const desc = document.getElementById('descText');\n      desc.textContent = 'Loading…';\n      materialsEl.innerHTML = '<p class=\"assign-empty\">Loading attached materials…</p>';\n      try {\n        let tz = '';\n        try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch {}\n        const res = await fetch(`${averagesApiBase()}/data/assignment?section=${encodeURIComponent(item.courseId)}&id=${encodeURIComponent(item.id)}${tz ? '&tz=' + encodeURIComponent(tz) : ''}`, { credentials: 'include' });\n        if (res.status === 401) { window.location.href = '/'; return; }\n        if (!res.ok) throw new Error('status ' + res.status);\n        const d = await res.json();\n        desc.textContent = d.description || 'No description provided by your teacher yet.';\n        liveMaterials = {\n          files: Array.isArray(d.files) ? d.files : [],\n          links: Array.isArray(d.links) ? d.links : [],\n          materials: CLASSROOM && Array.isArray(d.materials) ? d.materials.filter(m => m && /^https?:\\/\\//i.test(String(m.url || ''))).map(m => ({ kind: String(m.kind || 'link'), title: String(m.title || 'Link'), url: String(m.url) })) : null,\n        };\n        renderLiveMaterials();\n        if (CLASSROOM) applyClassroomSubmission(d);\n      } catch {\n        desc.textContent = 'Couldn’t load this assignment’s details right now.';\n        materialsEl.innerHTML = '<p class=\"assign-empty\">Couldn’t load the attached materials.<button class=\"assign-retry\" type=\"button\" data-live-retry>Try again</button></p>';\n      }\n    }\n    if (LIVE) {\n      if (LIVE_DETAIL) loadLiveDetail();\n      else materialsEl.innerHTML = '<p class=\"assign-empty\">No materials attached to this assignment.</p>';\n    }\n\n    // A small popup for anything that stops Edit in Canva. Connect sends the\n    // student through Canva and back to this same page.\n    function showCanvaProblem(code) {\n      const connect = code === 'canva_not_connected' || code === 'canva_reconnect_needed';\n      const MSG = {\n        canva_not_connected: ['Connect Canva first', 'Edit in Canva opens assignment files in your own Canva account. Connect it once and this button works from then on.'],\n        canva_reconnect_needed: ['Reconnect Canva', 'Your Canva connection ran out. Connect it again to keep editing.'],\n        canva_not_configured: ['Canva is coming soon', 'Editing in Canva isn’t switched on yet.'],\n        canva_missing_permission: ['Canva needs permission', 'Disconnect and connect Canva again in Settings, and allow access when Canva asks.'],\n        canva_duplicate_import: ['Already in your Canva', 'This file was opened in Canva before. Find it in your Canva account or on the Files tab.'],\n        canva_rate_limited: ['Canva is busy', 'Too many files were opened at once. Try again in a minute.'],\n        canva_invalid_file: ['Canva can’t open this file', 'Download it instead and open it another way.'],\n        file_too_large: ['This file is too big for Canva', 'Files over 25 MB can’t be opened in Canva from Averages.io. Download it instead.'],\n        file_not_found: ['File not found', 'This file isn’t on the assignment anymore. Reload the page to see what’s attached now.'],\n        canva_design_gone: ['Design not found', 'This draft was deleted in Canva, so it’s been removed from Drafts.'],\n      };\n      const [title, text] = MSG[code] || ['Couldn’t open this in Canva', 'Something went wrong. Try again in a moment.'];\n      openModal(`\n        <h3>${escapeHtml(title)}</h3>\n        <p>${escapeHtml(text)}</p>\n        <div class=\"modal-actions\">\n          ${connect\n            ? '<button class=\"modal-btn secondary\" type=\"button\" id=\"canvaProbCancel\">Not now</button><button class=\"modal-btn primary\" type=\"button\" id=\"canvaProbConnect\">Connect Canva</button>'\n            : '<button class=\"modal-btn primary\" type=\"button\" id=\"canvaProbCancel\">OK</button>'}\n        </div>`);\n      modalBox.setAttribute('role', 'alertdialog'); modalBox.setAttribute('aria-modal', 'true');\n      document.getElementById('canvaProbCancel').addEventListener('click', closeModal);\n      const go = document.getElementById('canvaProbConnect');\n      if (go) go.addEventListener('click', () => { window.location.href = `${averagesApiBase()}/canva/connect?return_to=${encodeURIComponent(currentAppPath())}`; });\n      (go || document.getElementById('canvaProbCancel')).focus();\n    }\n    const CANVA_EDIT_URL = /^https:\\/\\/(www\\.)?canva\\.com\\//i;\n\n    // ---- Canva opens in this tab again (2026-10-09, Martin: \"can Canva not\n    // open in another tab anymore\"). Canva's Return button brings the\n    // student back here. (2026-10-07 to 10-09 it opened in a new tab; the\n    // helpers stay so that's a one-line change: NEW_TAB.)\n    const CANVA_NEW_TAB = false;\n    function openCanvaTab() {\n      if (!CANVA_NEW_TAB) return null;\n      let tab = null;\n      try { tab = window.open('', '_blank'); } catch {}\n      if (!tab) return null;\n      try {\n        tab.opener = null;\n        tab.document.title = 'Opening Canva…';\n        tab.document.body.style.cssText = 'margin:0;display:grid;place-items:center;height:100vh;font:600 16px -apple-system,system-ui,sans-serif;color:#555;background:#f4f4f6';\n        tab.document.body.textContent = 'Opening Canva…';\n      } catch {}\n      return tab;\n    }\n    /** Sends the tab to Canva; true when it went there (this page stays). */\n    function sendToCanva(tab, url) {\n      if (tab && !tab.closed) { try { tab.location.replace(url); return true; } catch {} }\n      window.location.assign(url);\n      return false;\n    }\n    function closeCanvaTab(tab) { try { if (tab && !tab.closed) tab.close(); } catch {} }\n    async function liveEditInCanva(btn) {\n      if (btn.getAttribute('aria-busy') === 'true') return;\n      const label = btn.querySelector('span:last-child');\n      const was = label ? label.textContent : '';\n      btn.setAttribute('aria-busy', 'true');\n      if (label) label.textContent = 'Opening Canva…';\n      const done = () => { btn.removeAttribute('aria-busy'); if (label) label.textContent = was; };\n      const tab = openCanvaTab();\n      try {\n        const res = await fetch(averagesApiBase() + '/canva/edit', {\n          method: 'POST',\n          credentials: 'include',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ section: String(item.courseId), assignment: String(item.id), fileId: btn.dataset.fileId, returnTo: currentAppPath() }),\n        });\n        const j = await res.json().catch(() => ({}));\n        if (res.ok && typeof j.editUrl === 'string' && CANVA_EDIT_URL.test(j.editUrl)) {\n          if (j.draft) { upsertLiveDraft(j.draft); renderDrafts(); }\n          if (sendToCanva(tab, j.editUrl)) done();   // same tab only if pop-ups are blocked\n          return;\n        }\n        closeCanvaTab(tab);\n        done();\n        showCanvaProblem(j.error);\n      } catch {\n        closeCanvaTab(tab);\n        done();\n        showCanvaProblem('network');\n      }\n    }\n\n    // ------------------------------------------------------------------\n    // Google Drive and OneDrive, signed in (2026-10-05). Both run in this\n    // browser with public/js/averages-cloud.js: the file comes from our API\n    // (/data/attachment) and goes straight to the student's own drive, into\n    // an \"Averages.io\" folder. Their Google/Microsoft tokens never reach our\n    // servers. Sign-in windows must open inside the click, so the token is\n    // asked for before anything is awaited.\n    // ------------------------------------------------------------------\n    let cloudCfg = null;   // null until loaded: { google, microsoft }\n    const CLOUD_NAME = { gdrive: 'Google Drive', onedrive: 'OneDrive' };\n    // Where saved files go: a folder Averages.io makes in Drive, and OneDrive's app folder (all it can reach).\n    const CLOUD_WHERE = { gdrive: 'the Averages.io folder in your Google Drive', onedrive: 'the Apps/Averages.io folder in your OneDrive' };\n    function loadCloudScript() {\n      return new Promise((resolve, reject) => {\n        if (window.AveragesCloud) { resolve(window.AveragesCloud); return; }\n        const sc = document.createElement('script');\n        sc.src = '/js/averages-cloud.js';\n        sc.onload = () => (window.AveragesCloud ? resolve(window.AveragesCloud) : reject(new Error('cloud')));\n        sc.onerror = () => reject(new Error('cloud'));\n        document.head.appendChild(sc);\n      });\n    }\n    async function loadCloud() {\n      try {\n        const C = await loadCloudScript();\n        const cfg = await C.config();\n        if (cfg.failed) return;\n        cloudCfg = cfg;\n        if (cfg.google) C.prepareGoogle().catch(() => {});\n        syncDriveReady();\n        refreshUploadSources();   // Add from Google Drive / OneDrive (2026-10-06)\n        window.addEventListener('averages-cloud-change', syncDriveReady);\n        mergeDrafts();\n        if (await C.refreshDriveDrafts(String(item.courseId), String(item.id))) mergeDrafts();\n      } catch {\n        /* Save to cloud just says Coming soon */\n      }\n    }\n    function attachmentSource(btn) {\n      return { section: String(item.courseId), assignment: String(item.id), fileId: btn.dataset.fileId, name: btn.dataset.fileName || 'File' };\n    }\n    function showCloudProblem(title, err) {\n      const C = window.AveragesCloud;\n      const code = err && err.code ? err.code : String(err || '');\n      openModal(`\n        <h3>${escapeHtml(title)}</h3>\n        <p>${escapeHtml(C ? C.messageFor(err) : 'Something went wrong. Try again in a moment.')}</p>\n        <div class=\"modal-actions\">\n          ${code === 'signed_out' ? '<button class=\"modal-btn primary\" type=\"button\" id=\"cloudProbOk\">Sign in</button>' : '<button class=\"modal-btn primary\" type=\"button\" id=\"cloudProbOk\">OK</button>'}\n        </div>`);\n      modalBox.setAttribute('role', 'alertdialog'); modalBox.setAttribute('aria-modal', 'true');\n      const ok = document.getElementById('cloudProbOk');\n      ok.addEventListener('click', () => { if (code === 'signed_out') window.location.href = '/'; else closeModal(); });\n      ok.focus();\n    }\n    function showOpenLink(title, text, url, linkLabel) {\n      const C = window.AveragesCloud;\n      const link = C && C.linkOk(url)\n        ? `<a class=\"modal-btn primary\" id=\"cloudOpenLink\" href=\"${escapeHtml(url)}\" target=\"_blank\" rel=\"noopener noreferrer\">${escapeHtml(linkLabel)}</a>` : '';\n      openModal(`\n        <h3>${escapeHtml(title)}</h3>\n        <p>${escapeHtml(text)}</p>\n        <div class=\"modal-actions\">\n          <button class=\"modal-btn ${link ? 'secondary' : 'primary'}\" type=\"button\" id=\"cloudOpenDone\">Done</button>\n          ${link}\n        </div>`);\n      document.getElementById('cloudOpenDone').addEventListener('click', closeModal);\n      const a = document.getElementById('cloudOpenLink');\n      if (a) a.addEventListener('click', () => setTimeout(closeModal, 0));\n      (a || document.getElementById('cloudOpenDone')).focus();\n    }\n    /** Asks for the token inside the click (it may open a sign-in window). */\n    function cloudToken(C, app) {\n      if (app === 'gdrive') {\n        if (!C.googleReady()) { C.prepareGoogle().catch(() => {}); return Promise.reject({ code: 'not_ready' }); }\n        return C.googleSession({ interactive: true });\n      }\n      return C.oneDriveToken({ interactive: true });\n    }\n    function saveToCloud(app, btn) {\n      const C = window.AveragesCloud;\n      const name = CLOUD_NAME[app];\n      if (!C) { showCloudProblem(`Couldn’t save to ${name}`, 'not_ready'); return; }\n      const src = attachmentSource(btn);\n      const pending = cloudToken(C, app);\n      openModal(`\n        <h3>Saving to ${escapeHtml(name)}…</h3>\n        <p>Copying \"${escapeHtml(src.name)}\" to ${escapeHtml(CLOUD_WHERE[app])}. If a sign-in window opened, finish there first.</p>`);\n      modalBox.setAttribute('aria-busy', 'true');\n      pending\n        .then(async token => {\n          const blob = await C.fetchAttachment(src);\n          return app === 'gdrive' ? C.googleUpload(token, { name: src.name, blob }) : C.oneDriveUpload(token, { name: src.name, blob });\n        })\n        .then(f => {\n          modalBox.removeAttribute('aria-busy');\n          syncDriveReady();\n          showOpenLink(`Saved to ${name}`, `\"${f.name || src.name}\" is in ${CLOUD_WHERE[app]}.`, f.webViewLink || f.webUrl, `Open in ${name}`);\n        })\n        .catch(err => {\n          modalBox.removeAttribute('aria-busy');\n          if (err && err.code === 'popup_closed') { closeModal(); return; }\n          showCloudProblem(`Couldn’t save to ${name}`, err);\n        });\n    }\n    function liveEditInDrive(btn) {\n      if (btn.getAttribute('aria-busy') === 'true') return;\n      const C = window.AveragesCloud;\n      if (!C || !cloudCfg) { showCloudProblem('Couldn’t open this in Google Drive', 'not_ready'); return; }\n      if (!cloudCfg.google) { showCloudProblem('Google Drive is coming soon', 'not_configured'); return; }\n      const src = attachmentSource(btn);\n      // Already signed in to Google in this tab: the new tab opens now, inside\n      // this click, and the file loads into it when it's ready. Otherwise this\n      // click goes to Google's sign-in window, and the file opens from a link.\n      const signedIn = C.hasToken('gdrive') && C.googleReady();\n      const pending = cloudToken(C, 'gdrive');\n      let tab = null;\n      if (signedIn) {\n        try {\n          tab = window.open('', '_blank');\n          if (tab) {\n            tab.opener = null;\n            tab.document.title = 'Opening Google Drive…';\n            tab.document.body.style.font = '15px system-ui, sans-serif';\n            tab.document.body.textContent = 'Opening Google Drive…';\n          }\n        } catch { tab = null; }\n      }\n      const label = btn.querySelector('span:last-child');\n      const was = label ? label.textContent : '';\n      btn.setAttribute('aria-busy', 'true');\n      if (label) label.textContent = 'Opening Google Drive…';\n      const done = () => { btn.removeAttribute('aria-busy'); if (label) label.textContent = was; };\n      pending\n        .then(token => C.editInGoogleDrive(token, src))\n        .then(d => {\n          done();\n          mergeDrafts();\n          const row = draftsList.querySelector(`[data-draft=\"g-${CSS.escape(d.fileId)}\"]`);\n          if (row) { row.scrollIntoView({ block: 'nearest', behavior: reduceMotion() ? 'auto' : 'smooth' }); pulse(row); }\n          if (tab && !tab.closed && C.linkOk(d.webViewLink)) { tab.location.href = d.webViewLink; return; }\n          if (tab) { try { tab.close(); } catch {} }\n          showOpenLink('Ready in Google Drive', `\"${d.name}\" is in your Google Drive and in Drafts here.`, d.webViewLink, 'Open in Google Drive');\n        })\n        .catch(err => {\n          done();\n          if (tab) { try { tab.close(); } catch {} }\n          if (err && err.code === 'popup_closed') return;\n          showCloudProblem('Couldn’t open this in Google Drive', err);\n        });\n    }\n\n    // ------------------------------------------------------------------\n    // Shared small modal — Add Submission and the View/Download file\n    // info both open into this one overlay.\n    // ------------------------------------------------------------------\n    const modalOverlay = document.getElementById('modalOverlay');\n    const modalBox = document.getElementById('modalBox');\n    function openModal(html) { modalBox.innerHTML = html; modalOverlay.hidden = false; }\n    // Also strips the wider modal-box-lg modifier (see openAddSubmissionModal)\n    // so the NEXT modal opened -- e.g. a small file-info popup -- isn't left\n    // oversized from a previous Add Submission session.\n    // A turn-in still running when its popup closes (Cancel, Escape) is\n    // stopped (2026-10-06): nothing is turned in unless it got that far.\n    let activeSubmitAbort = null;\n    function closeModal() { if (activeSubmitAbort) { const stop = activeSubmitAbort; activeSubmitAbort = null; stop(); } modalOverlay.hidden = true; modalBox.innerHTML = ''; modalBox.classList.remove('modal-box-lg'); modalBox.removeAttribute('role'); modalBox.removeAttribute('aria-modal'); }\n    // Static popup (2026-08-29, per Martin's request) — clicking the dark\n    // backdrop no longer dismisses the modal, so an accidental click outside\n    // the box (easy to do on the Add Submission modal while picking a tab or\n    // a file) can't lose in-progress input. Escape and the explicit\n    // Cancel/Close buttons still close it.\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !modalOverlay.hidden) closeModal(); });\n\n    // Edit in Canva / Save to cloud menus (2026-10-04). Not connected yet, so\n    // every choice says Coming soon, same as the Materials page.\n    const fileMenu = document.createElement('div');\n    fileMenu.className = 'file-menu';\n    fileMenu.setAttribute('role', 'menu');\n    fileMenu.hidden = true;\n    document.body.appendChild(fileMenu);\n    let fileMenuFor = null;\n    function closeFileMenu() {\n      if (fileMenu.hidden) return;\n      fileMenu.hidden = true;\n      if (fileMenuFor) { fileMenuFor.setAttribute('aria-expanded', 'false'); fileMenuFor = null; }\n    }\n    function openFileMenu(btn, kind) {\n      if (fileMenuFor === btn) { closeFileMenu(); return; }\n      closeFileMenu();\n      const name = btn.dataset.fileName || 'this file';\n      const items = kind === 'canva' ? ['Open in Canva'] : kind === 'gdrive' ? ['Open in Google Drive'] : ['Google Drive', 'OneDrive'];   // OneDrive back 2026-10-05\n      const editIn = kind === 'canva' ? 'Canva' : kind === 'gdrive' ? 'Google Drive' : '';\n      fileMenu.setAttribute('aria-label', editIn ? `Edit in ${editIn}` : 'Save to cloud');\n      // Signed in (2026-10-05): Save to cloud is real for whichever app is set up.\n      const liveSave = kind === 'cloud' && LIVE_DETAIL && ID_OK(btn.dataset.fileId) && cloudCfg && !INCOGNITO;\n      const ready = { 'Google Drive': liveSave && !!cloudCfg.google, OneDrive: liveSave && !!cloudCfg.microsoft };\n      const appId = { 'Google Drive': 'gdrive', OneDrive: 'onedrive' };\n      fileMenu.innerHTML = `<div class=\"file-menu-label\">${editIn ? 'Edit' : 'Save'} \"${escapeHtml(name)}\" ${editIn ? 'in ' + editIn : 'to'}</div>` +\n        items.map(n => ready[n]\n          ? `<button class=\"file-menu-item\" type=\"button\" role=\"menuitem\" data-save=\"${appId[n]}\"><span>${n}<small>${appId[n] === 'onedrive' ? 'Into Apps/Averages.io' : 'Into an Averages.io folder'}</small></span></button>`\n          : `<button class=\"file-menu-item\" type=\"button\" role=\"menuitem\" disabled><span>${n}</span><span class=\"soon\">${INCOGNITO ? 'Off in Incognito' : 'Coming soon'}</span></button>`).join('');\n      fileMenu.hidden = false;\n      const r = btn.getBoundingClientRect(), w = fileMenu.offsetWidth, h = fileMenu.offsetHeight;\n      fileMenu.style.left = Math.max(8, Math.min(r.right - w, window.innerWidth - w - 8)) + 'px';\n      fileMenu.style.top = (r.bottom + 6 + h > window.innerHeight - 8 ? Math.max(8, r.top - h - 6) : r.bottom + 6) + 'px';\n      btn.setAttribute('aria-expanded', 'true');\n      fileMenuFor = btn;\n      const first = fileMenu.querySelector('.file-menu-item:not(:disabled)');\n      if (first) first.focus();\n    }\n    fileMenu.addEventListener('click', e => {\n      const it = e.target.closest('[data-save]');\n      if (!it || !fileMenuFor) return;\n      const btn = fileMenuFor;\n      closeFileMenu();\n      saveToCloud(it.dataset.save, btn);\n    });\n    document.addEventListener('click', e => { if (!fileMenu.hidden && !fileMenu.contains(e.target) && !(fileMenuFor && fileMenuFor.contains(e.target))) closeFileMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !fileMenu.hidden) { const b = fileMenuFor; closeFileMenu(); if (b) b.focus(); } });\n    window.addEventListener('scroll', closeFileMenu, true);\n    window.addEventListener('resize', closeFileMenu);\n\n    materialsEl.addEventListener('click', e => {\n      if (e.target.closest('[data-live-retry]')) { loadLiveDetail(); return; }\n      const whyBtn = e.target.closest('[data-why]');\n      if (whyBtn) {\n        const note = whyBtn.closest('.material-row').querySelector('.why-note');\n        const open = whyBtn.getAttribute('aria-expanded') !== 'true';\n        whyBtn.setAttribute('aria-expanded', String(open));\n        if (note) note.hidden = !open;\n        return;\n      }\n      const btn = e.target.closest('[data-file-action]');\n      if (!btn) return;\n      const liveFile = LIVE_DETAIL && ID_OK(btn.dataset.fileId);\n      if (btn.dataset.fileAction === 'download' && liveFile) {\n        // The real file, streamed through the API (it answers as a download, so the page stays put).\n        window.location.href = `${averagesApiBase()}/data/attachment?section=${encodeURIComponent(item.courseId)}&assignment=${encodeURIComponent(item.id)}&file=${encodeURIComponent(btn.dataset.fileId)}`;\n      }\n      else if (btn.dataset.fileAction === 'download') downloadPlaceholderFile(btn.dataset.fileName, btn.dataset.fileExt);\n      else if ((btn.dataset.fileAction === 'canva' || btn.dataset.fileAction === 'gdrive') && CANVA_PREVIEW) { closeFileMenu(); editInCanvaPreview(btn); }\n      else if (btn.dataset.fileAction === 'canva' && liveFile) { closeFileMenu(); liveEditInCanva(btn); }\n      else if (btn.dataset.fileAction === 'gdrive' && liveFile) { closeFileMenu(); liveEditInDrive(btn); }\n      else openFileMenu(btn, btn.dataset.fileAction);\n    });\n    // Same download delegation as the Attached Materials list above, but\n    // scoped to the modal itself -- covers the Submission Preview\n    // popup's per-file Download buttons (see openSubmissionPreview),\n    // which can now list more than one file per turn-in.\n    modalBox.addEventListener('click', e => {\n      const btn = e.target.closest('[data-file-action=\"download\"]');\n      if (!btn) return;\n      downloadPlaceholderFile(btn.dataset.fileName, btn.dataset.fileExt);\n    });\n\n    // ------------------------------------------------------------------\n    // Submissions panel — banner + status-specific body. An assignment\n    // can be submitted more than once (2026-08-29, per Martin's request),\n    // so this is now re-rendered from mutable state every time a new\n    // attempt is added, rather than drawn once from static data.\n    // ------------------------------------------------------------------\n    let submissionHistory = (detail.submissions || []).slice();\n    // Signed in with Schoology (2026-10-06): the real turn-ins, newest first,\n    // from GET /submit/history. `pending` is a just-made turn-in kept on top\n    // until Schoology lists it too.\n    const liveHistory = { state: 'loading', revisions: [], pending: null, seq: 0 };\n    let currentStatus = item.status;\n    const previousScore = (item.status === 'graded' && typeof item.score === 'number') ? item.score : null;\n\n    const BANNER_COPY = {\n      overdue: () => ({ label: 'Missing: nothing submitted', meta: item.due ? `Was due ${item.due}` : '' }),\n      upcoming: () => ({ label: 'Not submitted yet', meta: item.due ? `Due ${item.due}` : '' }),\n      submitted: () => {\n        const latest = submissionHistory[submissionHistory.length - 1];\n        let meta = latest ? `Submitted ${latest.timestamp}` : '';\n        if (previousScore !== null) meta += meta ? ` · previously graded ${previousScore}%` : `Previously graded ${previousScore}%`;\n        return { label: 'Submitted: awaiting grade', meta };\n      },\n      graded: () => ({ label: 'Graded', meta: typeof item.score === 'number' ? `${item.score}%` : '' }),\n      returned: () => ({ label: 'Returned: revision requested', meta: item.returnedOn ? `Returned ${item.returnedOn}` : '' }),\n    };\n    // Google Classroom's own words for its states (2026-10-05).\n    let classroomLink = '';\n    let classroomLate = false;\n    const CLASSROOM_URL = u => /^https:\\/\\/classroom\\.google\\.com\\//.test(String(u || ''));\n    if (CLASSROOM) {\n      BANNER_COPY.overdue = () => ({ label: 'Missing: not turned in', meta: item.due ? `Was due ${item.due}` : '' });\n      BANNER_COPY.upcoming = () => ({ label: 'Not turned in yet', meta: item.due ? `Due ${item.due}` : '' });\n      BANNER_COPY.submitted = () => ({ label: 'Turned in: awaiting grade', meta: classroomLate ? 'Turned in late' : '' });\n      BANNER_COPY.graded = () => ({ label: 'Graded', meta: typeof item.score === 'number' ? `${item.score}%${item.points ? ' · ' + item.points + ' points' : ''}` : '' });\n      BANNER_COPY.returned = () => ({ label: 'Returned by your teacher', meta: '' });\n    }\n    if (SUBMIT_LIVE) {\n      BANNER_COPY.submitted = () => {\n        const latest = liveHistory.revisions.find(r => !r.draft);\n        let meta = latest ? `Submitted ${revWhen(latest)}${latest.late ? ' · Late' : ''}` : '';\n        if (previousScore !== null) meta += meta ? ` · previously graded ${previousScore}%` : `Previously graded ${previousScore}%`;\n        return { label: 'Submitted: awaiting grade', meta };\n      };\n    }\n    /** The student's real state on Classroom, from /data/assignment. */\n    function applyClassroomSubmission(d) {\n      classroomLink = CLASSROOM_URL(d.classroomUrl) ? String(d.classroomUrl) : '';\n      const s = d.submission || {};\n      classroomLate = s.late === true;\n      if (d.due) item.due = String(d.due);\n      if (s.state === 'unknown') { renderSubmissionsPanel(); return; }   // Classroom didn't say: keep the list's status\n      if (s.state === 'turned_in') currentStatus = 'submitted';\n      else if (s.state === 'returned') {\n        if (typeof s.grade === 'number' && typeof s.maxPoints === 'number' && s.maxPoints > 0) {\n          currentStatus = 'graded';\n          item.score = Math.round(s.grade / s.maxPoints * 100);\n          item.points = `${s.grade}/${s.maxPoints}`;\n        } else currentStatus = 'returned';\n      } else {\n        const due = d.dueAt ? new Date(d.dueAt) : null;\n        currentStatus = due && !isNaN(due) && due < new Date() ? 'overdue' : 'upcoming';\n      }\n      renderSubmissionsPanel();\n    }\n\n    // Rows are clickable (2026-08-31, per Martin's request) — each one\n    // is a specific turn-in, so clicking it pops up a preview plus that\n    // turn-in's own teacher comments (see openSubmissionPreview below)\n    // instead of the teacher feedback sitting as one static block under\n    // the whole list. `data-sub-index` is the row's real index into\n    // `submissionHistory` (oldest-first), not its on-screen position —\n    // the array itself is only reordered for display, via the trailing\n    // `.reverse()` on the rendered HTML strings, so the index each row\n    // carries stays stable regardless of display order.\n    function submissionHistoryHTML() {\n      if (!submissionHistory.length) return '<p class=\"assign-empty\">No submission on record.</p>';\n      return submissionHistory.map((s, idx) => {\n        const files = filesOf(s);\n        const first = files[0] || { name: 'Untitled', ext: '' };\n        const color = EXT_COLOR[first.ext] || '#83849a';\n        const isLatest = idx === submissionHistory.length - 1;\n        // Multiple files in one turn-in (2026-09-04, per Martin) show as\n        // a count badge + \"N files\" rather than trying to cram every\n        // filename onto one row -- the full list is one click away in\n        // openSubmissionPreview.\n        const badgeLabel = files.length > 1 ? String(files.length) : first.ext.toUpperCase();\n        const nameLabel = files.length > 1 ? `${files.length} files` : first.name;\n        return `\n          <div class=\"material-row submission-row\" tabindex=\"0\" role=\"button\" data-sub-index=\"${idx}\" aria-label=\"Preview ${escapeHtml(nameLabel)}, submitted ${escapeHtml(s.timestamp)}\">\n            ${files.length > 1 ? `<span class=\"material-badge\" style=\"background:${escapeHtml(color)}\">${escapeHtml(badgeLabel)}</span>` : fileIcon(first.ext, `<span class=\"material-badge\" style=\"background:${escapeHtml(color)}\">${escapeHtml(badgeLabel)}</span>`)}\n            <span class=\"material-name\">${escapeHtml(nameLabel)} <span style=\"color:var(--text-faint); font-weight:600;\">— ${escapeHtml(s.timestamp)}</span></span>\n            ${isLatest && submissionHistory.length > 1 ? '<span class=\"submission-latest-tag\">Latest</span>' : ''}\n            ${s.comment ? COMMENT_ICON : ''}\n          </div>`;\n      }).reverse().join('');\n    }\n\n    // Preview + teacher comments popup for one submission-history row\n    // (2026-08-31, per Martin's request — submissions weren't clickable\n    // at all before). Reuses the same shared openModal()/closeModal()\n    // component the Attached Materials View/Download buttons and Add\n    // Submission already use, so it looks and behaves like every other\n    // popup in this app. Only the LATEST submission can carry the\n    // assignment's current teacher feedback/comment — an older,\n    // superseded attempt shows a plain \"no feedback on this one\" note,\n    // since real feedback is given on the most recent turn-in, not every\n    // one in the history.\n    function openSubmissionPreview(idx) {\n      const s = submissionHistory[idx];\n      if (!s) return;\n      const files = filesOf(s);\n      const isLatest = idx === submissionHistory.length - 1;\n      let feedbackHtml = '';\n      if (isLatest && currentStatus === 'graded' && detail.feedback) {\n        feedbackHtml = `\n          <div class=\"feedback-box\">\n            <span class=\"feedback-box-label\" style=\"color:var(--grade-good);\">Teacher Feedback</span>\n            <p>\"${escapeHtml(detail.feedback)}\"</p>\n            <span class=\"attrib\">— ${escapeHtml(course.teacher)}</span>\n          </div>`;\n      } else if (isLatest && currentStatus === 'returned' && detail.comment) {\n        feedbackHtml = `\n          <div class=\"feedback-box returned\">\n            <span class=\"feedback-box-label\">Teacher Comment · Revision requested</span>\n            <p>\"${escapeHtml(detail.comment)}\"</p>\n            <span class=\"attrib\">— ${escapeHtml(course.teacher)}</span>\n          </div>`;\n      } else {\n        feedbackHtml = `<p class=\"assign-empty\" style=\"margin-top:14px;\">No teacher feedback on this submission yet.</p>`;\n      }\n      const ownCommentHtml = s.comment ? `\n        <div class=\"own-comment-box\">\n          <span class=\"label\">Your comment</span>\n          \"${escapeHtml(s.comment)}\"\n        </div>` : '';\n      // Title/subhead read naturally whether this turn-in was one file or\n      // several (2026-09-04, per Martin's multi-file request). Each file\n      // gets its own row + Download button (materialRowHTML(f, true),\n      // same component Attached Materials uses) instead of the single\n      // \"Download\" action this modal used to have — the delegated\n      // [data-file-action=\"download\"] listener on modalBox (see where\n      // modalBox is declared) handles all of them, one file or many.\n      const titleLabel = files.length > 1 ? `${files.length} files` : (files[0] ? files[0].name : 'Submission');\n      openModal(`\n        <h3>${escapeHtml(titleLabel)}</h3>\n        <p>Submitted ${escapeHtml(s.timestamp)}<br>No live preview is available in this mock.</p>\n        <div class=\"modal-file-list\">${files.map(f => materialRowHTML(f, true)).join('')}</div>\n        ${ownCommentHtml}\n        ${feedbackHtml}\n        <div class=\"modal-actions\">\n          <button class=\"modal-btn primary\" type=\"button\" id=\"modalCloseBtn\">Close</button>\n        </div>`);\n      document.getElementById('modalCloseBtn').addEventListener('click', closeModal);\n    }\n\n    const submissionBodyEl = document.getElementById('submissionBody');\n    submissionBodyEl.addEventListener('click', e => {\n      if (e.target.closest('[data-history-retry]')) { liveHistory.state = 'loading'; renderSubmissionsPanel(); loadLiveHistory(); return; }\n      const rev = e.target.closest('[data-rev-index]');\n      if (rev) { openRevisionPreview(Number(rev.dataset.revIndex)); return; }\n      const row = e.target.closest('[data-sub-index]');\n      if (!row) return;\n      openSubmissionPreview(Number(row.dataset.subIndex));\n    });\n    submissionBodyEl.addEventListener('keydown', e => {\n      if (e.key !== 'Enter' && e.key !== ' ') return;\n      const rev = e.target.closest('[data-rev-index]');\n      if (rev) { e.preventDefault(); openRevisionPreview(Number(rev.dataset.revIndex)); return; }\n      const row = e.target.closest('[data-sub-index]');\n      if (!row) return;\n      e.preventDefault();\n      openSubmissionPreview(Number(row.dataset.subIndex));\n    });\n    // Signed in (2026-10-06): files dropped on \"Nothing turned in yet\" open\n    // Add Submission with them already picked.\n    const dropZoneOf = e => SUBMIT_LIVE && e.target.closest && e.target.closest('[data-dropzone]');\n    submissionBodyEl.addEventListener('dragover', e => {\n      const zone = dropZoneOf(e);\n      if (!zone || !e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes('Files')) return;\n      e.preventDefault();\n      e.dataTransfer.dropEffect = 'copy';\n      zone.classList.add('dragging');\n    });\n    submissionBodyEl.addEventListener('dragleave', e => {\n      const zone = dropZoneOf(e);\n      if (zone && !zone.contains(e.relatedTarget)) zone.classList.remove('dragging');\n    });\n    submissionBodyEl.addEventListener('drop', e => {\n      const zone = dropZoneOf(e);\n      if (!zone) return;\n      e.preventDefault();\n      zone.classList.remove('dragging');\n      const files = Array.from((e.dataTransfer && e.dataTransfer.files) || []);\n      if (files.length) openAddSubmissionModal({ files });\n    });\n\n    // ------------------------------------------------------------------\n    // Submission History, signed in with Schoology (2026-10-06). Every\n    // field comes from Schoology through our API, so all of it is escaped.\n    // ------------------------------------------------------------------\n    const fmtSize = n => n < 1024 ? `${n} B` : n < 1048576 ? `${Math.round(n / 1024)} KB` : `${(n / 1048576).toFixed(1)} MB`;\n    function revWhen(r) {\n      if (r && typeof r.when === 'string' && r.when.trim()) return r.when.trim().slice(0, 60);\n      const t = Number(r && r.created) || 0;\n      if (!t) return 'just now';\n      return new Date(t < 1e12 ? t * 1000 : t).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });\n    }\n    function revFiles(r) {\n      return (Array.isArray(r.files) ? r.files : [])\n        .filter(f => f && (typeof f.name === 'string' || typeof f.name === 'number') && String(f.name).trim())\n        .map(f => {\n          const name = String(f.name).trim().slice(0, 300);\n          return { name, ext: ((name.match(/\\.([a-z0-9]{1,5})$/i) || [])[1] || '').toLowerCase(), size: Number(f.size) > 0 ? Number(f.size) : 0 };\n        });\n    }\n    function revisionRowHTML(r, idx) {\n      const files = revFiles(r);\n      const text = typeof r.text === 'string' ? r.text.trim() : '';\n      const first = files[0];\n      const badge = files.length > 1 ? String(files.length) : first ? (first.ext || 'file').toUpperCase().slice(0, 4) : 'TEXT';\n      const color = files.length === 1 ? (EXT_COLOR[first.ext] || '#83849a') : files.length ? '#83849a' : '#4f6b8c';\n      const label = files.length > 1 ? `${files.length} files` : first ? first.name : 'Written answer';\n      const when = revWhen(r);\n      const tags = (idx === 0 && liveHistory.revisions.length > 1 ? '<span class=\"submission-latest-tag\">Latest</span>' : '')\n        + (r.late === true ? '<span class=\"submission-latest-tag late\">Late</span>' : '')\n        + (r.draft === true ? '<span class=\"submission-latest-tag draft\">Draft</span>' : '');\n      return `\n          <div class=\"material-row submission-row\" tabindex=\"0\" role=\"button\" data-rev-index=\"${idx}\" aria-label=\"${escapeHtml(`${label}, ${r.draft === true ? 'saved' : 'turned in'} ${when}${r.late === true ? ', late' : ''}`)}\">\n            ${files.length > 1 ? `<span class=\"material-badge\" style=\"background:${color}\">${escapeHtml(badge)}</span>` : fileIcon(first ? first.ext : 'txt', `<span class=\"material-badge\" style=\"background:${color}\">${escapeHtml(badge)}</span>`)}\n            <span class=\"rev-main\">\n              <span class=\"material-name\">${escapeHtml(label)} <span class=\"rev-when\">· ${escapeHtml(when)}</span></span>\n              ${text && !files.length ? `<span class=\"rev-snippet\">${escapeHtml(text.slice(0, 160))}</span>` : ''}\n            </span>\n            ${tags}\n          </div>`;\n    }\n    function liveHistoryHTML() {\n      if (liveHistory.state === 'loading') return '<p class=\"assign-empty\">Loading your submissions…</p>';\n      if (liveHistory.state === 'error') return '<p class=\"assign-empty\">Couldn’t load your submissions.<button class=\"assign-retry\" type=\"button\" data-history-retry>Try again</button></p>';\n      if (!liveHistory.revisions.length) return `\n          <div class=\"submit-dropzone live-drop\" data-dropzone>\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 16V4M12 4l-5 5M12 4l5 5\"/><path d=\"M4 16v3a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-3\"/></svg>\n            <div>Nothing turned in yet. Drop files here, or use Add Submission to upload a file or write your answer.</div>\n          </div>`;\n      return `<h2 style=\"margin-top:0;\">Submission History</h2>${liveHistory.revisions.map(revisionRowHTML).join('')}`;\n    }\n    function openRevisionPreview(idx) {\n      const r = liveHistory.revisions[idx];\n      if (!r) return;\n      const files = revFiles(r);\n      const text = typeof r.text === 'string' ? r.text.trim() : '';\n      const title = files.length > 1 ? `${files.length} files` : files[0] ? files[0].name : 'Written answer';\n      openModal(`\n        <h3>${escapeHtml(title)}</h3>\n        <p>${r.draft === true ? 'Saved as a draft' : 'Turned in'} ${escapeHtml(revWhen(r))}${r.late === true ? ' · Late' : ''}</p>\n        ${files.length ? `<div class=\"modal-file-list\">${files.map(f => `\n          <div class=\"material-row\">\n            ${fileIcon(f.ext, `<span class=\"material-badge\" style=\"background:${EXT_COLOR[f.ext] || '#83849a'}\">${escapeHtml((f.ext || 'file').toUpperCase().slice(0, 4))}</span>`)}\n            <span class=\"material-name\">${escapeHtml(f.name)}</span>\n            ${f.size ? `<span class=\"rev-size\">${escapeHtml(fmtSize(f.size))}</span>` : ''}\n          </div>`).join('')}</div>` : ''}\n        ${text ? `<div class=\"rev-text\">${escapeHtml(text)}</div>` : ''}\n        <div class=\"modal-actions\">\n          <button class=\"modal-btn primary\" type=\"button\" id=\"modalCloseBtn\">Close</button>\n        </div>`);\n      document.getElementById('modalCloseBtn').addEventListener('click', closeModal);\n      document.getElementById('modalCloseBtn').focus();\n    }\n    async function loadLiveHistory() {\n      const seq = ++liveHistory.seq;\n      let S;\n      try {\n        S = await loadSubmitScript();\n      } catch {\n        if (seq === liveHistory.seq && liveHistory.state === 'loading') { liveHistory.state = 'error'; renderSubmissionsPanel(); }\n        return;\n      }\n      try {\n        const revs = await S.history({ section: String(item.courseId), assignment: String(item.id) });\n        if (seq !== liveHistory.seq) return;\n        const p = liveHistory.pending;\n        if (p && !revs.some(r => String(r.id) === String(p.id))) revs.unshift(p);\n        else liveHistory.pending = null;\n        liveHistory.revisions = revs;\n        liveHistory.state = 'ready';\n        if (revs.some(r => r.draft !== true) && (currentStatus === 'overdue' || currentStatus === 'upcoming')) currentStatus = 'submitted';\n      } catch (e) {\n        if (seq !== liveHistory.seq) return;\n        if (e && e.code === 'signed_out') { window.location.href = '/'; return; }\n        if (liveHistory.state === 'loading') liveHistory.state = 'error';\n      }\n      renderSubmissionsPanel();\n    }\n    /** After a turn-in: show it at once, mark the work submitted (as the preview's mock does), then reload the real list. */\n    function afterTurnIn(revision) {\n      // Files' Turned In list (2026-10-09) asks Schoology again next time.\n      try { sessionStorage.removeItem('averages_subs_cache'); } catch {}\n      if (revision && typeof revision === 'object' && revision.id != null && String(revision.id)) {\n        liveHistory.pending = revision;\n        liveHistory.revisions = [revision].concat(liveHistory.revisions.filter(r => String(r.id) !== String(revision.id)));\n        liveHistory.state = 'ready';\n      }\n      currentStatus = 'submitted';\n      renderSubmissionsPanel();\n      pulse(submissionBodyEl.querySelector('[data-rev-index=\"0\"]'));\n      loadLiveHistory();\n    }\n\n    // ------------------------------------------------------------------\n    // Turning in, signed in with Schoology (2026-10-06): shared by Add\n    // Submission and Submit on a draft.\n    // ------------------------------------------------------------------\n    function submitMessage(err) {\n      const S = window.AveragesSubmit, C = window.AveragesCloud;\n      if (S) return S.messageFor(err);\n      if (C) return C.messageFor(err);\n      return 'Something went wrong. Try again in a moment.';\n    }\n    function submitErrorHTML(err, short) {\n      const code = err && err.code ? err.code : '';\n      // `short`: the failing file's row already says why.\n      let html = short ? 'Nothing was turned in.' : escapeHtml(submitMessage(err));\n      if (code === 'canva_reconnect_needed') html += ' <a href=\"/settings?section=integrations\">Reconnect Canva</a>';\n      if (code === 'canva_not_connected') html += ' <a href=\"/settings?section=integrations\">Connect Canva</a>';\n      if (code === 'signed_out') html += ' <a href=\"/\">Sign in</a>';\n      return html;\n    }\n    /** Tokens to download picked files. Not async: a sign-in window may open, so call inside the click, before any await. */\n    function driveReadToken(C) {\n      if (!C || typeof C.googleSession !== 'function') return Promise.reject({ code: 'not_configured' });\n      if (!C.googleReady()) { C.prepareGoogle().catch(() => {}); return Promise.reject({ code: 'not_ready' }); }\n      return C.googleSession({ interactive: true });\n    }\n    function oneDriveReadToken(C) {\n      if (!C || typeof C.oneDriveToken !== 'function') return Promise.reject({ code: 'not_configured' });\n      return C.oneDriveToken({ interactive: true, read: true });\n    }\n    const driveDownloadReady = () => !!(window.AveragesCloud && cloudCfg && cloudCfg.google && typeof window.AveragesCloud.googleDownload === 'function');\n    const CHECK_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg>';\n    /** The \"Turned in\" state, in whichever popup did the turning in. */\n    function showTurnedIn(names, sentence) {\n      activeSubmitAbort = null;\n      modalBox.removeAttribute('aria-busy');\n      const list = names.filter(Boolean);\n      const what = sentence || `${list.length === 1 ? `\"${escapeHtml(list[0])}\" is` : `${list.length} files are`} turned in on Schoology.`;\n      modalBox.innerHTML = `\n        <div class=\"submit-done-head\"><span class=\"submit-done-check\" aria-hidden=\"true\">${CHECK_ICON}</span><h3>Turned in</h3></div>\n        <p>${what} You’ll find it in Submission History.</p>\n        ${list.length > 1 ? `<div class=\"modal-file-list\">${list.map(n => {\n          const ext = ((String(n).match(/\\.([a-z0-9]{1,5})$/i) || [])[1] || '').toLowerCase();\n          return `<div class=\"material-row\">${fileIcon(ext, `<span class=\"material-badge\" style=\"background:${EXT_COLOR[ext] || '#83849a'}\">${escapeHtml((ext || 'file').toUpperCase().slice(0, 4))}</span>`)}<span class=\"material-name\">${escapeHtml(n)}</span></div>`;\n        }).join('')}</div>` : ''}\n        <div class=\"modal-actions\">\n          <button class=\"modal-btn primary\" type=\"button\" id=\"modalDoneBtn\">Done</button>\n        </div>`;\n      modalBox.setAttribute('role', 'dialog');\n      const done = document.getElementById('modalDoneBtn');\n      done.addEventListener('click', closeModal);\n      done.focus();\n    }\n\n\n    function renderSubmissionsPanel() {\n      const banner = BANNER_COPY[currentStatus]();\n      document.getElementById('submissionBanner').innerHTML = `\n        <div class=\"submission-banner ${escapeHtml(currentStatus)}\">\n          <span class=\"dot\"></span>\n          <div class=\"submission-banner-text\">\n            <p class=\"submission-banner-label\">${banner.label}</p>\n            ${banner.meta ? `<p class=\"submission-banner-meta\">${escapeHtml(banner.meta)}</p>` : ''}\n          </div>\n        </div>`;\n\n      const bodyEl = document.getElementById('submissionBody');\n      let html = '';\n      if (CLASSROOM) {\n        const done = currentStatus === 'submitted' || currentStatus === 'graded' || currentStatus === 'returned';\n        const href = classroomLink || (CLASSROOM_URL(course.link) ? course.link : 'https://classroom.google.com/');\n        bodyEl.innerHTML = `\n          <div class=\"submit-dropzone quiz-redirect-notice classroom-turnin\">\n            ${EXTERNAL_LINK_ICON}\n            <div>${done ? 'This was turned in on Google Classroom. Open it there to see your work and any comments.' : 'Turn this in on Google Classroom. Your status and grade show up here once it’s in.'}</div>\n            <a class=\"quiz-redirect-btn\" href=\"${escapeHtml(href)}\" target=\"_blank\" rel=\"noopener noreferrer\">\n              ${done ? 'Open in Google Classroom' : 'Turn in on Google Classroom'}\n              ${EXTERNAL_LINK_ICON}\n            </a>\n          </div>`;\n        return;\n      }\n      // Quizzes/tests are actually taken in Schoology itself, not in\n      // Averages.io — there's no real \"upload a file\" or \"type an answer\"\n      // step for them here, unlike a normal assignment or discussion post\n      // (2026-09-03, per Martin: \"for quizes i don't think they can take\n      // it in our app, they have to use schoology\"). So instead of the\n      // upload dropzone / submission history / Add Submission button\n      // below, a quiz-type item gets one static redirect notice no matter\n      // its status — the status banner above still reflects the real\n      // Missing/Submitted/Graded/Returned state, since Averages.io does\n      // still mirror that from Schoology once it happens.\n      if (item.type === 'assessment') {\n        html += `\n          <div class=\"submit-dropzone quiz-redirect-notice\">\n            ${EXTERNAL_LINK_ICON}\n            <div>Quizzes and tests are taken in Schoology, not in Averages. Head to Schoology to complete this one — your grade will show up here once it's in.</div>\n            <a class=\"quiz-redirect-btn\" href=\"https://www.schoology.com/\" target=\"_blank\" rel=\"noopener noreferrer\">\n              Open in Schoology\n              ${EXTERNAL_LINK_ICON}\n            </a>\n          </div>`;\n        // Feedback/a comment is still real Schoology grading data, not a\n        // \"submission\" — Averages.io already mirrors the score in the banner\n        // above, so it shows this the same way rather than hiding it just\n        // because the file-submission UI above it went away.\n        if (currentStatus === 'graded' && detail.feedback) {\n          html += `\n            <div class=\"feedback-box\">\n              <span class=\"feedback-box-label\" style=\"color:var(--grade-good);\">Teacher Feedback</span>\n              <p>\"${escapeHtml(detail.feedback)}\"</p>\n              <span class=\"attrib\">— ${escapeHtml(course.teacher)}</span>\n            </div>`;\n        } else if (currentStatus === 'returned' && detail.comment) {\n          html += `\n            <div class=\"feedback-box returned\">\n              <span class=\"feedback-box-label\">Teacher Comment · Revision requested</span>\n              <p>\"${escapeHtml(detail.comment)}\"</p>\n              <span class=\"attrib\">— ${escapeHtml(course.teacher)}</span>\n            </div>`;\n        }\n        bodyEl.innerHTML = html;\n        return;\n      }\n      if (SUBMIT_LIVE) {\n        html += liveHistoryHTML();\n      } else if (currentStatus === 'overdue' || currentStatus === 'upcoming') {\n        html += `\n          <div class=\"submit-dropzone\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 16V4M12 4l-5 5M12 4l5 5\"/><path d=\"M4 16v3a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-3\"/></svg>\n            <div>Submitting assignments isn't available in this preview yet.</div>\n          </div>`;\n      } else {\n        // Teacher Feedback / Teacher Comment used to render here as one\n        // static block for the whole assignment — moved into each\n        // submission row's own click-to-preview popup instead\n        // (2026-08-31, per Martin's request to make submissions\n        // clickable), since feedback is really about one specific\n        // turn-in, not the assignment in the abstract. See\n        // openSubmissionPreview() above.\n        html += `<h2 style=\"margin-top:0;\">Submission History</h2>${submissionHistoryHTML()}`;\n      }\n      // You can submit an assignment more than once — this button stays\n      // available regardless of status (2026-08-29, per Martin's\n      // request), including after it's already been graded, since a\n      // resubmission is exactly how a real regrade request would start.\n      html += `\n        <button class=\"add-submission-btn\" type=\"button\" id=\"addSubmissionBtn\">\n          ${PLUS_ICON}\n          Add Submission\n        </button>`;\n      bodyEl.innerHTML = html;\n      document.getElementById('addSubmissionBtn').addEventListener('click', () => openAddSubmissionModal());\n    }\n\n    // Add Submission — Upload / Create, mirroring the real Schoology upload\n    // dialog (screenshot Martin shared 2026-08-29): Upload loads a file from\n    // this device, Create answers directly in the app with no file. Both are\n    // real, switchable tabs sharing one optional comment box underneath.\n    // (A third Resources tab, picking a file from Google Drive, was removed\n    // 2026-09-02 per Martin's request — Google Drive integrations are coming\n    // back in a later update, not this release.)\n    const UPLOAD_TAB_PANEL = {\n      // Custom-styled \"Choose Files\" button + a list of what's been picked\n      // so far, in place of the bare native file input (2026-08-29, per\n      // Martin's request — the browser-default control looked out of\n      // place next to everything else in this modal). The real\n      // <input type=\"file\"> is still there, just visually hidden and\n      // triggered by the button. `multiple` + the picked-files list below\n      // (2026-09-04, per Martin: \"let people upload multiple files\") — see\n      // bindUploadTab's pickedFiles handling for why the list is tracked\n      // in JS rather than read straight off the input at submit time.\n      upload: () => `\n        <p class=\"upload-tab-desc\">Upload one or more files from this device.</p>\n        <div class=\"upload-picker\" id=\"uploadPicker\">\n          <button class=\"upload-picker-btn\" type=\"button\" id=\"chooseFileBtn\">Choose Files</button>\n          <span class=\"upload-picker-filename empty\" id=\"chooseFileName\">No files chosen</span>\n        </div>\n        <div class=\"upload-picked-list\" id=\"uploadPickedList\"></div>\n        <!-- Hidden until a Submit attempt with no file chosen (2026-09-04,\n             per Martin -- at least one file is now required on this tab;\n             see modalSubmitBtn's click handler). -->\n        <p class=\"upload-required-note\" id=\"uploadRequiredNote\" hidden>Choose at least one file before submitting.</p>\n        ${uploadSourcesHTML()}\n        <input type=\"file\" id=\"submissionFileInput\" multiple style=\"display:none;\">`,\n      // Rich-text answer area (2026-08-30, per Martin's request — a plain\n      // textbox with Google-Docs-style formatting options) in place of the\n      // old bare <textarea>. See bindCreateTab() below for the toolbar\n      // wiring (document.execCommand-based, front-end only).\n      create: () => `\n        <p class=\"upload-tab-desc\">Answer directly — no file needed.</p>\n        <div class=\"rte-toolbar\" role=\"toolbar\" aria-label=\"Text formatting\">\n          <select class=\"rte-select\" id=\"rteBlockSelect\" aria-label=\"Text style\">\n            <option value=\"p\">Normal text</option>\n            <option value=\"h1\">Heading 1</option>\n            <option value=\"h2\">Heading 2</option>\n            <option value=\"h3\">Heading 3</option>\n          </select>\n          <span class=\"rte-divider\" aria-hidden=\"true\"></span>\n          <button class=\"rte-btn\" type=\"button\" data-cmd=\"bold\" aria-label=\"Bold\" title=\"Bold\"><b>B</b></button>\n          <button class=\"rte-btn\" type=\"button\" data-cmd=\"italic\" aria-label=\"Italic\" title=\"Italic\"><i>I</i></button>\n          <button class=\"rte-btn\" type=\"button\" data-cmd=\"underline\" aria-label=\"Underline\" title=\"Underline\"><u>U</u></button>\n          <span class=\"rte-divider\" aria-hidden=\"true\"></span>\n          <button class=\"rte-btn\" type=\"button\" data-cmd=\"insertUnorderedList\" aria-label=\"Bulleted list\" title=\"Bulleted list\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><line x1=\"4\" y1=\"6\" x2=\"4.01\" y2=\"6\"/><line x1=\"4\" y1=\"12\" x2=\"4.01\" y2=\"12\"/><line x1=\"4\" y1=\"18\" x2=\"4.01\" y2=\"18\"/><path d=\"M9 6h11M9 12h11M9 18h11\"/></svg>\n          </button>\n          <button class=\"rte-btn\" type=\"button\" data-cmd=\"insertOrderedList\" aria-label=\"Numbered list\" title=\"Numbered list\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 6h11M9 12h11M9 18h11\"/><text x=\"1\" y=\"8\" font-size=\"7\">1</text><text x=\"1\" y=\"14\" font-size=\"7\">2</text><text x=\"1\" y=\"20\" font-size=\"7\">3</text></svg>\n          </button>\n          <span class=\"rte-divider\" aria-hidden=\"true\"></span>\n          <button class=\"rte-btn\" type=\"button\" data-cmd=\"createLink\" aria-label=\"Insert link\" title=\"Insert link\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 15l6-6\"/><path d=\"M10 6l1-1a4 4 0 0 1 6 6l-1 1\"/><path d=\"M14 18l-1 1a4 4 0 0 1-6-6l1-1\"/></svg>\n          </button>\n        </div>\n        <div class=\"modal-textarea answer-textarea rte-editor\" id=\"submissionAnswerText\" contenteditable=\"true\" role=\"textbox\" aria-multiline=\"true\" aria-label=\"Answer\" data-placeholder=\"Type your answer here…\"></div>`,\n    };\n\n    // \"Or add from\" (2026-10-06): the preview keeps its Coming soon row.\n    // Signed in with Schoology, each app works once it's set up: Canva when\n    // it's connected (else a Connect hint), Google Drive and OneDrive when\n    // their app ids are set and averages-cloud.js has the download helpers.\n    const SOURCE_NAME = { canva: 'Canva', gdrive: 'Google Drive', onedrive: 'OneDrive' };\n    const PICK_SOURCE = { course: 'Course file', gdrive: 'Google Drive', onedrive: 'OneDrive', canva: 'Canva, turned in as a PDF' };\n    const PICK_ID_OK = {\n      course: id => /^\\d{1,20}$/.test(id),\n      gdrive: id => /^[A-Za-z0-9_-]{1,200}$/.test(id),\n      onedrive: id => /^[A-Za-z0-9!._-]{1,200}$/.test(id),\n      canva: id => /^[A-Za-z0-9_-]{1,64}$/.test(id),\n    };\n    function sourceState(app) {\n      if (INCOGNITO) return 'off';\n      if (app === 'canva') return !canvaInfo || !canvaInfo.configured ? 'soon' : canvaInfo.connected ? 'ready' : 'connect';\n      const C = window.AveragesCloud;\n      if (!C || !cloudCfg) return 'soon';\n      if (app === 'gdrive') return cloudCfg.google && typeof C.googleDownload === 'function' ? 'ready' : 'soon';\n      return cloudCfg.microsoft && typeof C.oneDrivePick === 'function' && typeof C.oneDriveDownload === 'function' ? 'ready' : 'soon';\n    }\n    function uploadSourcesRowHTML() {\n      const off = ['canva', 'gdrive', 'onedrive'].filter(a => ['soon', 'off'].includes(sourceState(a)));\n      const btn = (app, inner) => `<button class=\"upload-source\" type=\"button\" data-source=\"${app}\"${off.includes(app) ? ' disabled' : ''}>${inner}</button>`;\n      const soon = INCOGNITO ? 'Off in Incognito' : off.length === 3 ? 'Coming soon' : off.length ? `${off.map(a => SOURCE_NAME[a]).join(' and ')} coming soon` : '';\n      return `<div class=\"upload-sources\" id=\"uploadSources\" role=\"group\" aria-label=\"Add from another app\">\n          <span class=\"upload-sources-label\">Or add from</span>\n          ${btn('canva', '<span class=\"canva-mark\" aria-hidden=\"true\"></span>Canva')}\n          ${btn('gdrive', 'Google Drive')}\n          ${btn('onedrive', 'OneDrive')}\n          ${soon ? `<span class=\"soon\">${soon}</span>` : ''}\n        </div>`;\n    }\n    function uploadSourcesHTML() {\n      if (!SUBMIT_LIVE) return `\n        <div class=\"upload-sources\" role=\"group\" aria-label=\"Add from another app (coming soon)\">\n          <span class=\"upload-sources-label\">Or add from</span>\n          <button class=\"upload-source\" type=\"button\" disabled><span class=\"canva-mark\" aria-hidden=\"true\"></span>Canva</button>\n          <button class=\"upload-source\" type=\"button\" disabled>Google Drive</button>\n          <button class=\"upload-source\" type=\"button\" disabled>OneDrive</button>\n          <span class=\"soon\">Coming soon</span>\n        </div>`;\n      return `\n        ${uploadSourcesRowHTML()}\n        <p class=\"upload-source-note\" id=\"uploadSourceNote\" role=\"status\" hidden></p>\n        <div class=\"canva-pick\" id=\"canvaPick\" hidden></div>`;\n    }\n    /** Redraws the row in an open Add Submission when Canva / the cloud setup becomes known. */\n    function refreshUploadSources() {\n      const row = document.getElementById('uploadSources');\n      if (!row || !SUBMIT_LIVE || modalBox.getAttribute('aria-busy') === 'true') return;\n      const tmp = document.createElement('div');\n      tmp.innerHTML = uploadSourcesRowHTML();\n      row.replaceWith(tmp.firstElementChild);\n    }\n    /** A file from the Files page (?attach=), as an Add Submission pick. */\n    function pickFromAttach(a) {\n      if (a.src === 'course') return { src: 'course', id: a.id, name: a.name, kind: a.kind, parent: a.parent, course: a.course };\n      if (a.src === 'canva') {\n        const title = a.name.replace(/\\.pdf$/i, '') || 'Canva design';\n        return { src: 'canva', id: a.id, designId: a.id, title, name: title + '.pdf' };\n      }\n      return { src: a.src, id: a.id, name: a.name };\n    }\n    function pickExt(f) {\n      const ext = ((String(f.name || '').match(/\\.([a-z0-9]{1,5})$/i) || [])[1] || '').toLowerCase();\n      if (f.src === 'canva') return 'pdf';\n      return ext || (f.src === 'gdrive' ? 'pdf' : '');\n    }\n\n    function openAddSubmissionModal(opts) {\n      opts = opts || {};\n      let activeTab = 'upload';\n      // Every file picked on the Upload tab so far this modal session\n      // (2026-09-04, per Martin's multi-file request) -- lives here, not\n      // just on the <input>, because re-opening the OS file dialog\n      // REPLACES input.files with just that dialog's selection rather\n      // than adding to it; this array is what actually accumulates\n      // across multiple picks (see bindUploadTab's `change` handler).\n      // Also survives switching to the Create tab and back, since it's\n      // closed over here rather than living in the (regenerated) DOM.\n      let pickedFiles = [];\n      // Each pick is { name, src }: 'device' with its File, or, signed in\n      // (2026-10-06), 'course' | 'gdrive' | 'onedrive' | 'canva' with an id,\n      // fetched as a Blob only once Submit is clicked.\n      (opts.files || []).forEach(f => pickedFiles.push({ name: f.name, src: 'device', file: f, size: f.size }));\n      if (opts.attach) pickedFiles.push(pickFromAttach(opts.attach));\n      let renderPicked = () => {};\n      let running = false;\n\n      openModal(`\n        <h3>Add Submission</h3>\n        <div class=\"upload-tabs\" role=\"tablist\">\n          <button class=\"upload-tab active\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-tab=\"upload\">Upload</button>\n          <button class=\"upload-tab\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-tab=\"create\">Create</button>\n        </div>\n        <div class=\"upload-tab-panel\" id=\"uploadTabPanel\">${UPLOAD_TAB_PANEL.upload()}</div>\n        ${SUBMIT_LIVE\n          // Signed in: Schoology's turn-in has no comment field, so there's no box that would go nowhere.\n          ? '<p class=\"submit-error\" id=\"submitError\" role=\"alert\" hidden></p>'\n          : `<label class=\"modal-field-label\" for=\"submissionComment\">Add a comment (optional)</label>\n        <textarea class=\"modal-textarea\" id=\"submissionComment\" placeholder=\"Add a comment (optional)\"></textarea>`}\n        <div class=\"modal-actions\">\n          <button class=\"modal-btn secondary\" type=\"button\" id=\"modalCancelBtn\">Cancel</button>\n          <button class=\"modal-btn primary\" type=\"button\" id=\"modalSubmitBtn\">Submit</button>\n        </div>`);\n      // Wider than the default .modal-box (2026-09-04, per Martin: \"make\n      // the assignment submission popup bigger\") -- see the modal-box-lg\n      // rule and closeModal(), which strips this back off so a later,\n      // smaller popup (file info, submission preview) isn't left oversized.\n      modalBox.classList.add('modal-box-lg');\n\n      const panelEl = document.getElementById('uploadTabPanel');\n      const commentEl = document.getElementById('submissionComment');\n\n      function bindUploadTab() {\n        if (activeTab !== 'upload') return;\n        const chooseBtn = document.getElementById('chooseFileBtn');\n        const fileInput = document.getElementById('submissionFileInput');\n        const nameEl = document.getElementById('chooseFileName');\n        const pickerEl = document.getElementById('uploadPicker');\n        const noteEl = document.getElementById('uploadRequiredNote');\n        const listEl = document.getElementById('uploadPickedList');\n\n        function renderPickedList() {\n          if (!pickedFiles.length) {\n            listEl.innerHTML = '';\n            nameEl.textContent = 'No files chosen';\n            nameEl.classList.add('empty');\n            return;\n          }\n          nameEl.textContent = pickedFiles.length === 1 ? pickedFiles[0].name : `${pickedFiles.length} files chosen`;\n          nameEl.classList.remove('empty');\n          listEl.innerHTML = pickedFiles.map((f, i) => {\n            const ext = SUBMIT_LIVE ? pickExt(f) : (f.name.split('.').pop() || '').toLowerCase();\n            const color = EXT_COLOR[ext] || '#83849a';\n            const name = `<span class=\"upload-picked-name\">${escapeHtml(f.name)}</span>`;\n            // Signed in: where it's from (cloud files), and a line for its progress.\n            const tooBig = SUBMIT_LIVE && f.size > SUBMIT_MAX_BYTES;\n            const live = SUBMIT_LIVE ? `<span class=\"upload-picked-text\">${name}${PICK_SOURCE[f.src] ? `<span class=\"upload-picked-src\">${PICK_SOURCE[f.src]}</span>` : ''}<span class=\"upload-picked-progress\"${tooBig ? '' : ' hidden'}><span class=\"upload-progress-text\">${tooBig ? 'Too big to turn in (95 MB max)' : ''}</span><span class=\"upload-bar\" aria-hidden=\"true\"><i></i></span></span></span>` : '';\n            return `\n              <div class=\"upload-picked-row${tooBig ? ' failed' : ''}\" data-pick=\"${i}\">\n                ${fileIcon(f.src === 'canva' ? 'canva' : ext, `<span class=\"material-badge\" style=\"background:${escapeHtml(color)}\">${escapeHtml(SUBMIT_LIVE ? (ext || '?').toUpperCase().slice(0, 4) : (ext || '?').toUpperCase())}</span>`)}\n                ${SUBMIT_LIVE ? live : name}\n                <button class=\"material-icon-btn\" type=\"button\" data-index=\"${i}\" aria-label=\"Remove ${escapeHtml(f.name)}\">${REMOVE_ICON}</button>\n              </div>`;\n          }).join('');\n        }\n        renderPicked = renderPickedList;\n        renderPickedList(); // re-bound after a Create->Upload tab switch, with files already picked this session\n\n        chooseBtn.addEventListener('click', () => fileInput.click());\n        fileInput.addEventListener('change', () => {\n          const newFiles = Array.from(fileInput.files);\n          fileInput.value = ''; // so picking the same file(s) again still fires \"change\"\n          if (!newFiles.length) return;\n          pickedFiles.push(...newFiles.map(f => ({ name: f.name, src: 'device', file: f, size: f.size })));\n          renderPickedList();\n          // Picking file(s) clears a validation error from a previous\n          // failed Submit attempt (see modalSubmitBtn's click handler).\n          pickerEl.classList.remove('error');\n          noteEl.hidden = true;\n        });\n        // Delegated (not per-row) since the list is rebuilt on every add/remove.\n        listEl.addEventListener('click', e => {\n          const btn = e.target.closest('.material-icon-btn[data-index]');\n          if (!btn || running) return;\n          pickedFiles.splice(Number(btn.dataset.index), 1);\n          renderPickedList();\n        });\n      }\n\n      // Wires up the Create tab's rich-text toolbar (2026-08-30). Kept\n      // deliberately simple — document.execCommand is deprecated but still\n      // broadly supported, and this is a front-end mockup with no real\n      // save-as-HTML step, so a heavier editor library isn't warranted.\n      function bindCreateTab() {\n        if (activeTab !== 'create') return;\n        const editor = document.getElementById('submissionAnswerText');\n        const blockSelect = document.getElementById('rteBlockSelect');\n        const toolbar = editor.previousElementSibling;\n        const cmdBtns = toolbar.querySelectorAll('.rte-btn[data-cmd]');\n        function updateToolbarState() {\n          cmdBtns.forEach(btn => {\n            let active = false;\n            try { active = document.queryCommandState(btn.dataset.cmd); } catch (e) {}\n            btn.classList.toggle('active', active);\n          });\n          try {\n            const block = (document.queryCommandValue('formatBlock') || '').toLowerCase();\n            blockSelect.value = ['h1', 'h2', 'h3'].includes(block) ? block : 'p';\n          } catch (e) {}\n        }\n        cmdBtns.forEach(btn => {\n          btn.addEventListener('click', () => {\n            editor.focus();\n            const cmd = btn.dataset.cmd;\n            if (cmd === 'createLink') {\n              const url = window.prompt('Link URL:', 'https://');\n              if (url) document.execCommand('createLink', false, url);\n            } else {\n              document.execCommand(cmd, false, null);\n            }\n            updateToolbarState();\n          });\n        });\n        blockSelect.addEventListener('change', () => {\n          editor.focus();\n          document.execCommand('formatBlock', false, blockSelect.value);\n          updateToolbarState();\n        });\n        editor.addEventListener('keyup', updateToolbarState);\n        editor.addEventListener('mouseup', updateToolbarState);\n        editor.addEventListener('focus', updateToolbarState);\n      }\n\n      function bindActiveTab() {\n        bindUploadTab();\n        bindCreateTab();\n      }\n      bindActiveTab();\n\n      // ---------- Signed in with Schoology (2026-10-06) ----------\n      const sec = String(item.courseId), asg = String(item.id);\n      function sourceNote(html) {\n        const note = document.getElementById('uploadSourceNote');\n        if (note) { note.innerHTML = html; note.hidden = !html; }\n      }\n      function clearRequired() {\n        const picker = document.getElementById('uploadPicker'), req = document.getElementById('uploadRequiredNote');\n        if (picker) picker.classList.remove('error');\n        if (req) req.hidden = true;\n      }\n      /** Adds a pick unless that same file is already in the list. */\n      function addPick(f) {\n        if (f.src !== 'device' && pickedFiles.some(x => x.src === f.src && x.id === f.id)) return false;\n        pickedFiles.push(f);\n        renderPicked();\n        clearRequired();\n        return true;\n      }\n      // Add from Canva: this assignment's Canva drafts, then the student's designs (GET /canva/designs, as on Files).\n      let canvaPickItems = [], canvaPickNext = null;\n      const httpsUrl = u => /^https:\\/\\//i.test(String(u || ''));\n      const canvaPickHead = `<div class=\"canva-pick-head\"><span>Pick a design. It’s turned in as a PDF.</span><button class=\"material-icon-btn\" type=\"button\" data-canva-close aria-label=\"Close Canva designs\">${REMOVE_ICON}</button></div>`;\n      function renderCanvaPick() {\n        const box = document.getElementById('canvaPick');\n        if (!box || box.hidden) return;\n        const row = (id, title, meta, thumb) => `<button class=\"canva-pick-item\" type=\"button\" data-pick-design=\"${escapeHtml(id)}\" data-pick-title=\"${escapeHtml(title)}\">`\n          + `<span class=\"canva-pick-thumb\">${httpsUrl(thumb) ? `<img src=\"${escapeHtml(thumb)}\" alt=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer\">` : '<span class=\"canva-mark\" aria-hidden=\"true\"></span>'}</span>`\n          + `<span class=\"canva-pick-name\">${escapeHtml(title)}</span><span class=\"canva-pick-meta\">${escapeHtml(meta)}</span></button>`;\n        const draftIds = new Set(canvaDrafts.map(d => d.designId));\n        const drafts = canvaDrafts.map(d => row(d.designId, d.name, `Edited ${d.edited}`, ''));\n        const designs = canvaPickItems.filter(d => !draftIds.has(String(d.id))).map(d => row(String(d.id), String(d.title || 'Untitled design'), d.updatedAt ? editedLabel(d.updatedAt) : '', d.thumbnailUrl));\n        box.innerHTML = canvaPickHead + `<div class=\"canva-pick-list\">`\n          + (drafts.length ? '<div class=\"canva-pick-label\">Drafts for this assignment</div>' + drafts.join('') : '')\n          + (designs.length ? '<div class=\"canva-pick-label\">Your designs</div>' + designs.join('') : '')\n          + (!drafts.length && !designs.length ? '<p class=\"canva-pick-empty\">No Canva designs yet.</p>' : '')\n          + (canvaPickNext ? '<button class=\"assign-retry\" type=\"button\" data-canva-more>Show more</button>' : '')\n          + '</div>';\n      }\n      async function loadCanvaPick(more) {\n        const box = document.getElementById('canvaPick');\n        if (!box) return;\n        box.hidden = false;\n        if (!more) {\n          canvaPickItems = []; canvaPickNext = null;\n          box.innerHTML = canvaPickHead + '<p class=\"canva-pick-empty\">Loading your Canva designs…</p>';\n        }\n        try {\n          const res = await fetch(`${averagesApiBase()}/canva/designs${more && canvaPickNext ? '?continuation=' + encodeURIComponent(canvaPickNext) : ''}`, { credentials: 'include' });\n          const j = await res.json().catch(() => ({}));\n          if (j.connected === false || j.error === 'canva_not_connected' || j.error === 'canva_reconnect_needed') {\n            box.innerHTML = canvaPickHead + '<p class=\"canva-pick-empty\">Connect Canva first in <a href=\"/settings?section=integrations\">Settings</a>, then add your designs here.</p>';\n            return;\n          }\n          if (!res.ok) throw new Error('status ' + res.status);\n          canvaPickItems = canvaPickItems.concat((Array.isArray(j.items) ? j.items : []).filter(d => d && PICK_ID_OK.canva(String(d.id || ''))));\n          canvaPickNext = typeof j.continuation === 'string' && j.continuation ? j.continuation : null;\n          renderCanvaPick();\n        } catch {\n          if (canvaPickItems.length || canvaDrafts.length) { renderCanvaPick(); return; }\n          box.innerHTML = canvaPickHead + '<p class=\"canva-pick-empty\">Couldn’t load your Canva designs.<button class=\"assign-retry\" type=\"button\" data-canva-retry>Try again</button></p>';\n        }\n      }\n      // Google Drive / OneDrive: the sign-in window (if any) opens inside the click, before anything is awaited.\n      function addFromCloud(app, btn) {\n        const C = window.AveragesCloud;\n        if (!C) return;\n        // Google Drive (2026-10-09): no picker. Google Drive opens, the student chooses\n        // Open with → Averages.io on their file, and attaches it to this assignment from Files.\n        if (app === 'gdrive') {\n          // Not connected (or Google disconnected it): connect first, here,\n          // and come back to this assignment. Opening Drive first sent them\n          // to Files with nothing able to open the file (2026-10-09).\n          const lost = typeof C.lost === 'function' ? C.lost('gdrive') : null;\n          if (lost || !C.accounts().gdrive) {\n            sourceNote(`${lost ? 'Google Drive got disconnected.' : 'Connect Google Drive first.'} Then open Google Drive, right-click your file and choose <strong>Open with → Averages.io</strong>. <button class=\"upload-note-btn\" type=\"button\" data-drive-connect>${lost ? 'Reconnect' : 'Connect'} Google Drive</button>`);\n            return;\n          }\n          window.open(C.driveHome || 'https://drive.google.com/', '_blank', 'noopener,noreferrer');\n          sourceNote('Google Drive opened in a new tab. Right-click your file, choose <strong>Open with → Averages.io</strong>, then <strong>Attach to an assignment</strong> and pick this one.');\n          return;\n        }\n        const pending = oneDriveReadToken(C).then(t => C.oneDrivePick(t)).then(items => (items || []).map(f => ({ id: String(f.id || ''), name: String(f.name || 'OneDrive file'), mimeType: String(f.mimeType || ''), size: Number(f.size) || 0 })));\n        btn.setAttribute('aria-busy', 'true');\n        pending\n          .then(list => {\n            list.forEach(f => {\n              if (!PICK_ID_OK[app](f.id)) return;\n              // Google Docs, Sheets and Slides come down as PDFs.\n              const google = app === 'gdrive' && /^application\\/vnd\\.google-apps\\./.test(f.mimeType) && !/\\.pdf$/i.test(f.name);\n              addPick({ src: app, id: f.id, name: (google ? f.name + '.pdf' : f.name).slice(0, 200), mimeType: f.mimeType, size: f.size });\n            });\n          })\n          .catch(err => { if (!err || err.code !== 'popup_closed') sourceNote(escapeHtml(submitMessage(err))); })\n          .then(() => btn.removeAttribute('aria-busy'));\n      }\n      panelEl.addEventListener('click', e => {\n        if (!SUBMIT_LIVE || running) return;\n        const src = e.target.closest('[data-source]');\n        if (src && !src.disabled) {\n          if (src.getAttribute('aria-busy') === 'true') return;\n          sourceNote('');\n          if (src.dataset.source !== 'canva') { addFromCloud(src.dataset.source, src); return; }\n          if (sourceState('canva') === 'connect') { sourceNote('Connect Canva first in <a href=\"/settings?section=integrations\">Settings</a>, then add your designs here.'); return; }\n          const box = document.getElementById('canvaPick');\n          if (box && !box.hidden) box.hidden = true; else loadCanvaPick(false);\n          return;\n        }\n        if (e.target.closest('[data-drive-connect]')) {\n          const C = window.AveragesCloud;\n          if (C && typeof C.connectGoogle === 'function') C.connectGoogle().catch(err => { if (!err || err.code !== 'popup_closed') sourceNote(escapeHtml(submitMessage(err))); });\n          return;\n        }\n        if (e.target.closest('[data-canva-close]')) { document.getElementById('canvaPick').hidden = true; return; }\n        if (e.target.closest('[data-canva-more]')) { loadCanvaPick(true); return; }\n        if (e.target.closest('[data-canva-retry]')) { loadCanvaPick(false); return; }\n        const d = e.target.closest('[data-pick-design]');\n        if (d) {\n          const title = (d.dataset.pickTitle || 'Canva design').replace(/\\.pdf$/i, '').slice(0, 190) || 'Canva design';\n          addPick({ src: 'canva', id: d.dataset.pickDesign, designId: d.dataset.pickDesign, title, name: title + '.pdf' });\n          document.getElementById('canvaPick').hidden = true;\n        }\n      });\n\n      function setPickProgress(i, text, fraction, state) {\n        const row = modalBox.querySelector(`.upload-picked-row[data-pick=\"${i}\"]`);\n        const line = row && row.querySelector('.upload-picked-progress');\n        if (!line) return;\n        line.hidden = false;\n        line.querySelector('.upload-progress-text').textContent = text;\n        const bar = line.querySelector('.upload-bar');\n        bar.hidden = fraction == null;\n        if (fraction != null) bar.firstElementChild.style.width = Math.round(Math.max(0, Math.min(1, fraction)) * 100) + '%';\n        row.classList.toggle('done', state === 'done');\n        row.classList.toggle('failed', state === 'failed');\n      }\n      function setRunning(on) {\n        running = on;\n        if (on) modalBox.setAttribute('aria-busy', 'true'); else modalBox.removeAttribute('aria-busy');\n        modalBox.querySelectorAll('.upload-tab, #chooseFileBtn, .upload-picked-row .material-icon-btn').forEach(b => { b.disabled = on; });\n        if (on) {\n          modalBox.querySelectorAll('.upload-source').forEach(b => { b.disabled = true; });\n          const box = document.getElementById('canvaPick');\n          if (box) box.hidden = true;\n          sourceNote('');\n        } else refreshUploadSources();\n        const editor = document.getElementById('submissionAnswerText');\n        if (editor) editor.setAttribute('contenteditable', on ? 'false' : 'true');\n        const btn = document.getElementById('modalSubmitBtn');\n        btn.disabled = on;\n        btn.textContent = on ? 'Turning in…' : 'Submit';\n      }\n      function showSubmitError(err) {\n        const onRow = !!err && typeof err.index === 'number' && err.index >= 0 && !!modalBox.querySelector(`.upload-picked-row[data-pick=\"${err.index}\"]`);\n        if (onRow) setPickProgress(err.index, submitMessage(err), null, 'failed');\n        const el = document.getElementById('submitError');\n        if (el) { el.innerHTML = submitErrorHTML(err, onRow); el.hidden = false; }\n      }\n      /** One pick as { blob, name }. Cloud and Canva files are only fetched now. */\n      async function pickBlob(S, C, f, i, tokens, signal) {\n        if (f.src === 'device') return { blob: f.file, name: f.name };\n        if (f.src === 'course') {\n          setPickProgress(i, 'Getting it from your class…', null);\n          const blob = await S.courseFile({ section: f.course, [f.kind === 'document' ? 'document' : 'assignment']: f.parent, fileId: f.id, name: f.name }, signal);\n          return { blob, name: f.name };\n        }\n        if (f.src === 'canva') {\n          setPickProgress(i, `Making a PDF of ${f.title}…`, null);\n          return S.exportCanva(f.designId, { title: f.title, signal });\n        }\n        const download = C && (f.src === 'gdrive' ? C.googleDownload : C.oneDriveDownload);\n        if (typeof download !== 'function') throw { code: 'not_configured' };\n        setPickProgress(i, `Getting it from ${SOURCE_NAME[f.src]}…`, null);\n        const r = await download.call(C, await tokens[f.src], f.id);\n        if (!r || !r.blob) throw { code: 'download_failed' };\n        return { blob: r.blob, name: String(r.name || f.name) };\n      }\n      /** Runs one turn-in: `run(S, signal)` resolves { revision }; names are what the done state lists. */\n      function go(run, names, sentence) {\n        const ctl = new AbortController();\n        activeSubmitAbort = () => ctl.abort();\n        const err = document.getElementById('submitError');\n        if (err) err.hidden = true;\n        setRunning(true);\n        loadSubmitScript()\n          .then(S => run(S, ctl.signal))\n          .then(r => {\n            if (ctl.signal.aborted) return;\n            showTurnedIn(names(), sentence);\n            afterTurnIn(r && r.revision);\n          })\n          .catch(e => {\n            // Closed mid-way (Cancel or Escape): the popup is gone; the list may have changed.\n            if (ctl.signal.aborted || (e && e.code === 'aborted')) { loadLiveHistory(); return; }\n            activeSubmitAbort = null;\n            setRunning(false);\n            if (e && e.code === 'popup_closed') { renderPicked(); return; }\n            showSubmitError(e && typeof e === 'object' ? e : { code: String(e) });\n          });\n      }\n      function liveSubmit() {\n        if (running) return;\n        if (activeTab === 'create') {\n          const editor = document.getElementById('submissionAnswerText');\n          if (!editor.textContent.trim()) { showSubmitError({ code: 'empty_text' }); editor.focus(); return; }\n          const html = editor.innerHTML;\n          go((S, signal) => S.submitText({ section: sec, assignment: asg, html, signal }), () => [], 'Your answer is turned in on Schoology.');\n          return;\n        }\n        if (!pickedFiles.length) {\n          document.getElementById('uploadPicker').classList.add('error');\n          document.getElementById('uploadRequiredNote').hidden = false;\n          document.getElementById('chooseFileBtn').focus();\n          return;\n        }\n        const C = window.AveragesCloud;\n        // Sign-in windows have to open inside this click, so tokens are asked for before anything is awaited.\n        const tokens = {};\n        if (pickedFiles.some(f => f.src === 'gdrive')) tokens.gdrive = driveReadToken(C);\n        const oneDriveFiles = pickedFiles.filter(f => f.src === 'onedrive');\n        if (oneDriveFiles.length) {\n          const needsRead = typeof C.oneDrivePicked !== 'function' || oneDriveFiles.some(f => C.oneDrivePicked(f.id));\n          tokens.onedrive = needsRead ? oneDriveReadToken(C)\n            : (typeof C.oneDriveToken === 'function' ? C.oneDriveToken({ interactive: true }) : Promise.reject({ code: 'not_configured' }));\n        }\n        Object.values(tokens).forEach(t => t.catch(() => {}));\n        const picks = pickedFiles.slice();\n        const names = picks.map(f => f.name);\n        renderPicked();\n        picks.forEach((f, i) => setPickProgress(i, 'Waiting…', null));\n        go(async (S, signal) => {\n          const files = [];\n          for (let i = 0; i < picks.length; i++) {\n            try {\n              files.push(await pickBlob(S, C, picks[i], i, tokens, signal));\n            } catch (e) {\n              throw Object.assign(e && typeof e === 'object' ? e : { code: String(e) }, { index: i });\n            }\n            if (signal.aborted) throw { code: 'aborted' };\n            names[i] = files[i].name;\n            if (picks[i].src !== 'device') setPickProgress(i, 'Waiting…', null);\n          }\n          return S.submitFiles({\n            section: sec, assignment: asg, files, signal,\n            onProgress: p => {\n              const pct = Math.round((p.fraction || 0) * 100);\n              if (p.phase === 'hashing') setPickProgress(p.index, `Getting ready ${pct}%`, p.fraction);\n              else if (p.phase === 'uploading') setPickProgress(p.index, `Uploading ${pct}%`, p.fraction);\n              else if (p.phase === 'done') setPickProgress(p.index, 'Uploaded', 1, 'done');\n            },\n          });\n        }, () => names);\n      }\n\n      modalBox.querySelectorAll('.upload-tab').forEach(tabBtn => {\n        tabBtn.addEventListener('click', () => {\n          activeTab = tabBtn.dataset.tab;\n          modalBox.querySelectorAll('.upload-tab').forEach(b => {\n            const isActive = b === tabBtn;\n            b.classList.toggle('active', isActive);\n            b.setAttribute('aria-selected', String(isActive));\n          });\n          panelEl.innerHTML = UPLOAD_TAB_PANEL[activeTab]();\n          bindActiveTab();\n        });\n      });\n\n      document.getElementById('modalCancelBtn').addEventListener('click', closeModal);\n      document.getElementById('modalSubmitBtn').addEventListener('click', () => {\n        if (SUBMIT_LIVE) { liveSubmit(); return; }\n        let files;\n        if (activeTab === 'upload') {\n          // At least one file is required on this tab (2026-09-04, per\n          // Martin) — no more falling back to a synthesized filename when\n          // nothing was chosen. Blocks the submit and surfaces the error\n          // inline instead of closing the modal.\n          if (!pickedFiles.length) {\n            document.getElementById('uploadPicker').classList.add('error');\n            document.getElementById('uploadRequiredNote').hidden = false;\n            document.getElementById('chooseFileBtn').focus();\n            return;\n          }\n          // Every file picked this session (2026-09-04, per Martin: \"let\n          // people upload multiple files\") goes into this one turn-in --\n          // see filesOf()/submissionHistoryHTML()/openSubmissionPreview\n          // for how a multi-file entry renders.\n          files = pickedFiles.map(f => ({ name: f.name, ext: (f.name.split('.').pop() || 'pdf').toLowerCase() }));\n        } else {\n          // activeTab === 'create'. Typed content isn't required to submit\n          // -- this tab has no file requirement (only the Upload tab does,\n          // per Martin) -- the filename just always reflects that this\n          // attempt was a typed answer, not an uploaded document.\n          files = [{ name: `${item.title.replace(/\\s+/g, '_')}_Answer.txt`, ext: 'txt' }];\n        }\n        const comment = (commentEl.value || '').trim();\n        const entry = { files, timestamp: 'Just now' };\n        if (comment) entry.comment = comment;\n        submissionHistory.push(entry);\n        currentStatus = 'submitted';\n        closeModal();\n        renderSubmissionsPanel();\n      });\n    }\n\n    renderSubmissionsPanel();\n    // Signed in with Schoology: the real Submission History (2026-10-06).\n    // Quizzes are taken on Schoology and show no history here.\n    if (SUBMIT_LIVE && item.type !== 'assessment') loadLiveHistory();\n\n    // ------------------------------------------------------------------\n    // Drafts (2026-10-04, per Martin): Edit in Canva sends the file over to\n    // Drafts, above Submissions, with Submit and Delete. Canva isn't\n    // connected yet, so this only runs in the preview; signed in, Edit in\n    // Canva keeps its Coming soon menu. Real flow: POST /canva/edit opens\n    // Canva, Canva's return brings the student back here, and the drafts\n    // list comes from the API instead of this in-memory array.\n    // ------------------------------------------------------------------\n    const drafts = [];\n    let draftSeq = 0;\n    const draftsSec = document.getElementById('draftsSec');\n    const draftsList = document.getElementById('draftsList');\n    const TRASH_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M10 11v6M14 11v6M5 7l1 12a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2l1-12M9 7V4h6v3\"/></svg>';\n    const reduceMotion = () => window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n    const DRAFT_APP = { canva: 'Canva', gdrive: 'Google Drive', onedrive: 'OneDrive', course: 'Course file' };\n    const DRAFT_EXT_COLOR = Object.assign({ doc: '#3b6fd1', xlsx: '#2f7d54', xls: '#2f7d54', ppt: '#d1852f' }, EXT_COLOR);\n    function draftBadgeHTML(d) {\n      if (window.AveragesFileIcons) {\n        const x = String(d.ext || '').toLowerCase();\n        const k = d.app === 'canva' ? 'canva' : d.app === 'gdrive' ? ({ doc: 'gdoc', docx: 'gdoc', ppt: 'gslide', pptx: 'gslide', xls: 'gsheet', xlsx: 'gsheet', csv: 'gsheet' })[x] || 'gdoc' : x || 'file';\n        return fileIcon(k, '', 36);\n      }\n      if (d.app === 'gdrive') return `<span class=\"draft-badge drive\" aria-hidden=\"true\" style=\"background:${(DRIVE_KIND[d.ext] || DRIVE_KIND.docx)[1]}\">${(DRIVE_KIND[d.ext] || DRIVE_KIND.docx)[0]}</span>`;\n      if (d.app === 'canva') return '<span class=\"draft-badge\" aria-hidden=\"true\"><span class=\"canva-mark\"></span></span>';\n      const ext = String(d.ext || 'file').toLowerCase();\n      return `<span class=\"draft-badge drive\" aria-hidden=\"true\" style=\"background:${escapeHtml(DRAFT_EXT_COLOR[ext] || '#83849a')}\">${escapeHtml(ext.toUpperCase().slice(0, 4))}</span>`;\n    }\n    // ------------------------------------------------------------------\n    // Turning in a draft (2026-10-10, Martin's mockup): Turn in flips the row\n    // to  ×  [Send a Copy ⇅ | Submit]. Send a Copy turns in a PDF (Canva\n    // makes it; Google Drive exports it), as before. Share a Link (drafts\n    // only) turns in a link as a text answer: a Google Drive draft is shared\n    // \"anyone with the link\" as viewer or commenter, never editor; Canva has\n    // no API for sharing, so the student pastes Canva's own view link.\n    // Submit runs a step bar like Cloudflare's deploys: one segment per step.\n    // ------------------------------------------------------------------\n    const TI = new Map();   // draft id -> { turning, mode, role, menu, access, url, busy, prog, err, doneText }\n    const tiSvg = d => `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">${d}</svg>`;\n    const TI_ICON = {\n      x: tiSvg('<path d=\"M6 6l12 12M18 6L6 18\"/>'),\n      copy: tiSvg('<rect x=\"8\" y=\"8\" width=\"12\" height=\"13\" rx=\"2\"/><path d=\"M16 8V5a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v11a2 2 0 0 0 2 2h2\"/>'),\n      link: tiSvg('<path d=\"M6.5 19a4.5 4.5 0 0 1-.4-9A6 6 0 0 1 17.6 8.5 4.3 4.3 0 0 1 17.5 19z\"/>'),\n      ud: '<svg class=\"ti-ud\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M8 9l4-4 4 4M8 15l4 4 4-4\"/></svg>',\n      ck: '<svg class=\"ti-ck\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg>',\n      globe: tiSvg('<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18\"/>'),\n      person: tiSvg('<circle cx=\"9\" cy=\"8\" r=\"3.5\"/><path d=\"M3 20a6 6 0 0 1 12 0\"/><path d=\"M16 11l2 2 4-4\"/>'),\n      chev: '<svg class=\"ti-chev\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 6l6 6-6 6\"/></svg>',\n      eye: tiSvg('<path d=\"M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>'),\n      bubble: tiSvg('<path d=\"M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z\"/>'),\n      pen: tiSvg('<path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z\"/>'),\n      get: '<path d=\"M12 3v12\"/><path d=\"M7 10l5 5 5-5\"/><path d=\"M5 21h14\"/>',\n      pdf: '<path d=\"M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z\"/><path d=\"M14 3v5h5\"/>',\n      up: '<path d=\"M12 21V9\"/><path d=\"M7 14l5-5 5 5\"/><path d=\"M5 3h14\"/>',\n      chain: '<path d=\"M10 14a4 4 0 0 0 5.66 0l3-3a4 4 0 0 0-5.66-5.66l-1 1\"/><path d=\"M14 10a4 4 0 0 0-5.66 0l-3 3a4 4 0 0 0 5.66 5.66l1-1\"/>',\n      school: '<path d=\"M3 10l9-5 9 5-9 5z\"/><path d=\"M7 12v4c0 1.5 2.2 3 5 3s5-1.5 5-3v-4\"/>',\n      done: '<path d=\"M5 12.5l4.5 4.5L19 7.5\"/>',\n      spin: '<path d=\"M12 3a9 9 0 1 0 9 9\"/>',\n      fail: '<path d=\"M12 8v5M12 16.5v.5\"/><circle cx=\"12\" cy=\"12\" r=\"9\"/>',\n    };\n    const CANVA_VIEW_LINK = u => /^https:\\/\\/(www\\.)?canva\\.com\\/design\\/[A-Za-z0-9_-]+\\/[A-Za-z0-9_\\-\\/?=&.%]*$/.test(String(u || '').trim());\n    const isDriveDraft = d => !!d.drive || d.app === 'gdrive';\n    const isCanvaDraft = d => !d.drive && (d.live || d.app === 'canva');\n    // Share a Link is for Google Drive and Canva drafts (a course file or OneDrive file goes in as a copy).\n    const canLink = d => isDriveDraft(d) || isCanvaDraft(d);\n    function tiOpt(kind, val, on, icon, title, sub) {\n      return `<button class=\"ti-opt\" type=\"button\" role=\"${kind === 'mode' ? 'menuitemradio' : 'radio'}\" aria-checked=\"${on}\" data-draft-action=\"ti-${kind}\" data-val=\"${val}\">${TI_ICON.ck}${icon}<span><b>${title}</b><span>${sub}</span></span></button>`;\n    }\n    function tiBelowHTML(d, t) {\n      let html = '';\n      const roleWord = t.role === 'commenter' ? 'comment' : 'view';\n      if (t.mode === 'link' && isDriveDraft(d)) {\n        html += `<button class=\"ti-hint\" type=\"button\" data-draft-action=\"ti-access\" aria-expanded=\"${!!t.access}\"${t.busy ? ' disabled' : ''}>${TI_ICON.globe}<span>Anyone with the link can ${roleWord}.</span>${TI_ICON.chev}</button>`;\n        if (t.access) html += `<div class=\"ti-access\" role=\"radiogroup\" aria-label=\"People with the link can\">\n            ${tiOpt('role', 'reader', t.role !== 'commenter', TI_ICON.eye, 'Can view', 'Anyone with the link can look, nothing else.')}\n            ${tiOpt('role', 'commenter', t.role === 'commenter', TI_ICON.bubble, 'Can comment', 'Your teacher can leave comments on it.')}\n            <button class=\"ti-opt\" type=\"button\" role=\"radio\" aria-checked=\"false\" disabled>${TI_ICON.ck}${TI_ICON.pen}<span><b>Can edit</b><span>Not offered: nobody else should change your work.</span></span></button>\n          </div>`;\n      } else if (t.mode === 'link') {\n        html += `<p class=\"ti-hint\">${TI_ICON.globe}<span>Canva doesn’t let apps change sharing. In Canva: <b>Share</b> → <b>Anyone with the link</b> → <b>Can view</b> → <b>Copy link</b>, then paste it here.</span></p>\n          <label class=\"ti-paste\"><span class=\"sr-only\">Canva view link for ${escapeHtml(d.name)}</span><input type=\"url\" inputmode=\"url\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"https://www.canva.com/design/…\" data-ti-url value=\"${escapeHtml(t.url || '')}\"${t.busy ? ' disabled' : ''}></label>`;\n      } else {\n        html += `<p class=\"ti-hint\">${TI_ICON.person}<span>Your teacher gets ${d.live || d.app === 'canva' ? 'a PDF of it' : 'a copy'} as it is now. Later edits won’t show.</span></p>`;\n      }\n      if (t.prog) html += tiProgHTML(d, t);\n      if (t.menu) html += `<div class=\"ti-menu\" role=\"menu\">\n          ${tiOpt('mode', 'link', t.mode === 'link', TI_ICON.link, 'Share a Link', isDriveDraft(d) ? 'Your teacher opens the live file with a link.' : 'Turn in Canva’s view link to your design.')}\n          ${tiOpt('mode', 'copy', t.mode !== 'link', TI_ICON.copy, 'Send a Copy', isDriveDraft(d) ? 'Turn in a PDF of it as it is now.' : isCanvaDraft(d) ? 'Turn in a PDF of your design as it is now.' : 'Turn in the file as it is now.')}\n        </div>`;\n      return `<div class=\"ti-below\">${html}</div>`;\n    }\n    /** The steps for this draft and choice; each gets a share of the bar about as big as the time it usually takes. */\n    function tiSteps(d, t) {\n      if (t.mode === 'link') return [\n        isDriveDraft(d) ? { icon: 'chain', label: 'Making the view link', w: 1 } : { icon: 'chain', label: 'Checking your Canva link', w: 1 },\n        { icon: 'school', label: 'Sending it to your school', w: 2 },\n      ];\n      return [\n        isDriveDraft(d) ? { icon: 'get', label: 'Getting it from Google Drive', w: 2 } : isCanvaDraft(d) ? { icon: 'pdf', label: 'Making a PDF in Canva', w: 3 } : { icon: 'get', label: 'Getting the file', w: 1 },\n        { icon: 'up', label: 'Uploading', w: 2, bytes: true },\n        { icon: 'school', label: 'Turning in', w: 1 },\n      ];\n    }\n    function tiProgHTML(d, t) {\n      const P = t.prog;\n      const segs = P.steps.map((st, i) => {\n        const state = P.failedAt === i ? 'fail' : (i < P.i || P.finished) ? 'done' : i === P.i ? 'now' : 'next';\n        const ic = state === 'done' ? 'done' : state === 'fail' ? 'fail' : state === 'now' ? 'spin' : st.icon;\n        const fill = state === 'now' && st.bytes && P.frac != null\n          ? `<i class=\"ti-fill\" data-ti-fill style=\"width:${Math.round(P.frac * 100)}%\"></i>`\n          : `<i class=\"ti-fill${state === 'now' ? ' ind' : ''}\"></i>`;\n        return `<span class=\"ti-seg ${state}${P.finished ? ' ok' : ''}\" style=\"flex:${st.w} 1 0\"><span class=\"ti-track\">${fill}</span><span class=\"ti-lab\"><svg class=\"${ic === 'spin' ? 'ti-spin' : ''}\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">${TI_ICON[ic]}</svg><span>${st.label}</span></span></span>`;\n      }).join('');\n      const cur = P.steps[Math.min(P.i, P.steps.length - 1)];\n      const head = P.finished ? 'Turned in' : P.failedAt != null ? 'Couldn’t turn it in' : `${P.note || cur.label}…`;\n      const mb = n => (n / (1024 * 1024)).toFixed(1);\n      const right = P.finished ? 'Done' : P.failedAt != null ? '' : cur.bytes && P.size && P.frac != null ? `${mb(P.frac * P.size)} of ${mb(P.size)} MB` : `Step ${P.i + 1} of ${P.steps.length}`;\n      const err = P.failedAt != null ? `<p class=\"ti-err\" role=\"alert\"><span>${t.err || 'Nothing was turned in.'}</span><button type=\"button\" data-draft-action=\"ti-submit\">Try again</button></p>` : '';\n      return `<div class=\"ti-prog\" role=\"status\" aria-live=\"polite\"><div class=\"ti-head\"><span>${escapeHtml(head)}</span><small data-ti-right>${escapeHtml(right)}</small></div><div class=\"ti-segs\">${segs}</div>${err}</div>`;\n    }\n\n    // ---- motion (none with reduced motion / Potato mode) ----\n    const tiStill = () => reduceMotion() || !!(document.body && document.body.classList.contains('potato-mode'));\n    const TI_EASE = 'cubic-bezier(.2,.8,.2,1)';\n    const tiRow = id => draftsList.querySelector(`[data-draft=\"${CSS.escape(id)}\"]`);\n    const tiQ = (id, sel) => { const r = tiRow(id); return r ? r.querySelector(sel) : null; };\n    const tiW = el => (el ? el.getBoundingClientRect().width : 0);\n    function tiAnim(el, frames, ms, delay) { if (el && el.animate && !tiStill()) el.animate(frames, { duration: ms, delay: delay || 0, easing: TI_EASE, fill: 'backwards' }); }\n    function tiMorph(el, from, ms) {\n      if (!el || !from || tiStill() || !el.animate) return;\n      const to = tiW(el);\n      if (Math.abs(to - from) > 1) el.animate([{ width: from + 'px' }, { width: to + 'px' }], { duration: ms, easing: TI_EASE });\n    }\n    function tiGrow(id, from, ms) {\n      const row = tiRow(id);\n      if (!row || !from || tiStill() || !row.animate) return;\n      const to = row.offsetHeight;\n      if (Math.abs(to - from) < 2) return;\n      row.style.overflow = 'hidden';\n      row.animate([{ height: from + 'px' }, { height: to + 'px' }], { duration: ms, easing: TI_EASE }).onfinish = () => { row.style.overflow = ''; };\n    }\n    const tiRoll = el => tiAnim(el && el.querySelector('.ti-t'), [{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'none' }], 240, 60);\n    /** Redraws one draft row (keeps the rest of the list as it is), with an optional motion. */\n    function tiDraw(id, motion, focusSel) {\n      const old = tiRow(id);\n      if (!old) { renderDrafts(); return; }\n      const before = { main: tiW(old.querySelector('.ti-main')), pick: tiW(old.querySelector('.ti-pick')), h: old.offsetHeight };\n      const d = drafts.find(x => x.id === id);\n      if (!d) { renderDrafts(); return; }\n      const tmp = document.createElement('div');\n      tmp.innerHTML = draftRowHTML(d).trim();\n      old.replaceWith(tmp.firstElementChild);\n      if (focusSel) { const f = tiQ(id, focusSel); if (f) f.focus({ preventScroll: true }); }\n      tiPlaceMenu(id);\n      if (!motion) return;\n      if (motion !== 'menu') tiGrow(id, before.h, 300);\n      if (motion === 'in') {\n        // Turn in → Submit: the button narrows and its word rolls over; the pill slides out from behind it; × spins in.\n        tiMorph(tiQ(id, '.ti-main'), before.main, 300);\n        tiRoll(tiQ(id, '.ti-main'));\n        tiAnim(tiQ(id, '.ti-pick'), [{ opacity: 0, transform: 'translateX(40px) scale(.9)' }, { opacity: 1, transform: 'none' }], 320, 40);\n        tiAnim(tiQ(id, '.ti-x'), [{ opacity: 0, transform: 'scale(.4) rotate(-90deg)' }, { opacity: 1, transform: 'none' }], 280, 90);\n        tiAnim(tiQ(id, '.ti-below'), [{ opacity: 0, transform: 'translateY(-8px)' }, { opacity: 1, transform: 'none' }], 260, 140);\n      } else if (motion === 'mode') {\n        tiMorph(tiQ(id, '.ti-pick'), before.pick, 260);\n        tiRoll(tiQ(id, '.ti-pick'));\n        tiAnim(tiQ(id, '.ti-hint'), [{ opacity: 0, transform: 'translateY(-6px)' }, { opacity: 1, transform: 'none' }], 240, 40);\n      } else if (motion === 'menu') {\n        tiAnim(tiQ(id, '.ti-menu'), [{ opacity: 0, transform: 'translateY(-6px) scale(.96)' }, { opacity: 1, transform: 'none' }], 200);\n      } else if (motion === 'busy') {\n        tiAnim(tiQ(id, '.ti-prog'), [{ opacity: 0, transform: 'translateY(-6px)' }, { opacity: 1, transform: 'none' }], 220);\n      } else if (motion === 'back') {\n        tiMorph(tiQ(id, '.ti-main'), before.main, 300);\n        tiRoll(tiQ(id, '.ti-main'));\n        tiAnim(tiQ(id, '.canva-btn'), [{ opacity: 0, transform: 'translateX(24px)' }, { opacity: 1, transform: 'none' }], 300, 60);\n        tiAnim(tiQ(id, '.draft-meta'), [{ opacity: 0, transform: 'translateY(4px)' }, { opacity: 1, transform: 'none' }], 260, 80);\n      }\n    }\n    function tiPlaceMenu(id) {\n      const menu = tiQ(id, '.ti-menu'), pick = tiQ(id, '.ti-pick'), row = tiRow(id);\n      if (!menu || !pick || !row) return;\n      const r = row.getBoundingClientRect(), b = pick.getBoundingClientRect();\n      menu.style.top = (b.bottom - r.top + 6) + 'px';\n      menu.style.right = Math.max(8, r.right - b.right - 40) + 'px';\n    }\n    /** × : one smooth motion, the reverse of Turn in. The row goes back at once while copies of the pill, × and the lines below leave. */\n    function tiCancel(id) {\n      const t = TI.get(id);\n      if (!t || t.busy) return;\n      const row = tiRow(id);\n      const h0 = row ? row.offsetHeight : 0;\n      const m0 = tiQ(id, '.ti-main') ? tiQ(id, '.ti-main').getBoundingClientRect() : null;\n      const box0 = row ? row.getBoundingClientRect() : null;\n      const ghosts = [];\n      const ghost = el => {\n        if (!el || !box0 || tiStill()) return null;\n        const r = el.getBoundingClientRect();\n        const g = el.cloneNode(true);\n        g.removeAttribute('data-draft-action');\n        g.querySelectorAll('[data-draft-action]').forEach(x => x.removeAttribute('data-draft-action'));\n        Object.assign(g.style, { position: 'absolute', left: (r.left - box0.left) + 'px', top: (r.top - box0.top) + 'px', width: r.width + 'px', height: r.height + 'px', margin: '0', pointerEvents: 'none', zIndex: 1 });\n        g.setAttribute('aria-hidden', 'true');\n        ghosts.push(g);\n        return g;\n      };\n      const gGrp = ghost(tiQ(id, '.ti-grp'));\n      if (gGrp) { const mm = gGrp.querySelector('.ti-main'); if (mm) mm.style.visibility = 'hidden'; }\n      const gX = ghost(tiQ(id, '.ti-x'));\n      const gBelow = ghost(tiQ(id, '.ti-below'));\n      TI.delete(id);\n      const d = drafts.find(x => x.id === id);\n      const kept = t.doneText;   // a turn-in done earlier still shows on the row\n      if (kept) TI.set(id, { doneText: kept });\n      tiDraw(id, null, '[data-draft-action=\"turnin\"]');\n      if (tiStill() || !d) return;\n      const nrow = tiRow(id);\n      if (!nrow) return;\n      ghosts.forEach(g => nrow.appendChild(g));\n      const T = 280;\n      tiGrow(id, h0, T);\n      const m = tiQ(id, '.ti-main');\n      if (m && m0) {\n        const r1 = m.getBoundingClientRect();\n        m.style.position = 'relative'; m.style.zIndex = '2';\n        m.animate([\n          { width: m0.width + 'px', height: m0.height + 'px', transform: `translate(${m0.right - r1.right}px, ${(m0.top + m0.height / 2) - (r1.top + r1.height / 2)}px)` },\n          { width: r1.width + 'px', height: r1.height + 'px', transform: 'none' },\n        ], { duration: T, easing: TI_EASE });\n        tiAnim(m.querySelector('.ti-t'), [{ opacity: 0, transform: 'translateY(-8px)' }, { opacity: 1, transform: 'none' }], 220, 60);\n      }\n      tiAnim(tiQ(id, '.canva-btn'), [{ opacity: 0, transform: 'translateX(24px)' }, { opacity: 1, transform: 'none' }], T, 70);\n      const out = { duration: 220, easing: 'cubic-bezier(.4,0,1,1)', fill: 'forwards' };\n      if (gGrp) {\n        gGrp.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 160, easing: 'ease-out', fill: 'forwards' });\n        const gp = gGrp.querySelector('.ti-pick');\n        if (gp) gp.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(40px) scale(.9)' }], out);\n      }\n      if (gX) gX.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'scale(.4) rotate(-90deg)' }], out);\n      if (gBelow) gBelow.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateY(-8px)' }], { duration: 180, easing: 'ease-in', fill: 'forwards' });\n      setTimeout(() => { ghosts.forEach(g => g.remove()); if (m) { m.style.position = ''; m.style.zIndex = ''; } }, T + 20);\n    }\n\n    // ---- running a turn-in ----\n    function tiSubmit(d) {\n      const t = TI.get(d.id);\n      if (!t || t.busy) return;\n      t.menu = false; t.access = false;\n      if (t.mode === 'link' && !isDriveDraft(d) && !CANVA_VIEW_LINK(t.url)) {\n        t.err = escapeHtml(submitMessage({ code: 'canva_link_needed' }));\n        t.prog = { steps: tiSteps(d, t), i: 0, frac: null, size: 0, failedAt: 0, finished: false };\n        tiDraw(d.id, null, '[data-ti-url]');\n        return;\n      }\n      const C = window.AveragesCloud;\n      // Inside this click: Google may need its sign-in window.\n      const token = d.live && isDriveDraft(d) ? driveReadToken(C) : null;\n      if (token) token.catch(() => {});\n      t.busy = true; t.err = '';\n      t.prog = { steps: tiSteps(d, t), i: 0, frac: null, size: 0, failedAt: null, finished: false, note: '' };\n      tiDraw(d.id, 'busy');\n      const P = t.prog;\n      const paint = () => {\n        const box = tiQ(d.id, '.ti-prog');\n        if (!box) return;\n        const tmp = document.createElement('div');\n        tmp.innerHTML = tiProgHTML(d, t);\n        box.replaceWith(tmp.firstElementChild);\n      };\n      const step = (i, note) => { P.i = i; P.frac = null; P.note = note || ''; paint(); };\n      const onUpload = p => {\n        if (p.phase === 'hashing') { if (P.i !== 1 || P.note !== 'Getting ready') step(1, 'Getting ready'); return; }\n        if (p.phase === 'uploading') {\n          if (P.i !== 1 || P.note) { P.i = 1; P.note = ''; P.frac = p.fraction || 0; paint(); return; }\n          P.frac = p.fraction || 0;\n          const fill = tiQ(d.id, '[data-ti-fill]'), right = tiQ(d.id, '[data-ti-right]');\n          if (fill) fill.style.width = Math.round(P.frac * 100) + '%'; else paint();\n          if (right && P.size) right.textContent = `${(P.frac * P.size / 1048576).toFixed(1)} of ${(P.size / 1048576).toFixed(1)} MB`;\n          return;\n        }\n        if (p.phase === 'finishing' && P.i < 2) step(2);\n      };\n      const run = async () => {\n        if (!d.live) {\n          // The preview: same steps, made up.\n          for (let i = 0; i < P.steps.length; i++) {\n            step(i);\n            if (P.steps[i].bytes) { P.size = 2.4 * 1048576; for (let f = 0; f <= 1.0001; f += 0.1) { onUpload({ phase: 'uploading', fraction: f }); await new Promise(r => setTimeout(r, 60)); } }\n            else await new Promise(r => setTimeout(r, 450));\n          }\n          return null;\n        }\n        const S = await loadSubmitScript();\n        const section = String(item.courseId), assignment = String(item.id);\n        if (t.mode === 'link') {\n          let link;\n          if (isDriveDraft(d)) {\n            if (!C || typeof C.googleShareLink !== 'function') throw { code: 'not_configured' };\n            link = await C.googleShareLink(await token, d.driveId, t.role === 'commenter' ? 'commenter' : 'reader');\n          } else link = { url: String(t.url).trim(), name: d.name };\n          step(1);\n          const html = `<p><a href=\"${escapeHtml(link.url)}\">${escapeHtml(link.name || d.name)}</a></p>`;\n          return S.submitText({ section, assignment, html });\n        }\n        let file;\n        if (isDriveDraft(d)) {\n          if (!C || typeof C.googleDownload !== 'function') throw { code: 'not_configured' };\n          const r = await C.googleDownload(await token, d.driveId);\n          if (!r || !r.blob) throw { code: 'download_failed' };\n          file = { blob: r.blob, name: String(r.name || d.name + '.pdf') };\n        } else {\n          file = await S.exportCanva(d.designId, { title: d.name });\n        }\n        P.size = file.blob ? file.blob.size : 0;\n        step(1);\n        return S.submitFiles({ section, assignment, files: [file], onProgress: onUpload });\n      };\n      run().then(r => {\n        P.finished = true; P.i = P.steps.length - 1; paint();\n        const roleWord = t.role === 'commenter' ? 'comment' : 'view';\n        setTimeout(() => {\n          TI.set(d.id, { doneText: t.mode === 'link'\n            ? (isDriveDraft(d) ? `Turned in as a link · anyone with it can ${roleWord}` : 'Turned in as a Canva link')\n            : `Turned in as ${d.live || d.app === 'canva' ? 'a PDF' : 'a copy'} · just now` });\n          tiDraw(d.id, 'back');\n          if (d.live) afterTurnIn(r && r.revision);\n          else {\n            const outExt = d.app === 'canva' ? 'pdf' : (d.ext || 'docx');\n            submissionHistory.push({ files: [{ name: t.mode === 'link' ? `${d.name} (link)` : `${d.name}.${outExt}`, ext: t.mode === 'link' ? 'link' : outExt }], timestamp: 'Just now', fromCanva: d.app === 'canva', fromDrive: d.app === 'gdrive' });\n            currentStatus = 'submitted';\n            renderSubmissionsPanel();\n          }\n        }, 900);\n      }).catch(err => {\n        if (err && err.code === 'popup_closed') { t.busy = false; t.prog = null; tiDraw(d.id); return; }\n        t.busy = false;\n        P.failedAt = P.i;\n        t.err = submitErrorHTML(err && typeof err === 'object' ? err : { code: String(err) });\n        if (err && err.code === 'canva_design_gone') { removeDraftRow(d.id); return; }\n        tiDraw(d.id);\n      });\n    }\n    // Typing the Canva link is kept as it's typed (the row redraws keep it).\n    draftsList.addEventListener('input', e => {\n      const inp = e.target.closest('[data-ti-url]');\n      if (!inp) return;\n      const t = TI.get(inp.closest('[data-draft]').dataset.draft);\n      if (t) t.url = inp.value;\n    });\n    draftsList.addEventListener('keydown', e => {\n      if (e.key === 'Enter' && e.target.closest('[data-ti-url]')) {\n        const id = e.target.closest('[data-draft]').dataset.draft;\n        const d = drafts.find(x => x.id === id);\n        if (d) { e.preventDefault(); tiSubmit(d); }\n      }\n    });\n    document.addEventListener('keydown', e => {\n      if (e.key !== 'Escape' || !modalOverlay.hidden) return;\n      for (const [id, t] of TI) { if (t.menu) { t.menu = false; tiDraw(id, null, '.ti-pick'); return; } }\n      for (const [id, t] of TI) { if (t.turning && !t.busy) { tiCancel(id); return; } }\n    });\n    document.addEventListener('click', e => {\n      if (e.target.closest('.ti-menu') || e.target.closest('.ti-pick')) return;\n      for (const [id, t] of TI) if (t.menu) { t.menu = false; tiDraw(id); }\n    });\n    window.addEventListener('resize', () => { for (const [id, t] of TI) if (t.menu) tiPlaceMenu(id); });\n\n    function draftRowHTML(d) {\n      const nm = escapeHtml(d.name);\n      const tip = (label, inner) => `<span class=\"tipwrap\">${inner}<span class=\"tip\" role=\"tooltip\">${label}</span></span>`;\n      const testItem = item.type === 'assessment';\n      const t = TI.get(d.id);\n      // Can this draft be turned in from here? (Signed in: Drive needs its download; Canva needs our API.)\n      let can = !testItem, why = testItem ? 'Tests are turned in on Schoology' : '';\n      if (d.live && d.drive && !(SUBMIT_LIVE && driveDownloadReady())) { can = false; why = why || 'Turning in from Averages.io is coming soon'; }\n      if (d.live && !d.drive && !SUBMIT_LIVE) { can = false; why = why || 'Turning in from Averages.io is coming soon'; }\n      let open = '', meta;\n      if (d.live && d.drive) {\n        // Signed in (2026-10-05): a Google Doc/Slides/Sheet made by Edit in Google Drive (remembered in this browser).\n        open = `<button class=\"canva-btn drive-btn\" type=\"button\" data-draft-action=\"open\" aria-label=\"Open ${nm} in Google Drive\"><span>Open in Google Drive</span></button>`;\n        meta = `Google Drive draft · Edited ${escapeHtml(d.edited)}`;\n      } else if (d.live) {\n        // Signed in (2026-10-05): a real Canva design (our API keeps the list).\n        open = `<button class=\"canva-btn\" type=\"button\" data-draft-action=\"open\" aria-label=\"Open ${nm} in Canva\"><span class=\"canva-mark\" aria-hidden=\"true\"></span><span>Open in Canva</span></button>`;\n        meta = `Canva draft · Edited ${escapeHtml(d.edited)}`;\n      } else {\n        meta = d.attached ? `${DRAFT_APP[d.app] || 'File'} · Added from Files` : `${DRAFT_APP[d.app] || 'Canva'} draft · Edited ${escapeHtml(d.edited)}`;\n      }\n      if (t && t.doneText) meta = escapeHtml(t.doneText);\n      const turning = !!(t && t.turning);\n      let actions;\n      if (!turning) {\n        const turnIn = `<button class=\"draft-submit ti-main\" type=\"button\" data-draft-action=\"turnin\"${can ? '' : ' disabled'} aria-label=\"Turn in ${nm}\"><span class=\"ti-t\">Turn in</span></button>`;\n        actions = `${open}\n            ${can ? turnIn : tip(why, turnIn)}\n            ${tip('Delete draft', `<button class=\"material-icon-btn\" type=\"button\" data-draft-action=\"delete\" aria-label=\"Delete draft ${nm}\">${TRASH_ICON}</button>`)}`;\n      } else {\n        const off = t.busy ? ' disabled' : '';\n        actions = `<button class=\"ti-x\" type=\"button\" data-draft-action=\"ti-cancel\" aria-label=\"Don’t turn in ${nm}\"${off}>${TI_ICON.x}</button>\n            <span class=\"ti-grp\">\n              <button class=\"ti-pick\" type=\"button\" data-draft-action=\"ti-pick\"${canLink(d) ? ` aria-haspopup=\"menu\" aria-expanded=\"${!!t.menu}\"${off}` : ' disabled'}><span class=\"ti-t\">${t.mode === 'link' ? TI_ICON.link : TI_ICON.copy}${t.mode === 'link' ? 'Share a Link' : 'Send a Copy'}</span>${canLink(d) ? TI_ICON.ud : ''}</button>\n              <button class=\"draft-submit ti-main\" type=\"button\" data-draft-action=\"ti-submit\"${off}><span class=\"ti-t\">Submit</span></button>\n            </span>`;\n      }\n      return `\n        <div class=\"material-row file-bar draft-row${turning ? ' ti-on' : ''}\" data-draft=\"${escapeHtml(d.id)}\">\n          ${draftBadgeHTML(d)}\n          <span class=\"draft-text\">\n            <span class=\"material-name\">${nm}</span>\n            <span class=\"draft-meta\">${meta}</span>\n          </span>\n          <div class=\"material-actions${turning ? ' ti-acts' : ''}\">\n            ${actions}\n          </div>\n          ${turning ? tiBelowHTML(d, t) : ''}\n        </div>`;\n    }\n    function renderDrafts() {\n      draftsSec.hidden = drafts.length === 0 && draftsNote.hidden;\n      draftsList.innerHTML = drafts.map(draftRowHTML).join('');\n    }\n    // Signed in (2026-10-05): drafts are the student's real Canva designs, kept by the API.\n    const draftsNote = document.createElement('p');\n    draftsNote.className = 'drafts-note';\n    draftsNote.setAttribute('role', 'status');\n    draftsNote.hidden = true;\n    draftsList.parentNode.insertBefore(draftsNote, draftsList);\n    function editedLabel(ms) {\n      const t = Number(ms) || 0;\n      if (!t) return 'recently';\n      const mins = Math.round((Date.now() - t) / 60000);\n      if (mins < 1) return 'just now';\n      if (mins < 60) return `${mins} min ago`;\n      const hrs = Math.round(mins / 60);\n      if (hrs < 24) return `${hrs} hour${hrs === 1 ? '' : 's'} ago`;\n      return new Date(t).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });\n    }\n    function liveDraft(api) {\n      return { id: 'c-' + api.designId, designId: String(api.designId), name: String(api.title || api.sourceName || 'Canva design'), app: 'canva', edited: editedLabel(api.updatedAt), t: Number(api.updatedAt) || 0, live: true };\n    }\n    function driveDraft(g) {\n      return { id: 'g-' + g.fileId, driveId: String(g.fileId), name: String(g.name || 'Google Drive file'), app: 'gdrive', ext: String(g.ext || 'docx'), edited: editedLabel(g.modifiedTime), t: Number(g.modifiedTime) || 0, link: String(g.webViewLink || ''), live: true, drive: true };\n    }\n    // Canva's drafts come from the API, Google Drive's from this browser; one list, newest first.\n    let canvaDrafts = [];\n    function mergeDrafts() {\n      const C = window.AveragesCloud;\n      const drive = C ? C.listDriveDrafts(String(item.courseId), String(item.id)).map(driveDraft) : [];\n      drafts.splice(0, drafts.length, ...canvaDrafts.concat(drive).sort((a, b) => (b.t || 0) - (a.t || 0)));\n      renderDrafts();\n    }\n    function upsertLiveDraft(api) {\n      if (!api || !api.designId) return;\n      const d = liveDraft(api);\n      const i = drafts.findIndex(x => x.id === d.id);\n      if (i === -1) drafts.unshift(d); else drafts[i] = d;\n    }\n    async function loadLiveDrafts(cameBack) {\n      try {\n        const res = await fetch(`${averagesApiBase()}/canva/drafts?section=${encodeURIComponent(item.courseId)}&assignment=${encodeURIComponent(item.id)}`, { credentials: 'include' });\n        if (!res.ok) return;\n        const j = await res.json();\n        canvaDrafts = (Array.isArray(j.drafts) ? j.drafts : []).filter(x => x && x.designId).map(liveDraft);\n        mergeDrafts();\n        if (cameBack && drafts.length) pulse(draftsList.querySelector('.draft-row'));\n      } catch {\n        /* Drafts are extra: the rest of the page works without them */\n      }\n    }\n    async function openLiveDraft(d, btn) {\n      if (btn.getAttribute('aria-busy') === 'true') return;\n      const label = btn.querySelector('span:last-child');\n      btn.setAttribute('aria-busy', 'true');\n      if (label) label.textContent = 'Opening…';\n      const done = () => { btn.removeAttribute('aria-busy'); if (label) label.textContent = 'Open in Canva'; };\n      const tab = openCanvaTab();\n      try {\n        const res = await fetch(`${averagesApiBase()}/canva/designs/${encodeURIComponent(d.designId)}/open`, {\n          method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ returnTo: currentAppPath() }),\n        });\n        const j = await res.json().catch(() => ({}));\n        if (res.ok && typeof j.editUrl === 'string' && CANVA_EDIT_URL.test(j.editUrl)) { if (sendToCanva(tab, j.editUrl)) done(); return; }\n        closeCanvaTab(tab);\n        done();\n        if (j.error === 'canva_design_gone') removeDraftRow(d.id);\n        showCanvaProblem(j.error);\n      } catch {\n        closeCanvaTab(tab);\n        done();\n        showCanvaProblem('network');\n      }\n    }\n    function pulse(el) {\n      if (!el || reduceMotion() || !el.animate) return;\n      el.animate([{ boxShadow: '0 0 0 2px var(--accent-ring)' }, { boxShadow: '0 0 0 0 transparent' }], { duration: 900, easing: 'ease-out' });\n    }\n    function editInCanvaPreview(btn) {\n      const source = btn.dataset.fileName || 'File';\n      const base = source.replace(/\\.[^.]+$/, '');\n      const app = btn.dataset.fileAction === 'gdrive' ? 'gdrive' : 'canva';\n      const existing = drafts.find(d => d.source === source && d.app === app);\n      if (existing) {   // already a draft: same design, just edited again\n        existing.edited = 'just now';\n        renderDrafts();\n        const row = draftsList.querySelector(`[data-draft=\"${existing.id}\"]`);\n        if (row) { row.scrollIntoView({ block: 'nearest', behavior: reduceMotion() ? 'auto' : 'smooth' }); pulse(row); }\n        return;\n      }\n      const fromEl = btn.closest('.file-bar');\n      const from = fromEl.getBoundingClientRect();\n      const d = { id: 'd' + (++draftSeq), source, name: base, edited: 'just now', app, ext: String(btn.dataset.fileExt || 'docx').toLowerCase() };\n      drafts.unshift(d);\n      renderDrafts();\n      const target = draftsList.querySelector(`[data-draft=\"${d.id}\"]`);\n      const done = () => {\n        const r = target.getBoundingClientRect();\n        if (r.top < 0 || r.bottom > window.innerHeight) target.scrollIntoView({ block: 'center', behavior: reduceMotion() ? 'auto' : 'smooth' });\n        pulse(target);\n      };\n      if (reduceMotion() || !target.animate) { done(); return; }\n      // Slide: a copy of the file bar flies from Attached Materials into its\n      // new spot in Drafts, then the real draft row takes its place.\n      const to = target.getBoundingClientRect();\n      // The flying card holds both rows, each at its own width, so nothing\n      // squishes: the old buttons fade out first, the file bar fades out,\n      // then the draft row fades in, and Submit/Delete fade in last.\n      const layer = (el, w) => {\n        const c = el.cloneNode(true);\n        c.querySelectorAll('[id]').forEach(n => n.removeAttribute('id'));\n        Object.assign(c.style, { position: 'absolute', left: '0', top: '0', width: w + 'px', margin: '0', visibility: 'visible' });\n        return c;\n      };\n      const ghost = document.createElement('div');\n      ghost.className = 'draft-ghost';\n      ghost.setAttribute('aria-hidden', 'true');\n      const oldRow = layer(fromEl, from.width), newRow = layer(target, to.width);\n      ghost.append(oldRow, newRow);\n      Object.assign(ghost.style, { left: from.left + 'px', top: from.top + 'px', width: from.width + 'px', height: from.height + 'px' });\n      document.body.appendChild(ghost);\n      target.style.visibility = 'hidden';\n      const D = 640;\n      const fade = (el, frames) => el && el.animate(frames, { duration: D, fill: 'both' });\n      fade(oldRow.querySelector('.material-actions'), [{ opacity: 1, transform: 'scale(1)' }, { opacity: 0, transform: 'scale(0.94)', offset: 0.22 }, { opacity: 0, transform: 'scale(0.94)' }]);\n      fade(oldRow, [{ opacity: 1 }, { opacity: 1, offset: 0.22 }, { opacity: 0, offset: 0.44, easing: 'ease-in' }, { opacity: 0 }]);\n      fade(newRow, [{ opacity: 0 }, { opacity: 0, offset: 0.46 }, { opacity: 1, offset: 0.72 }, { opacity: 1 }]);   // starts once the old row is gone: no two names on top of each other\n      fade(newRow.querySelector('.material-actions'), [{ opacity: 0, transform: 'scale(0.94)' }, { opacity: 0, transform: 'scale(0.94)', offset: 0.72 }, { opacity: 1, transform: 'scale(1)' }]);\n      const anim = ghost.animate([\n        { left: from.left + 'px', top: from.top + 'px', width: from.width + 'px', height: from.height + 'px' },\n        { left: to.left + 'px', top: to.top + 'px', width: to.width + 'px', height: to.height + 'px' },\n      ], { duration: D, easing: 'cubic-bezier(.2,.8,.2,1)' });\n      anim.onfinish = anim.oncancel = () => { ghost.remove(); target.style.visibility = ''; done(); };\n    }\n    function removeDraftRow(id, then) {\n      const row = draftsList.querySelector(`[data-draft=\"${id}\"]`);\n      const finish = () => { const i = drafts.findIndex(x => x.id === id); if (i !== -1) drafts.splice(i, 1); renderDrafts(); if (then) then(); };\n      if (!row || reduceMotion() || !row.animate) { finish(); return; }\n      row.classList.add('leaving');\n      const h = row.offsetHeight;\n      const a = row.animate([\n        { opacity: 1, height: h + 'px', marginTop: getComputedStyle(row).marginTop },\n        { opacity: 0, height: '0px', marginTop: '0px', paddingTop: '0px', paddingBottom: '0px' },\n      ], { duration: 220, easing: 'ease' });\n      a.onfinish = a.oncancel = finish;\n    }\n    // Submit on a draft, signed in (2026-10-06): \"Turn in ... as a PDF?\", then\n    // the PDF (Canva exports it; Google Drive exports a Doc/Slides/Sheet) goes\n    // through the same turn-in as Add Submission. The draft stays in Drafts.\n    function confirmSubmitDraft(d, fromBtn) {\n      openModal(`\n        <h3>Turn in \"${escapeHtml(d.name)}\" as a PDF?</h3>\n        <p>${d.drive ? 'Averages.io gets a PDF of it from your Google Drive and turns it in on Schoology.' : 'Canva makes a PDF of your design, and Averages.io turns it in on Schoology.'}</p>\n        <div class=\"upload-picked-progress\" id=\"draftSubProgress\" hidden><span class=\"upload-progress-text\"></span><span class=\"upload-bar\" aria-hidden=\"true\"><i></i></span></div>\n        <p class=\"submit-error\" id=\"submitError\" role=\"alert\" hidden></p>\n        <div class=\"modal-actions\">\n          <button class=\"modal-btn secondary\" type=\"button\" id=\"draftSubCancel\">Cancel</button>\n          <button class=\"modal-btn primary\" type=\"button\" id=\"draftSubOk\">Turn in</button>\n        </div>`);\n      modalBox.setAttribute('role', 'dialog'); modalBox.setAttribute('aria-modal', 'true');\n      const back = () => { if (fromBtn && document.body.contains(fromBtn)) fromBtn.focus(); };\n      const ok = document.getElementById('draftSubOk');\n      const errEl = document.getElementById('submitError');\n      const prog = document.getElementById('draftSubProgress');\n      const line = (text, fraction) => {\n        prog.hidden = false;\n        prog.querySelector('.upload-progress-text').textContent = text;\n        const bar = prog.querySelector('.upload-bar');\n        bar.hidden = fraction == null;\n        if (fraction != null) bar.firstElementChild.style.width = Math.round(fraction * 100) + '%';\n      };\n      document.getElementById('draftSubCancel').addEventListener('click', () => { closeModal(); back(); });\n      ok.addEventListener('click', () => {\n        if (ok.disabled) return;\n        const C = window.AveragesCloud;\n        const token = d.drive ? driveReadToken(C) : null;   // inside the click: it may open Google's window\n        if (token) token.catch(() => {});\n        const ctl = new AbortController();\n        activeSubmitAbort = () => ctl.abort();\n        ok.disabled = true;\n        ok.textContent = 'Turning in…';\n        errEl.hidden = true;\n        modalBox.setAttribute('aria-busy', 'true');\n        let name = d.name + '.pdf';\n        loadSubmitScript()\n          .then(async S => {\n            let file;\n            if (d.drive) {\n              line('Getting a PDF from Google Drive…', null);\n              if (!C || typeof C.googleDownload !== 'function') throw { code: 'not_configured' };\n              const r = await C.googleDownload(await token, d.driveId);\n              if (!r || !r.blob) throw { code: 'download_failed' };\n              file = { blob: r.blob, name: String(r.name || name) };\n            } else {\n              line(`Making a PDF of ${d.name}…`, null);\n              file = await S.exportCanva(d.designId, { title: d.name, signal: ctl.signal });\n            }\n            if (ctl.signal.aborted) throw { code: 'aborted' };\n            name = file.name;\n            return S.submitFiles({\n              section: String(item.courseId), assignment: String(item.id), files: [file], signal: ctl.signal,\n              onProgress: p => {\n                const pct = Math.round((p.fraction || 0) * 100);\n                if (p.phase === 'hashing') line(`Getting ready ${pct}%`, p.fraction);\n                else if (p.phase === 'uploading') line(`Uploading ${pct}%`, p.fraction);\n                else if (p.phase === 'finishing') line('Turning it in…', 1);\n              },\n            });\n          })\n          .then(r => {\n            if (ctl.signal.aborted) return;\n            showTurnedIn([name]);\n            afterTurnIn(r && r.revision);\n          })\n          .catch(err => {\n            if (ctl.signal.aborted || (err && err.code === 'aborted')) { loadLiveHistory(); return; }\n            activeSubmitAbort = null;\n            modalBox.removeAttribute('aria-busy');\n            prog.hidden = true;\n            ok.disabled = false;\n            ok.textContent = err && err.code === 'popup_closed' ? 'Turn in' : 'Try again';\n            if (err && err.code === 'popup_closed') return;\n            errEl.innerHTML = submitErrorHTML(err);\n            errEl.hidden = false;\n            if (err && err.code === 'canva_design_gone') removeDraftRow(d.id);\n          });\n      });\n      ok.focus();\n    }\n    // Are you sure? (2026-10-04, per Martin). Cancel is focused first, so a\n    // stray Enter doesn't delete anything; Escape also cancels.\n    function confirmDeleteDraft(d, fromBtn) {\n      openModal(`\n        <h3>Delete this draft?</h3>\n        <p>\"${escapeHtml(d.name)}\" will be removed from Drafts. This can't be undone. ${({ canva: 'Your design stays in your Canva account.', gdrive: 'The file stays in your Google Drive.', onedrive: 'The file stays in your OneDrive.', course: 'The file stays in Files.' })[d.app] || ''}</p>\n        <div class=\"modal-actions\">\n          <button class=\"modal-btn secondary\" type=\"button\" id=\"draftDelCancel\">Cancel</button>\n          <button class=\"modal-btn danger\" type=\"button\" id=\"draftDelOk\">Delete</button>\n        </div>`);\n      modalBox.setAttribute('role', 'alertdialog'); modalBox.setAttribute('aria-modal', 'true');\n      const back = () => { if (fromBtn && document.body.contains(fromBtn)) fromBtn.focus(); };\n      document.getElementById('draftDelCancel').addEventListener('click', () => { closeModal(); back(); });\n      document.getElementById('draftDelOk').addEventListener('click', async () => {\n        closeModal();\n        if (!d.live) { removeDraftRow(d.id); return; }\n        if (d.drive) {\n          // Only forgotten here; the file stays in their Google Drive.\n          if (window.AveragesCloud) window.AveragesCloud.removeDriveDraft(d.driveId);\n          removeDraftRow(d.id);\n          return;\n        }\n        // Signed in: forget it on the API first (the design stays in Canva).\n        try {\n          const res = await fetch(`${averagesApiBase()}/canva/drafts/${encodeURIComponent(d.designId)}`, { method: 'DELETE', credentials: 'include' });\n          if (!res.ok) throw new Error('status ' + res.status);\n          removeDraftRow(d.id);\n        } catch {\n          draftsNote.textContent = 'Couldn’t delete that draft. Try again.';\n          draftsNote.hidden = false;\n          draftsSec.hidden = false;\n        }\n      });\n      document.getElementById('draftDelCancel').focus();\n    }\n    draftsList.addEventListener('click', e => {\n      const btn = e.target.closest('[data-draft-action]');\n      if (!btn || btn.disabled) return;\n      const id = btn.closest('[data-draft]').dataset.draft;\n      const d = drafts.find(x => x.id === id);\n      if (!d) return;\n      const act = btn.dataset.draftAction;\n      if (act === 'turnin') { TI.set(id, { turning: true, mode: 'copy', role: 'reader', menu: false, access: false, url: '', busy: false, prog: null }); tiDraw(id, 'in', '.ti-pick'); return; }\n      const t = TI.get(id);\n      if (act === 'ti-cancel') { tiCancel(id); return; }\n      if (t && act === 'ti-pick') {\n        if (!canLink(d)) return;\n        t.menu = !t.menu; tiDraw(id, t.menu ? 'menu' : null, t.menu ? '.ti-menu [aria-checked=\"true\"]' : '.ti-pick'); return;\n      }\n      if (t && act === 'ti-mode') { const changed = t.mode !== btn.dataset.val; t.mode = btn.dataset.val === 'link' ? 'link' : 'copy'; t.menu = false; t.access = false; t.prog = null; tiDraw(id, changed ? 'mode' : null, t.mode === 'link' && !isDriveDraft(d) ? '[data-ti-url]' : '.ti-pick'); return; }\n      if (t && act === 'ti-access') { t.access = !t.access; tiDraw(id, null, '[data-draft-action=\"ti-access\"]'); return; }\n      if (t && act === 'ti-role') { t.role = btn.dataset.val === 'commenter' ? 'commenter' : 'reader'; tiDraw(id, null, `[data-draft-action=\"ti-role\"][data-val=\"${t.role}\"]`); return; }\n      if (t && act === 'ti-submit') { tiSubmit(d); return; }\n      if (btn.dataset.draftAction === 'delete') { confirmDeleteDraft(d, btn); return; }\n      if (btn.dataset.draftAction === 'open') {\n        if (d.drive) {\n          const C = window.AveragesCloud;\n          if (C && C.linkOk(d.link)) window.open(d.link, '_blank', 'noopener,noreferrer');\n          return;\n        }\n        if (d.live) openLiveDraft(d, btn);\n        return;\n      }\n      if (act !== 'submit') return;\n      // (Before 2026-10-10 Submit asked in a popup: confirmSubmitDraft, kept for reference.)\n      if (d.live) { confirmSubmitDraft(d, btn); return; }\n      // Submit: the Canva design goes in as a PDF, like any other turn-in.\n      removeDraftRow(id, () => {\n        // Canva designs go in as a PDF; a Google Drive file in its own format.\n        // Files attached from the Files page go in as they are.\n        const outExt = d.app === 'canva' ? 'pdf' : (d.ext || 'docx');\n        submissionHistory.push({ files: [{ name: `${d.name}.${outExt}`, ext: outExt }], timestamp: 'Just now', fromCanva: d.app === 'canva', fromDrive: d.app === 'gdrive' });\n        currentStatus = 'submitted';\n        renderSubmissionsPanel();\n      });\n    });\n\n    // Signed in: load this assignment's drafts, and say so when Canva's\n    // Return button brought the student back (?canva=saved).\n    if (LIVE_DETAIL && !CANVA_PREVIEW) {\n      const back = params.get('canva');\n      if (back === 'saved') {\n        draftsNote.textContent = 'Back from Canva. Your draft is saved here in Drafts.';\n        draftsNote.hidden = false;\n        draftsSec.hidden = false;\n      }\n      if (back) {\n        try {\n          const u = new URL(window.location.href);\n          u.searchParams.delete('canva');\n          window.history.replaceState(window.history.state, '', u.pathname + u.search + u.hash);\n        } catch (e) {}\n      }\n      if (!INCOGNITO && !CLASSROOM) {\n        loadLiveDrafts(back === 'saved');\n        // Canva works in its own tab now (2026-10-07): coming back here refreshes Drafts.\n        let draftsAt = Date.now();\n        document.addEventListener('visibilitychange', () => {\n          if (document.visibilityState !== 'visible' || Date.now() - draftsAt < 5000) return;\n          draftsAt = Date.now();\n          loadLiveDrafts(false);\n        });\n        loadCloud();\n        loadCanvaReady();\n      }\n    }\n\n    // Attach from Files (2026-10-05, per Martin): Files' \"Attach to an\n    // assignment\" opens this page with ?attach=<file name>&src=course|gdrive|\n    // onedrive|canva&ext=, and the file lands in Drafts, ready to Submit or\n    // Delete. Preview only (no Files API yet). The three params are dropped\n    // from the address afterwards so a reload doesn't add it again.\n    //\n    // Signed in (2026-10-06): ?attach= is JSON, { src, id, name, kind?, parent?,\n    // course? } (WAVES-CONTRACT.md), and opens Add Submission with that file\n    // already picked. Every field is checked: a bad one means nothing opens.\n    function parseAttach(raw) {\n      let j;\n      try { j = JSON.parse(raw); } catch { return null; }\n      if (!j || typeof j !== 'object' || Array.isArray(j)) return null;\n      const src = String(j.src || '');\n      const id = typeof j.id === 'string' || typeof j.id === 'number' ? String(j.id) : '';\n      const name = typeof j.name === 'string' ? j.name.replace(/[\\u0000-\\u001f\\u007f]/g, '').trim().slice(0, 200) : '';\n      if (!name || !PICK_ID_OK[src] || !PICK_ID_OK[src](id)) return null;\n      if (src !== 'course') return { src, id, name };\n      const kind = j.kind === undefined || j.kind === 'assignment' ? 'assignment' : j.kind === 'document' ? 'document' : '';\n      const parent = typeof j.parent === 'string' || typeof j.parent === 'number' ? String(j.parent) : '';\n      const course = typeof j.course === 'string' || typeof j.course === 'number' ? String(j.course) : '';\n      if (!kind || !/^\\d{1,20}$/.test(parent) || !/^\\d{1,20}$/.test(course)) return null;\n      return { src, id, name, kind, parent, course };\n    }\n    (function attachFromFiles() {\n      const raw = params.get('attach');\n      if (!raw) return;\n      try {\n        const u = new URL(location.href);\n        ['attach', 'src', 'ext'].forEach(k => u.searchParams.delete(k));\n        window.history.replaceState(window.history.state, '', u.pathname + u.search + u.hash);\n      } catch (e) {}\n      const parsed = /^\\s*\\{/.test(raw) ? parseAttach(raw) : null;\n      if (SUBMIT_LIVE) {\n        if (parsed && item.type !== 'assessment') openAddSubmissionModal({ attach: parsed });\n        return;\n      }\n      if (!CANVA_PREVIEW) return;\n      // The preview: the file lands in Drafts, from either form of the link.\n      if (/^\\s*\\{/.test(raw) && !parsed) return;\n      const name = parsed ? parsed.name : raw;\n      const src = parsed ? parsed.src : params.get('src');\n      const app = ['course', 'gdrive', 'onedrive', 'canva'].includes(src) ? src : 'course';\n      const ext = String(params.get('ext') || (name.match(/\\.([a-z0-9]+)$/i) || [0, 'pdf'])[1]).toLowerCase();\n      if (drafts.some(d => d.source === name && d.app === app)) return;\n      const d = { id: 'd' + (++draftSeq), source: name, name: name.replace(/\\.[a-z0-9]+$/i, ''), edited: 'just now', app, ext, attached: true };\n      drafts.unshift(d);\n      renderDrafts();\n      const row = draftsList.querySelector(`[data-draft=\"${d.id}\"]`);\n      if (row) { row.scrollIntoView({ block: 'center' }); pulse(row); }\n    })();\n\n    // Nav — Home/Courses/Assignments are real links between real pages;\n    // the rest stay visual-only placeholders until those pages exist.\n    document.querySelectorAll('.nav-link').forEach(link => {\n      link.addEventListener('click', () => {\n        if (link.dataset.href) { window.location.href = link.dataset.href; return; }\n        document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));\n        link.classList.add('active');\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Profile menu — same behavior as every other page.\n    // ------------------------------------------------------------------\n    const profileBtn = document.getElementById('profileBtn');\n    // Shared profile photo/name (2026-09-07) — /settings's Edit\n    // Profile modal is the only place this is ever set, but every other\n    // page's top-right profile button used to just show a fixed \"M\" no\n    // matter what was saved there: the button never read anything back,\n    // so a photo you set in Settings was invisible the moment you left\n    // it. schoolagy_profile is the same localStorage record\n    // /settings writes on every save; this is read-only here.\n    (function () {\n      var profile = null;\n      try {\n        var raw = localStorage.getItem('schoolagy_profile');\n        if (raw) profile = JSON.parse(raw);\n      } catch (e) {}\n      if (!profile) return;\n      if (profile.photo) {\n        profileBtn.style.backgroundImage = 'url(\"' + profile.photo + '\")';\n        profileBtn.style.backgroundSize = 'cover';\n        profileBtn.style.backgroundPosition = 'center';\n        profileBtn.textContent = '';\n      } else if (profile.name) {\n        profileBtn.textContent = profile.name.trim().charAt(0).toUpperCase() || 'M';\n      }\n    })();\n    const profileMenu = document.getElementById('profileMenu');\n    function openProfileMenu() { profileMenu.hidden = false; profileBtn.setAttribute('aria-expanded', 'true'); }\n    function closeProfileMenu() { profileMenu.hidden = true; profileBtn.setAttribute('aria-expanded', 'false'); }\n    profileBtn.addEventListener('click', () => { if (profileMenu.hidden) openProfileMenu(); else closeProfileMenu(); });\n    document.addEventListener('click', e => { if (!profileMenu.hidden && !e.target.closest('.profile-menu-wrap')) closeProfileMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !profileMenu.hidden) { closeProfileMenu(); profileBtn.focus(); } });\n    profileMenu.querySelectorAll('.profile-menu-item').forEach(item => {\n      item.addEventListener('click', () => {\n        if (item.dataset.action === 'settings') { window.location.href = '/settings'; return; }\n        closeProfileMenu();\n      });\n    });\n  \n\n\n    // Back link (2026-10-01, per Martin: \"where it returns to ... is always\n    // wrong\"). Every page records itself in a short per-tab trail; a page's\n    // back link then says and goes to the page before it (\"Back to AP\n    // Chemistry Hub\", \"Back to Grades\"...). With no trail (the page was\n    // opened directly) the page's own default back link is left alone.\n    (function () {\n      const SELF = '/assignment';\n      const KEY = 'averages_nav_trail';\n      const here = SELF + location.search;\n      const label = (document.title || '').replace(/^Averages\\s*[—-]\\s*/, '') || 'Assignment';\n      let trail = [];\n      try { trail = JSON.parse(sessionStorage.getItem(KEY) || '[]'); } catch {}\n      if (!Array.isArray(trail)) trail = [];\n      const last = trail[trail.length - 1];\n      if (last && last.href === here) last.label = label;                 // reload\n      else if (trail.length > 1 && trail[trail.length - 2].href === here) { trail.pop(); trail[trail.length - 1].label = label; } // went back\n      else trail.push({ href: here, label });\n      trail = trail.slice(-20);\n      try { sessionStorage.setItem(KEY, JSON.stringify(trail)); } catch {}\n\n      const btn = document.querySelector('.back-link');\n      const prev = trail[trail.length - 2];\n      if (!btn || !prev) return;\n      const fresh = btn.cloneNode(false);          // same button, minus old click handlers\n      fresh.removeAttribute('onclick');\n      const icon = btn.querySelector('svg');\n      if (icon) fresh.appendChild(icon.cloneNode(true));\n      const text = document.createElement('span');\n      text.textContent = 'Back to ' + prev.label;\n      fresh.appendChild(text);\n      fresh.addEventListener('click', () => { window.location.href = prev.href; });\n      btn.replaceWith(fresh);\n    })();\n  ";

export default function Page() {
  return (
    <LegacyPage
      title={TITLE}
      styleCss={STYLE_CSS}
      bodyHtml={BODY_HTML}
      scriptJs={SCRIPT_JS}
      requiresAuth={true}
      usesSavedTheme={true}
      hasUploads={false}
      externalScripts={[]}
      pageId={"assignment"}
    />
  );
}
